/* === lib/components/legal/authority-chain/authority-chain.styles.css === */
/* authority-chain — progression.timeline.structure
 *
 * Extracted from lib/_legacy.css in Phase 4 of the destination map.
 * See lib/components/authority-chain/authority-chain.manifest.json for the component contract.
 */

/* ── AUTHORITY-CHAIN ──────────────────────────────────────────────────
 * Hierarchy of legal authority: Statute → Regulation → Guidance → Case.
 *
 * <!-- _class: authority-chain -->
 * 1. Statute
 *    - `15 U.S.C. §6501`
 *    - COPPA, 1998 — verifiable parental consent for under-13 data.
 * 2. Regulation
 *    - `16 C.F.R. Part 312`
 *    - FTC implementing rule; 2013 rewrite expanded covered identifiers.
 *
 * Authoring contract: top-level li carries ONLY the tier label
 * (auto-bolded by slotLabelLift — author writes `1. Statute`, not
 * `1. **Statute**`). Nested ul carries body — first item is citation
 * chip (only-child <code>), remaining items are prose descriptor.
 *
 * Default = vertical chain with connectors. Variants:
 *   .pyramid    visual hierarchy by tier weight
 *   .branching  statute → multiple regs/cases (every nested item is a branch)
 *   .bracket    bracketed cards with strong connectors
 *   .trail      numbered horizontal trail with arrows
 * ──────────────────────────────────────────────────────────────────── */
section.authority-chain > .cell-stage { display:flex; flex-direction:column; }
section.authority-chain > .cell-stage > ol,
section.authority-chain > .cell-stage > ul {
  list-style:none; padding:0; margin:0;
  display:flex; flex-direction:column;
  /* flex:1 fills the stage; min-height:0 lets the chain shrink to the bounded stage
   * (flex cell-tree §6) — without it the list's min-height:auto floor kept the rows at
   * natural height and clipped the last tier on a 4-tier chain. */
  gap:var(--sp-md); flex:1; min-height:0; justify-content:center;
  counter-reset:auth;
}
section.authority-chain > .cell-stage > :is(ol, ul) > li {
  counter-increment:auth;
  position:relative;
  /* flex mirror of `grid-template-columns:14cqi 1fr`: a fixed tier-label rail + the body
   * filling the rest. flex-wrap lets the .branching variant drop its body to a full-width
   * second row (flex-basis:100%). */
  display:flex;
  flex-wrap:wrap;
  column-gap:var(--sp-md);
  align-items:center;
  /* border-box so the pyramid's explicit width:100%/84%/… rows include their border
   * and don't overflow the stage horizontally. */
  box-sizing:border-box;
  /* Rows distribute to fill the bounded stage; align-items:center keeps each tier's
   * content on the row midline as it grows. min-height:0 lets a dense chain compress
   * gracefully instead of overrunning the clip. */
  flex:1; min-height:0;
  padding:var(--sp-md) var(--sp-md);
  background:var(--bg-alt);
  border:1px solid var(--border);
  border-left:4px solid var(--tier-hue, var(--accent));
  border-radius:var(--radius-md);
  font-size:var(--fs-body);
  line-height:var(--lh-snug);
  color:var(--text-body);
}
section.authority-chain > .cell-stage > :is(ol, ul) > li::marker { content:''; }
/* Connector arrow between rows. */
section.authority-chain > .cell-stage > :is(ol, ul) > li:not(:last-child)::after {
  content:'';
  position:absolute;
  left:7cqi; bottom:calc(-1 * var(--sp-md));
  width:2px; height:var(--sp-md);
  background:var(--accent);
}
/* Tier hue rotation — Statute / Regulation / Guidance / Case. */
section.authority-chain > .cell-stage > :is(ol, ul) > li:nth-child(8n+1) { --tier-hue:var(--cat-4-mark); }
section.authority-chain > .cell-stage > :is(ol, ul) > li:nth-child(8n+2) { --tier-hue:var(--cat-1-mark); }
section.authority-chain > .cell-stage > :is(ol, ul) > li:nth-child(8n+3) { --tier-hue:var(--cat-6-mark); }
section.authority-chain > .cell-stage > :is(ol, ul) > li:nth-child(8n+4) { --tier-hue:var(--cat-3-mark); }
section.authority-chain > .cell-stage > :is(ol, ul) > li > strong:first-child {
  flex:0 0 14cqi;
  font-family:var(--font-mono);
  font-size:var(--fs-body);
  font-weight:700;
  letter-spacing:0.14em;
  text-transform:uppercase;
  color:var(--tier-hue, var(--accent));
}
section.authority-chain > .cell-stage > :is(ol, ul) > li > :is(ul, ol) {
  flex:1; min-width:0;
  list-style:none; padding:0; margin:0;
  display:flex; flex-direction:column; gap:var(--sp-xs);
}
section.authority-chain > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li::marker { content:''; }
section.authority-chain > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li:first-child:has(> code:only-child) > code {
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:600;
  color:var(--text-heading);
  background:none; border:none; padding:0;
  white-space:nowrap;
}

/* .pyramid — top is widest, each tier narrower. */
section.authority-chain.pyramid > .cell-stage > :is(ol, ul) {
  align-items:center;
}
section.authority-chain.pyramid > .cell-stage > :is(ol, ul) > li {
  width:100%;
  max-width:none;
  text-align:left;
  /* The pyramid is a SHAPE (decreasing-width tiers) — its rows stay content-height
   * and the group centres in the stage (ul justify-content:center), rather than the
   * base chain's flex:1 stretch which would balloon each tier and break the silhouette. */
  flex:0 1 auto;
}
section.authority-chain.pyramid > .cell-stage > :is(ol, ul) > li:nth-child(1) { width:100%; }
section.authority-chain.pyramid > .cell-stage > :is(ol, ul) > li:nth-child(2) { width:84%; }
section.authority-chain.pyramid > .cell-stage > :is(ol, ul) > li:nth-child(3) { width:68%; }
section.authority-chain.pyramid > .cell-stage > :is(ol, ul) > li:nth-child(4) { width:54%; }
section.authority-chain.pyramid > .cell-stage > :is(ol, ul) > li::after { display:none; }

/* .branching — statute root, then nested children render as connected branches. */
/* The branch list wraps to its own full-width row inside the flex-wrap li; the space
 * above it is the wrap row-gap (was margin-top on the list — an auto/edge margin sits
 * outside the flex content box and breaks the virtual-list height measurement). */
section.authority-chain.branching > .cell-stage > :is(ol, ul) > li {
  row-gap:var(--sp-sm);
}
section.authority-chain.branching > .cell-stage > :is(ol, ul) > li > :is(ul, ol) {
  flex:0 0 100%;
  list-style:none; margin:0; padding:0 0 0 var(--sp-lg);
  display:flex; flex-direction:column; gap:var(--sp-xs);
  border-left:2px dashed var(--tier-hue, var(--accent));
}
section.authority-chain.branching > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li {
  padding:var(--sp-xs) var(--sp-md);
  background:var(--bg);
  border:1px solid var(--border);
  border-radius:var(--radius-sm);
  font-size:var(--fs-meta);
  position:relative;
}
section.authority-chain.branching > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li::before {
  content:'';
  position:absolute;
  left:calc(-1 * var(--sp-lg)); top:50%;
  width:var(--sp-md); height:2px;
  background:var(--tier-hue, var(--accent));
}
section.authority-chain.branching > .cell-stage > :is(ol, ul) > li::after { display:none; }

/* .bracket — visual bracket connector tying tiers. */
section.authority-chain.bracket > .cell-stage > :is(ol, ul) { gap:0; }
section.authority-chain.bracket > .cell-stage > :is(ol, ul) > li {
  border-radius:0;
  border:1px solid var(--border);
  border-left:6px double var(--tier-hue, var(--accent));
}
section.authority-chain.bracket > .cell-stage > :is(ol, ul) > li::after { display:none; }
section.authority-chain.bracket > .cell-stage > :is(ol, ul) > li + li { border-top:none; }

/* .trail — horizontal numbered trail with arrows. */
section.authority-chain.trail > .cell-stage > :is(ol, ul) {
  flex-direction:row;
  gap:0; justify-content:space-between;
  align-items:stretch;
}
section.authority-chain.trail > .cell-stage > :is(ol, ul) > li {
  flex:1;
  display:flex; flex-direction:column; gap:var(--sp-xs);
  align-items:flex-start;
  border-left:none;
  border-top:4px solid var(--tier-hue, var(--accent));
  border-radius:0;
  padding:var(--sp-md);
  position:relative;
}
section.authority-chain.trail > .cell-stage > :is(ol, ul) > li::after {
  content:'→';
  display:block;
  position:absolute;
  right:calc(-0.5 * var(--sp-md)); top:50%;
  transform:translateY(-50%);
  background:none;
  width:auto; height:auto;
  font-size:var(--fs-h3);
  color:var(--accent);
  z-index:1;
}
section.authority-chain.trail > .cell-stage > :is(ol, ul) > li:last-child::after { display:none; }
section.authority-chain.trail > .cell-stage > :is(ol, ul) > li > strong:first-child {
  font-size:var(--fs-meta);
  letter-spacing:0.10em;
}
section.authority-chain.trail > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li:first-child:has(> code:only-child) > code {
  font-size:var(--fs-meta);
}
section.authority-chain.trail > .cell-stage > :is(ol, ul) > li::before {
  content:counter(auth, decimal-leading-zero);
  font-family:var(--font-mono);
  font-size:var(--fs-h2);
  font-weight:700;
  color:var(--tier-hue, var(--accent));
  line-height:1;
  padding-bottom:var(--sp-xs);
}

/* ── Box-local family reflow (2026-06-20-native-to-reflow-feasibility.md, Batch
   A1). The DEFAULT chain row is a `14cqi 1fr` tier-label | body grid; in a
   square/tall/strip box the 14cqi rail squeezes the label, so collapse each row
   to a single column — tier label over body. Scoped off the named variants
   (pyramid/branching/bracket also use the base row grid; trail is the horizontal
   one). The excluded variants keep their landscape shape for now — portrait
   handling for the variants is out of Batch A1 scope (tracked follow-up). Doubled
   class + the variant guards win on specificity. */
@container lattice (aspect-ratio <= 1.05) {
  /* Collapse the tier-label rail: the label fills row 1 (flex-basis:100%) so the body wraps
     onto its own line below — tier label over body. */
  section.authority-chain.authority-chain:not(.trail):not(.pyramid):not(.branching):not(.bracket) > .cell-stage > :is(ol, ul) > li {
    row-gap: var(--sp-xs);
    align-items: start;
    align-content: start;
  }
  section.authority-chain.authority-chain:not(.trail):not(.pyramid):not(.branching):not(.bracket) > .cell-stage > :is(ol, ul) > li > strong:first-child,
  section.authority-chain.authority-chain:not(.trail):not(.pyramid):not(.branching):not(.bracket) > .cell-stage > :is(ol, ul) > li > :is(ul, ol) {
    flex: 0 0 100%;
  }
}

/* ── Struck elevation (base.tokens.css --elevation-card) ── lift the cards; vertical
 * berth (padding-block, never margin — #20) so the stage's overflow:clip doesn't
 * shear the shadow. Shadow has no horizontal extent, so no horizontal berth. */
section.authority-chain > .cell-stage > :is(ol, ul) > li {
  box-shadow: var(--elevation-card);
}
section.authority-chain > .cell-stage {
  padding-block: var(--elevation-berth);
}

