section.compare-code:not(:has(.code-cols)):not(:has(> p ~ h2)) > p:nth-of-type(2) { grid-column:2; grid-row:2; }
section.compare-code:not(:has(.code-cols)):not(:has(> p ~ h2)) > pre:nth-of-type(1) { grid-column:1; grid-row:3; margin:0; }
section.compare-code:not(:has(.code-cols)):not(:has(> p ~ h2)) > pre:nth-of-type(2) { grid-column:2; grid-row:3; margin:0; }
section.compare-code:not(:has(.code-cols)):not(:has(> p ~ h2)) > blockquote         { grid-column:1 / -1; grid-row:4; padding-top:var(--sp-xs); }

/* ── WITH eyebrow (p>code precedes h2 among siblings) ── */
section.compare-code:not(:has(.code-cols)):has(> p ~ h2) {
  grid-template-rows:auto auto auto 1fr auto;
}
section.compare-code:not(:has(.code-cols)):has(> p ~ h2) > p:nth-of-type(1) { grid-column:1 / -1; grid-row:1; }
section.compare-code:not(:has(.code-cols)):has(> p ~ h2) > h2               { grid-column:1 / -1; grid-row:2; padding-bottom:var(--sp-sm); }
section.compare-code:not(:has(.code-cols)):has(> p ~ h2) > p:nth-of-type(2) { grid-column:1; grid-row:3; }
section.compare-code:not(:has(.code-cols)):has(> p ~ h2) > p:nth-of-type(3) { grid-column:2; grid-row:3; }
section.compare-code:not(:has(.code-cols)):has(> p ~ h2) > pre:nth-of-type(1) { grid-column:1; grid-row:4; margin:0; }
section.compare-code:not(:has(.code-cols)):has(> p ~ h2) > pre:nth-of-type(2) { grid-column:2; grid-row:4; margin:0; }
section.compare-code:not(:has(.code-cols)):has(> p ~ h2) > blockquote         { grid-column:1 / -1; grid-row:5; padding-top:var(--sp-xs); }

/* ── Cover-code carousel — compare-code's owned SPLIT forms ────────────────────
   Two labelled code blocks read across; code can't reflow into a row, so an overflowing
   compare-code re-authors into a title COVER then ONE code block per page at full width
   under its label (2026-06-23-read-across-carousel.md). lib/core/carousel.js emits
   `content compare-code-split compare-code-{cover,block} form`. Palette-blind. */
section.compare-code-cover {
  background: var(--accent); color: var(--on-accent);
  display: flex; flex-direction: column; justify-content: center; position: relative;
}
section.compare-code-cover .split-feat-eye { font-size: var(--fs-meta); letter-spacing: 0.2em; text-transform: uppercase; opacity: 0.85; }
section.compare-code-cover .split-feat-h {
