section.compare-code-block pre > code {
  font-family: var(--font-mono); font-size: var(--fs-body-compact); line-height: var(--lh-base);
  color: var(--code-text); background: none; padding: 0; display: block;
  white-space: pre-wrap; overflow-wrap: anywhere;
}

/* === lib/components/comparison/compare-prose/compare-prose.styles.css === */
/* compare-prose — extracted from lib/_legacy.css (batch 5).
