section.kpi.spotlight > .cell-stage > ol > li:nth-child(2) { grid-column: 2; grid-row: 1; }
section.kpi.spotlight > .cell-stage > ol > li:nth-child(3) { grid-column: 2; grid-row: 2; }
section.kpi.spotlight > .cell-stage > ol > li:nth-child(4) { grid-column: 2; grid-row: 3; }
section.kpi.spotlight > .cell-stage > ol > li:not(:first-child) {
  display: flex; flex-direction: column;
  justify-content: center;
  padding: 0;
}
section.kpi.spotlight > .cell-stage > ol > li:nth-child(2) { border-top: 1.5px solid var(--text-heading); }
section.kpi.spotlight > .cell-stage > ol > li:nth-child(3) { border-top: 1px solid var(--border); }
section.kpi.spotlight > .cell-stage > ol > li:nth-child(4) {
  border-top: 1px solid var(--border);
  border-bottom: 1.5px solid var(--text-heading);
}
section.kpi.spotlight > .cell-stage > ol > li:not(:first-child) > strong {
  font-size: var(--fs-emphasis);
}
section.kpi.spotlight > .cell-stage > ol > li:not(:first-child) > ul > li:first-child {
  padding-top: 0.15625cqi;
  font-size: var(--fs-body);
}
section.kpi.spotlight > .cell-stage > ol > li:not(:first-child) > ul > li + li {
  font-size: var(--fs-meta);
  padding-top: 0.15625cqi;
}
section.kpi.spotlight > .cell-stage > ol > li:not(:first-child) code {
  padding: 0.15625cqi 0.625cqi;
  font-size: var(--fs-meta);
}





/* ── Box-local family reflow (2026-06-18-component-adaptive-sizing.md) ──────
 * Every kpi variant (briefing, ops, spotlight, trajectory) places metric <li>s
 * on an explicit grid — a hero spanning rows + supports in a side column, or a
 * 2×2 matrix. In a square-or-narrower box that side-by-side composition is
 * cramped. Switching the metric list to a single flex COLUMN linearises every
 * variant at once: flex ignores the children's grid-column / grid-row, so the
 * hero stacks on top and the supports follow, full width — no per-variant
 * override. Keyed on the nearest `lattice` container's aspect, so it fires on a
 * portrait deck AND inside a narrow nested cell, replacing the data-orientation
 * stamp. `.kpi.kpi` (class doubled) lifts the selector to (0,2,2) so it matches
 * the per-variant grid rules' specificity (`section.kpi.spotlight > .cell-stage > ol`) and wins
 * on source order — the role the old `[data-orientation]` attribute played. */
@container lattice (aspect-ratio <= 1.05) {
  section.kpi.kpi > .cell-stage > ol,
  section.kpi.kpi > .cell-stage > ul {
    display: flex;
    flex-direction: column;
    /* The list keeps `flex: 1` (fills the slide below the title), so centre the
     * metrics WITHIN it — centring the section can't, the list absorbs the slack. */
    justify-content: center;
    gap: var(--sp-md);
    align-content: normal;
  }
  /* Demote the hero CARD to the lead row of a uniform ledger. The wide-grid
   * briefing hero is a full-width accent box with the supports in its right
   * column; linearised, that box keeps a dead right half AND eats the vertical
   * room a short square/portrait frame needs — so the 4th metric clipped. As a
   * hairline lead row (bigger number, no box) all four metrics read as one ledger
   * and fit. Scoped away from ops/compliance/trajectory, which are already uniform
   * grids/cards. (0,3,3) ties the briefing hero rules and wins on source order. */
  section.kpi.kpi:where(:not(.ops):not(.compliance):not(.trajectory)) > .cell-stage > ol > li:nth-child(1) {
    background: none;
    border-left: none;
    border-top: 1.5px solid var(--text-heading);
    padding: var(--sp-sm) 0;
  }
  section.kpi.kpi:where(:not(.ops):not(.compliance):not(.trajectory)) > .cell-stage > ol > li:nth-child(1)::after {
    content: none;
  }
  section.kpi.kpi:where(:not(.ops):not(.compliance):not(.trajectory)) > .cell-stage > ol > li:nth-child(1) > strong {
    font-size: var(--fs-h1);
    line-height: 1;
  }
  section.kpi.kpi:where(:not(.ops):not(.compliance):not(.trajectory)) > .cell-stage > ol > li:nth-child(1) > ul > li:first-child {
    font-family: var(--font-body);
    font-size: var(--fs-body);
    padding-top: var(--sp-3xs);
  }
}
/* Strip — the tallest/narrowest box (mobile @size; a nested strip cell): shed the
 * status pills, the lowest-priority unit (manifest `adapt.droppable`), so the
 * numbers and their labels own the narrow frame instead of crowding it. */
@container lattice (aspect-ratio <= 0.5) {
  section.kpi.kpi > .cell-stage > :is(ol,ul) li code { display: none; }
}

/* === lib/components/inventory/list/list.styles.css === */
/* list — inventory.stack.bullets
 *
 * An equal-fill ledger: the list fills the working area and every item takes
 * an equal share of the height with its content vertically centred, so the
 * slide reads edge-to-edge whether it carries three items or the layout's
 * max. Three registers share the spine:
 *   default        — accent-edged pills (a flat set of points)
 *   .takeaway      — hairline-ruled single lines (former tldr)
 *   .principles    — display-weight declarations + large counter (former principles)
 *
 * Type steps up to the message scale (principles to the emphasis/display
 * register); counters and text share a centreline so numbered rows read clean.
 *
 * See lib/components/inventory/list/list.manifest.json for the contract.
 */

section.list > .cell-stage { display:flex; flex-direction:column; }

/* ── Spine: the list fills the canvas; each row an equal, centred band. ── */
section.list > .cell-stage > :is(ul,ol) {
  list-style:none; padding:0; margin:0;
  display:flex; flex-direction:column;
  flex:1; gap:var(--sp-sm);
}
section.list > .cell-stage > :is(ul,ol) > li {
  flex:1 1 0; min-height:0;
  display:flex; align-items:center;
  font-size:var(--fs-message);
  color:var(--text-body); line-height:var(--lh-snug);
}

/* ── Default register: accent-edged pills. ── */
section.list > .cell-stage > ul > li {
  background:var(--bg-alt);
  border:1px solid var(--border); border-left:3px solid var(--accent);
  border-radius:var(--radius-md);
  padding:var(--sp-sm) var(--sp-md);
}
/* Optional second-line detail under a point. */
section.list > .cell-stage > ul > li > ul { list-style:none; margin:0; padding:0; }
section.list > .cell-stage > ul > li > ul > li {
  font-size:var(--fs-body-compact); color:var(--text-label);
  line-height:var(--lh-snug); background:none; border:none; padding:0;
}
/* Default ordered: leading accent counter, content centred. */
section.list > .cell-stage > ol { counter-reset:list-counter; }
section.list > .cell-stage > ol > li {
  counter-increment:list-counter;
  background:var(--bg-alt); border:1px solid var(--border);
  border-radius:var(--radius-md); padding:var(--sp-sm) var(--sp-md);
  /* flex mirror of `grid-template-columns:var(--sp-xl) 1fr` — fixed-width counter,
   * point fills the rest (flex shop §10). */
  display:flex; align-items:center; gap:var(--sp-md);
}
section.list > .cell-stage > ol > li::before {
  content:counter(list-counter, decimal-leading-zero);
  flex:0 0 var(--sp-xl);
  font-family:var(--font-label); font-size:var(--fs-h4); font-weight:700; color:var(--accent);
}

/* ── takeaway register — former `tldr` component (inventory.list.takeaway) ──
 * Hairline-ruled single lines, no pill chrome. `numbered` adds a large
 * accent counter on the same centreline. Merged 2026-06-07. */
section.list.takeaway > .cell-stage > :is(ul,ol) { gap:0; }
section.list.takeaway > .cell-stage > :is(ul,ol) > li {
  background:none; border:none; border-radius:0;
  border-bottom:1px solid var(--border);
  padding:0 var(--sp-xs);
  font-size:var(--fs-message); font-weight:500; color:var(--text-heading);
}
section.list.takeaway > .cell-stage > :is(ul,ol) > li::before { content:none; }
section.list.takeaway > .cell-stage > :is(ul,ol) > li::marker { content:''; }
section.list.takeaway > .cell-stage > :is(ul,ol) > li:last-child { border-bottom:none; }
/* numbered — accent counter as a fixed leading column, centred with the text. */
section.list.takeaway.numbered > .cell-stage > :is(ul,ol) > li { counter-increment:list-take-counter; gap:var(--sp-md); }
section.list.takeaway.numbered > .cell-stage > :is(ul,ol) { counter-reset:list-take-counter; }
section.list.takeaway.numbered > .cell-stage > :is(ul,ol) > li::before {
  content:counter(list-take-counter, decimal-leading-zero);
  font-family:var(--font-label); font-size:var(--fs-emphasis); font-weight:700;
  letter-spacing:0.02em; color:var(--accent); line-height:1;
  flex:0 0 auto; min-width:2.4em;
}

/* ── principles register — former `principles` component (inventory.list.principles) ──
 * Display-weight declarations with a large accent counter. ol only;
 * lettered/roman/bullet switch the counter format. Merged 2026-06-07. */
section.list.principles > .cell-stage > ol { counter-reset:list-principle-counter; gap:0; }
section.list.principles > .cell-stage > ol > li {
  counter-increment:list-principle-counter;
  /* flex mirror of `grid-template-columns:auto 1fr` — natural-width counter, declaration
   * fills the rest. */
  display:flex; column-gap:var(--sp-lg); align-items:center;
  background:none; border:none; border-radius:0;
  border-bottom:1px solid var(--border); padding:0;
  font-family:var(--font-display, var(--font-body));
  font-size:var(--fs-emphasis); font-weight:500; letter-spacing:-0.01em;
  line-height:var(--lh-tight); color:var(--text-heading);
}
section.list.principles > .cell-stage > ol > li:last-child { border-bottom:none; }
section.list.principles > .cell-stage > ol > li::before {
  content:counter(list-principle-counter, decimal-leading-zero);
  font-family:var(--font-label); font-size:var(--fs-h1); font-weight:700;
  letter-spacing:0.02em; color:var(--accent); line-height:1; align-self:center;
}
section.list.principles.lettered > .cell-stage > ol > li::before { content:counter(list-principle-counter, upper-alpha); }
section.list.principles.roman > .cell-stage > ol > li::before { content:counter(list-principle-counter, upper-roman); }
section.list.principles.bullet > .cell-stage > ol > li::before { content:'·'; }

/* ── Box-local family reflow (engineering/decisions/2026-06-18-component-adaptive-sizing.md).
   Keyed on the nearest `lattice` container's aspect, so it fires on a portrait deck
   (the section is tall) AND inside a narrow nested cell — replacing the deck-wide
   data-orientation stamp. Square and narrower de-balloon: keep each row CONTENT-height
   and distribute the set by rhythm, instead of flex:1 1 0 inflating one line of text
   into a ~640px band on a tall frame. Fill comes from space-evenly + the social type. */
/* `.list.list` (class doubled) reaches (0,2,2) to match the original
   `[data-orientation]` reflow's specificity, so the takeaway/principles registers
   (whose variant rules are (0,2,N)) still de-balloon — the role the attribute played. */
@container lattice (aspect-ratio <= 1.05) {
  section.list.list > .cell-stage > :is(ul,ol) { justify-content: space-evenly; }
  section.list.list > .cell-stage > :is(ul,ol) > li { flex: 0 0 auto; }
}
/* Strip — the tallest/narrowest box (mobile @size; a nested strip cell): open the
   rhythm so the de-ballooned rows breathe down the long frame instead of clustering. */
@container lattice (aspect-ratio <= 0.5) {
  section.list.list > .cell-stage > :is(ul,ol) { gap: var(--sp-md); }
}

/* ── Struck elevation (base.tokens.css --elevation-card) ── lift the cards; vertical
 * berth (padding-block, never margin — #20) so the stage's overflow:clip doesn't
 * shear the shadow. Shadow has no horizontal extent, so no horizontal berth. */
section.list > .cell-stage > ul > li,
section.list > .cell-stage > ol > li {
  box-shadow: var(--elevation-card);
}
section.list > .cell-stage {
  padding-block: var(--elevation-berth);
}

/* === lib/components/progression/list-criteria/list-criteria.styles.css === */
/* list-criteria — extracted from lib/_legacy.css (batch 4).
 * See lib/components/list-criteria/list-criteria.manifest.json for the component contract.
 */

/* ── CRITERIA ──
 * ## heading  ol or ul — li title (lifted to <strong> automatically by
 * slotLabelLift — authors need not type `**…**`) [optional nested ul > li description]
 * CSS counter provides leading-zero number (01 02…) regardless of list type.
 * Use ul when order is semantic-free; ol when order carries meaning.
 */
/* Stage cell (flex cell-tree §6): the criteria list is flex:1 per item, so the
 * stage must be a flex column for the items to fill the bounded cell. */
section.list-criteria > .cell-stage { display:flex; flex-direction:column; min-height:0; }

section.list-criteria > .cell-stage > :is(ol, ul) {
  list-style:none; counter-reset:crit-counter;
  display:flex; flex-direction:column; gap:var(--sp-sm);
  flex:1; justify-content:space-between; margin:0; padding:0;
}
section.list-criteria > .cell-stage > :is(ol, ul) > li {
  counter-increment:crit-counter;
  display:flex; align-items:center; gap:var(--sp-md); flex:1;
  container-type:size;
}
section.list-criteria > .cell-stage > :is(ol, ul) > li::before {
  content:counter(crit-counter, decimal-leading-zero);
  flex-shrink:0; align-self:stretch;
  display:flex; align-items:center; justify-content:center;
  font-family:var(--font-label); font-size:55cqh; font-weight:700;
  color:var(--accent); line-height:1;
}
section.list-criteria .crit-body {
  flex:1; display:flex; flex-direction:column; justify-content:center;
  font-size:var(--fs-body); font-weight:700; color:var(--text-heading);
}
section.list-criteria .crit-body > strong { font-weight:inherit; color:inherit; }
section.list-criteria .crit-body ul {
  list-style:none; padding:4px 0 0 0; margin:0;
  font-size:var(--fs-body); font-weight:400; color:var(--text-body);
}
section.list-criteria .crit-body ul li {
  font-size:inherit; font-weight:inherit; color:inherit; line-height:var(--lh-base);
  counter-increment:none;
}
section.list-criteria .crit-body ul li::before { display:none; content:none; }

/* ── CRITERIA ────────────────────────────────────────────────────────────────
 * li > strong + ul siblings (no .crit-body wrapper) — bare-renderer fallback (e.g. a raw
 * VS Code markdown preview that skips the post-processor). Our engine ALWAYS emits
 * .crit-body, so this path never ships; it only keeps the markdown legible in a bare
 * renderer. Flex, not grid (flex shop §10): the index is an absolutely-positioned left
 * gutter and the strong + ul stack in a centred column beside it — the marker spanning both
 * text lines is what a grid row-span did, here done with absolute placement. */
section.list-criteria:not(:has(.crit-body)) > .cell-stage > :is(ol, ul) > li {
  display:flex; flex-direction:column; justify-content:center;
  position:relative; padding-left:2.6em; gap:4px;
  font-size:var(--fs-body); font-weight:700; color:var(--text-heading);
}
section.list-criteria:not(:has(.crit-body)) > .cell-stage > :is(ol, ul) > li::before {
  position:absolute; left:0; top:0; bottom:0; width:2em;
  display:flex; align-items:center; justify-content:center;
  font-size:var(--fs-h2);
}
section.list-criteria:not(:has(.crit-body)) > .cell-stage > :is(ol, ul) > li > strong {
  display:block; font-weight:inherit; color:inherit;
}
section.list-criteria:not(:has(.crit-body)) > .cell-stage > :is(ol, ul) > li > ul {
  list-style:none; padding:0; margin:0;
  font-size:var(--fs-body); font-weight:400; color:var(--text-body);
}
section.list-criteria:not(:has(.crit-body)) > .cell-stage > :is(ol, ul) > li > ul li { font-size:inherit; font-weight:inherit; color:inherit; line-height:var(--lh-base); }
section.list-criteria:not(:has(.crit-body)) > .cell-stage > :is(ol, ul) > li > ul li::before { display:none; content:none; }

/* === lib/components/progression/list-steps/list-steps.styles.css === */
/* list-steps — extracted from lib/_legacy.css (batch 6).
 * See lib/components/list-steps/list-steps.manifest.json for the component contract.
 */

/* ── STEPS ──
 * ## heading  ol with: **Step N title** \n body text
 */
/* Stage cell (flex cell-tree §6): the body wraps in `.cell-stage`, so the stage
 * carries the flex-column context the strip `ol` (flex:1) needs to fill the bounded
 * cell. The `.timeline` variant overrides this with centring (below). */
section.list-steps > .cell-stage { display:flex; flex-direction:column; min-height:0; }
section.list-steps ol { list-style:none; counter-reset:step-counter; display:flex; gap:var(--sp-xl); flex:1; padding:0; margin:0; align-items:stretch; }
section.list-steps ol > li { counter-increment:step-counter; flex:1; background:var(--bg-alt); border:1px solid var(--border); border-radius:var(--radius-md); padding:var(--sp-md); display:flex; flex-direction:column; gap:var(--sp-xs); position:relative; font-size:var(--fs-body); line-height:var(--lh-snug); font-weight:700; color:var(--text-heading); }
section.list-steps ol > li:not(:last-child)::after {
  content:'';
  position:absolute;
  right:calc(-1 * var(--sp-xl) / 2);
  top:50%; transform:translate(50%, -50%);
  width:0; height:0;
  border-top:10px solid transparent;
  border-bottom:10px solid transparent;
  border-left:10px solid var(--border);
