}
section.list-steps ol > li::before { content:'STEP ' counter(step-counter, decimal-leading-zero); font-family:var(--font-label); font-size:var(--fs-meta); font-weight:700; letter-spacing:0.12em; text-transform:uppercase; color:var(--text-label); }
section.list-steps ol > li strong { display:block; }
section.list-steps ol > li p { font-size:var(--fs-body); color:var(--text-body); line-height:var(--lh-base); margin:0; }
section.list-steps ol > li:not(:has(> ul)) > p { flex:1; }
/* Nested list format: - body text under each step */
section.list-steps ol > li > ul { list-style:none; padding:0; margin:0; flex:1; }
section.list-steps ol > li > ul > li { font-size:var(--fs-body); color:var(--text-body); line-height:var(--lh-base); font-weight:400; }
section.list-steps ol > li > ul > li::before { display:none; content:none; }



/* ── List-steps family modifiers — appended Phase 7 ──
 * Layout-specific variants documented per the design proposal.
 */
/* ────────────────────────────────────────────────────────────────────────
 * Layout-specific modifiers — list-steps family
 * Reference: proposals.md §2.2 list-steps
 *
 * Renames the prefix word on the step badge ("STEP 01" → "PHASE 01") and
 * swaps the counter format. Two axes compose cleanly:
 *
 *   prefix word: phase · stage · milestone · rank · tier   (default: STEP)
 *   format     : lettered · roman                          (default: decimal-leading-zero)
 *
 * The prefix word lives in `--step-prefix` so any combination of class
 * flags resolves through the same three ::before rules, one per format.
 * `vertical` switches the strip from a horizontal flex row to a column
 * with a down-arrow connector.
 * ──────────────────────────────────────────────────────────────────────── */

section.list-steps.phase     { --step-prefix: 'PHASE '; }
section.list-steps.stage     { --step-prefix: 'STAGE '; }
section.list-steps.milestone { --step-prefix: 'MILESTONE '; }
section.list-steps.rank      { --step-prefix: 'RANK '; }
section.list-steps.tier      { --step-prefix: 'TIER '; }

section.list-steps:is(.phase, .stage, .milestone, .rank, .tier) ol > li::before {
  content: var(--step-prefix) counter(step-counter, decimal-leading-zero);
}
section.list-steps.lettered ol > li::before {
  content: var(--step-prefix, 'STEP ') counter(step-counter, upper-alpha);
}
section.list-steps.roman ol > li::before {
  content: var(--step-prefix, 'STEP ') counter(step-counter, upper-roman);
}

/* vertical: stack steps as rows instead of columns. The horizontal
 * right-pointing connector arrow becomes a down-pointing arrow centered
 * on the bottom edge of each non-last card. Cards size to content rather
 * than stretching equally so a 3-4 step deck fits the canvas. */
section.list-steps.vertical ol {
  flex-direction: column;
  gap: var(--sp-md);
  align-items: stretch;
  flex: 0 1 auto;
}
section.list-steps.vertical ol > li {
  flex: 0 0 auto;
}
section.list-steps.vertical ol > li:not(:last-child)::after {
  right: 50%;
  top: auto;
  bottom: calc(-1 * var(--sp-md) / 2);
  transform: translate(50%, 50%);
  border-top: 10px solid var(--border);
  border-bottom: none;
  border-left: 10px solid transparent;
  border-right: 10px solid transparent;
}


/* ── timeline variant — former `timeline` component (progression.list-steps.timeline) ──
 * Dots-on-a-spine: ordered stages as labelled nodes along one horizontal axis.
 * ol → numbered discs; ul → plain dots. Resets the list-steps card + STEP-badge
 * + arrow-connector chrome. Merged from the standalone timeline on 2026-06-07.
 * Lifted to <strong> by the timeline token in the shared slot-label-lift paths. */
section.list-steps.timeline > .cell-stage { display:flex; flex-direction:column; justify-content:center; align-items:center; }
/* The heading is framing text — it follows the headline-alignment seam (`headline:`) via its
 * own align-self, leaving the centered timeline body below untouched. `auto` → center (byte-
 * identical). */
section.list-steps.timeline h2 { text-align:var(--headline-align, center); align-self:var(--headline-justify, center); }
/* CONSISTENT-DEFAULTS: the timeline centers its heading + spine, so its WHOLE masthead framing
 * centers to match. The lede is a flex column (masthead-lede.css); override its fallbacks to
 * `center` so the eyebrow, heading, and heading-rule <hr> center as one cluster by default.
 * Per-selector fallback → `headline: left` still overrides. The rule <hr> follows the cluster
 * automatically (flex child) — no per-component rule handling, no bay-drift. */
section.form.list-steps.timeline .cell-masthead .masthead-lede { text-align:var(--headline-align, center); align-items:var(--headline-justify, center); }
/* The optional dek/subtitle sits in the centered stage; it's framing text too, so wire it to the
 * seam (align-self, since the stage is a flex column — its `align-items:center` would otherwise
 * strand it centered under `headline: left` while the heading + eyebrow move). `auto` → the
 * fallback `center`, byte-identical; `head-left` moves it left with the rest of the cluster. */
section.list-steps.timeline > .cell-stage > p { text-align:var(--headline-align, center); align-self:var(--headline-justify, center); }
section.list-steps.timeline > .cell-stage > :is(ol,ul) {
  display:flex; justify-content:space-between; align-items:flex-start;
  width:100%; position:relative; flex:0 1 auto;
  padding:0 var(--sp-xl); gap:0; box-sizing:border-box; margin:0;
}
section.list-steps.timeline > .cell-stage > :is(ol,ul)::before {
  content:''; position:absolute; top:1.015625cqi;
  left:calc(var(--sp-xl) + 7.03125cqi); right:calc(var(--sp-xl) + 7.03125cqi);
  height:3px; background:var(--spectrum-structure); border-radius:2px;
}
section.list-steps.timeline > .cell-stage > :is(ol,ul) > li {
  flex:0 0 auto;
  display:flex; flex-direction:column; align-items:center;
  width:14.0625cqi; text-align:center; position:relative; z-index:1;
  background:none; border:none; border-radius:0; padding:0;
  font-size:var(--fs-meta); line-height:var(--lh-snug); font-weight:700; color:var(--text-heading);
}
section.list-steps.timeline > .cell-stage > ol { counter-reset:ls-timeline-counter; }
section.list-steps.timeline > .cell-stage > ol > li::before {
  counter-increment:ls-timeline-counter;
  content:counter(ls-timeline-counter);
  display:flex; align-items:center; justify-content:center;
  width:2.03125cqi; height:2.03125cqi; border-radius:50%;
  background:var(--accent); color:var(--on-accent, var(--on-dark-primary));
  font-family:var(--font-label); font-size:var(--fs-meta); font-weight:700; line-height:1;
  flex-shrink:0;
}
section.list-steps.timeline > .cell-stage > ul > li::before {
  content:''; display:block; width:2.03125cqi; height:2.03125cqi; border-radius:50%;
  background:var(--accent); border:3px solid var(--bg);
  box-shadow:0 0 0 1px var(--border); flex-shrink:0;
}
section.list-steps.timeline > .cell-stage > :is(ol,ul) > li:not(:last-child)::after { content:none; }
section.list-steps.timeline > .cell-stage > :is(ol,ul) > li > strong { display:block; padding-top:1.09375cqi; padding-bottom:0.3125cqi; }
section.list-steps.timeline > .cell-stage > :is(ol,ul) > li > :is(ul,ol) { list-style:none; padding:0; margin:0; }
section.list-steps.timeline > .cell-stage > :is(ol,ul) > li > :is(ul,ol) > li { font-weight:400; }
section.list-steps.timeline > .cell-stage > :is(ol,ul) > li > :is(ul,ol) > li em { font-size:var(--fs-meta); color:var(--text-body); line-height:var(--lh-snug); font-style:normal; }

/* ── chevron · converge · ghost — vertical staged-flow variants ──
 * Three looks for a labelled argument cascading DOWN the frame (Problem →
 * Vision → … → Plan), each riding the same list-steps DOM: `li > strong` is the
 * stage label (slot-label-lifted from the nested `- Title`), `li > ul > li` is
 * the one-line description. Added 2026-07-06 from the chevron-cascade design
 * bake-off (engineering/decisions/2026-07-06-vertical-staged-flow.md).
 *   chevron  — accent down-chevron tab + accent-keyed description card (the
 *              boardroom-cleaned version of the reference deck).
 *   converge — one continuous tapering silhouette narrowing onto the last
 *              stage; colour deepens top→bottom (the qualitative sibling of the
 *              value-driven chart `funnel`). Built for 4 stages (3–4 ideal).
 *   ghost    — editorial: faint chevron watermark, eyebrow label, hero body.
 * Self-contained: each establishes the vertical column itself, so
 * `<!-- _class: list-steps chevron -->` needs no companion `vertical`. */

/* shared: centre the flow, stack as a column, strip the default card + STEP
 * badge (::before) + right-arrow connector (::after) chrome. */
section.list-steps:is(.chevron, .converge, .ghost) > .cell-stage { justify-content:center; }
section.list-steps:is(.chevron, .converge, .ghost) ol { flex-direction:column; align-items:stretch; flex:0 1 auto; }
section.list-steps:is(.chevron, .converge, .ghost) ol > li { flex:0 0 auto; border:none; background:none; padding:0; font-weight:400; }
section.list-steps:is(.chevron, .converge, .ghost) ol > li::before { content:none; }
section.list-steps:is(.chevron, .converge, .ghost) ol > li::after  { content:none; }
section.list-steps:is(.chevron, .converge, .ghost) ol > li > ul { list-style:none; padding:0; }

/* chevron — accent down-chevron tab carries the label; a bordered card holds the
 * description, tied to the tab by a solid accent left key. The chevron point aims
 * at the next row so the eye reads a cascade. */
section.list-steps.chevron ol { gap:1.4cqi; }
section.list-steps.chevron ol > li {
  display:grid; grid-template-columns:16cqi 1fr; gap:2cqi; align-items:stretch; min-height:7.4cqi;
}
section.list-steps.chevron ol > li > strong {
  display:flex; align-items:center; justify-content:center; text-align:center;
  background:var(--accent); color:var(--on-accent);
  font-family:var(--font-label); font-size:var(--fs-h5); font-weight:700;
  letter-spacing:0.05em; text-transform:uppercase;
  padding:0 1cqi 2cqi;
  clip-path:polygon(0 0, 100% 0, 100% 66%, 50% 100%, 0 66%);
}
section.list-steps.chevron ol > li > ul {
  display:flex; flex-direction:column; justify-content:center;
  background:var(--bg-alt); border:1px solid var(--border); border-left:0.7cqi solid var(--accent);
  padding:1cqi 2.2cqi;
}
section.list-steps.chevron ol > li > ul > li { font-size:var(--fs-body); color:var(--text-body); line-height:var(--lh-snug); }

/* converge — every band is full-width, clipped to a trapezoid whose edges sit on
 * two continuous converging diagonals; stacked at gap:0 the clips read as ONE
 * funnel narrowing onto the final stage, capped by a spout point (ol::after).
 * Colour deepens in four steps via color-mix. Geometry is authored for 4 bands;
 * a 3rd/4th+ band degrades to the narrowest trapezoid rather than breaking. */
section.list-steps.converge ol { gap:0; width:100%; }
section.list-steps.converge ol > li {
  display:flex; flex-direction:column; align-items:center; justify-content:center;
  text-align:center; gap:0.4cqi; width:100%; box-sizing:border-box; padding-block:1.5cqi;
}
section.list-steps.converge ol > li:nth-child(1)    { clip-path:polygon(0% 0,     100% 0,     93.25% 100%, 6.75% 100%);  padding-inline:6cqi;  background:var(--accent-soft); }
section.list-steps.converge ol > li:nth-child(2)    { clip-path:polygon(6.75% 0,  93.25% 0,   86.5% 100%,  13.5% 100%);  padding-inline:13cqi; background:color-mix(in srgb, var(--accent) 32%, var(--accent-soft)); }
section.list-steps.converge ol > li:nth-child(3)    { clip-path:polygon(13.5% 0,  86.5% 0,    79.75% 100%, 20.25% 100%); padding-inline:19cqi; background:color-mix(in srgb, var(--accent) 66%, var(--accent-soft)); }
section.list-steps.converge ol > li:nth-child(n+4)  { clip-path:polygon(20.25% 0, 79.75% 0,   73% 100%,    27% 100%);    padding-inline:25cqi; background:var(--accent); }
section.list-steps.converge ol > li:nth-child(-n+2) :is(strong, ul li) { color:var(--accent-soft-body); }
section.list-steps.converge ol > li:nth-child(n+3)  :is(strong, ul li) { color:var(--on-accent); }
section.list-steps.converge ol > li > strong {
  font-family:var(--font-label); font-size:var(--fs-h5); font-weight:700;
  text-transform:uppercase; letter-spacing:0.05em;
}
section.list-steps.converge ol > li > ul > li { font-size:var(--fs-body); line-height:var(--lh-snug); }
section.list-steps.converge ol::after {
  content:""; width:100%; height:3.6cqi; background:var(--accent);
  clip-path:polygon(27% 0, 73% 0, 50% 100%);
}

/* ghost — a large faint chevron watermarks each row; the label is a small accent
 * eyebrow and the description is the hero in heading type. Hairline rules imply
 * the flow. Maximum restraint, maximum type. */
section.list-steps.ghost ol { gap:0; }
section.list-steps.ghost ol > li { position:relative; padding:1.55cqi 0 1.55cqi 9cqi; }
section.list-steps.ghost ol > li + li { border-top:1px solid var(--border); }
section.list-steps.ghost ol > li::before {
  content:''; position:absolute; left:1.2cqi; top:50%; transform:translateY(-50%);
  width:6.2cqi; height:6.2cqi; background:var(--accent); opacity:0.12;
  clip-path:polygon(50% 88%, 0 34%, 14% 20%, 50% 60%, 86% 20%, 100% 34%);
}
section.list-steps.ghost ol > li > strong {
  display:block; font-family:var(--font-label); font-size:var(--fs-meta); color:var(--accent);
  font-weight:700; text-transform:uppercase; letter-spacing:0.18em; line-height:var(--lh-snug);
  padding-bottom:0.7cqi;
}
section.list-steps.ghost ol > li > ul > li {
  font-size:var(--fs-h4); color:var(--text-heading); font-weight:400; line-height:var(--lh-snug);
}

/* ── Box-local family reflow (engineering/decisions/2026-06-18-component-adaptive-sizing.md).
   The default strip is a horizontal flex row of step cards with right-pointing
   connectors; in a tall box those columns crush. Apply the existing `vertical`
   treatment automatically — stack the cards down the frame, content-height, with a
   down-pointing connector on the bottom edge. Keyed on the nearest `lattice`
   container's aspect (a portrait deck OR a narrow nested cell). `:not(.timeline)`
   spares the dots-on-a-spine variant (its own layout); the `:not()` also lifts the
   selector to (0,3,2) so it clears the equal-weight variant rules cleanly. Boundary
   is `≤ 0.9` (tall + strip): a square box fits neither the horizontal row (it
   overflows) nor 3–4 full cards stacked (also overflows), so `square` is left out of
   `adapt.families` and the vertical stack fires only on the taller frames. */
@container lattice (aspect-ratio <= 0.9) {
  section.list-steps.list-steps:not(.timeline):not(.chevron):not(.converge):not(.ghost) ol {
    flex-direction: column; gap: var(--sp-md); align-items: stretch; flex: 0 1 auto;
  }
  section.list-steps.list-steps:not(.timeline):not(.chevron):not(.converge):not(.ghost) ol > li { flex: 0 0 auto; }
  section.list-steps.list-steps:not(.timeline):not(.chevron):not(.converge):not(.ghost) ol > li:not(:last-child)::after {
    right: 50%; top: auto; bottom: calc(-1 * var(--sp-md) / 2);
    transform: translate(50%, 50%);
    border-top: 10px solid var(--border); border-bottom: none;
    border-left: 10px solid transparent; border-right: 10px solid transparent;
  }
}

/* ── Struck elevation (base.tokens.css --elevation-card) ── lift the cards; vertical
 * berth (padding-block, never margin — #20) so the stage's overflow:clip doesn't
 * shear the shadow. Shadow has no horizontal extent, so no horizontal berth. */
section.list-steps ol > li {
  box-shadow: var(--elevation-card);
}
section.list-steps > .cell-stage {
  padding-block: var(--elevation-berth);
}

/* === lib/components/inventory/list-tabular/list-tabular.styles.css === */
/* list-tabular — extracted from lib/_legacy.css (batch 6).
 * See lib/components/list-tabular/list-tabular.manifest.json for the component contract.
 */

/* ── LIST-TABULAR ──────────────────────────────────────────────────────────
 * Ordered tabular list — counter | name | description | meta per row.
 * Default look is hairline-ruled rows, display-serif name, mono uppercase
 * meta. Counter sits at fs-md on the name baseline.
 *
 * Authoring contract (same across base + all variants):
 *
 *   N. Name `Meta string`
 *      - Description sentence.
 *
 * The inline code is the meta — adjacent to the name in source because
 * that's what it qualifies. CSS pulls it into the right column at render.
 *
 * Visual variants (mutually exclusive — pick one or none):
 *
 *   (none)    Default — hairline ledger; display-serif name; mono meta
 *   def       Editorial — big counter spans rows, eyebrow above name
 *   metric    Meta renders as a tile on the right
 *   spec      Mono name as a key (technical-reference feel)
 *   register  Meta renders as an accent-soft pill
 *
 * Fine-tuning modifiers (compose with the variant above):
 *
 *   compact   Tighter row padding (any variant)
 *   rule      def: full-height accent rail down the ol's left edge
 *   solid     metric: filled accent tile instead of bordered
 *   stacked   spec: description on its own row beneath the name; counter
 *               scales up and spans both rows
 *   outline   register: hairline-bordered tag instead of filled pill
 *
 * Counter sizing rule across the family: counter size scales with item
 * height. Single-row items → fs-md (paired with the name baseline).
 * Multi-row items (def, spec.stacked) → fs-2xl, spans rows, centered.
 * ───────────────────────────────────────────────────────────────────────── */

/* ── Base (default = hairline ledger) ─────────────────────────────────── */
section.list-tabular ol {
  list-style:none; counter-reset:tabular-counter;
  padding:0; margin:0;
  display:flex; flex-direction:column;
}
section.list-tabular ol > li {
  counter-increment:tabular-counter;
  display:grid;
  /* col 4 (metadata) is bounded minmax, not auto: long legacy metadata
   * must wrap within its share, never expand the track off the slide edge. */
  grid-template-columns:3.4375cqi 15.625cqi 1fr minmax(0, 0.9fr);
  align-items:baseline;
  column-gap:var(--sp-md);
  padding:var(--sp-sm) 0;
  border-bottom:1px solid var(--border);
  font-family:var(--font-display);
  font-size:var(--fs-body-compact);
  font-weight:700;
  color:var(--text-heading);
  letter-spacing:-0.01em;
  line-height:var(--lh-snug);
}
section.list-tabular ol > li:first-child { border-top:1px solid var(--border); }
section.list-tabular ol > li::before {
  content:counter(tabular-counter, decimal-leading-zero);
  font-family:var(--font-mono);
  font-size:var(--fs-body-compact);
  font-weight:700;
  color:var(--accent);
  letter-spacing:0.06em;
  align-self:baseline;
}
section.list-tabular ol > li > ul { display:contents; }
section.list-tabular ol > li > ul > li::marker { content:''; }
section.list-tabular ol > li > ul > li:first-child {
  grid-column:3; grid-row:1;
  font-family:var(--font-body);
  font-size:var(--fs-body-compact);
  font-weight:400;
  color:var(--text-body);
  letter-spacing:0;
}
/* Legacy italic-meta compatibility: when a second nested li is present
 * (the 3-line authoring contract), treat it as the meta column. The new
 * 2-line contract uses inline <code> instead and never produces a second
 * nested li. */
section.list-tabular ol > li > ul > li:nth-child(2) {
  grid-column:4; grid-row:1;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:600;
  color:var(--text-label);
  letter-spacing:0.08em;
  text-transform:uppercase;
  text-align:right;
  overflow-wrap:break-word;
}
section.list-tabular ol > li > ul > li:nth-child(2) em { font-style:normal; }
section.list-tabular ol > li > code {
  grid-column:4; grid-row:1;
  background:none;
  border:none;
  padding:0;
  border-radius:0;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:600;
  color:var(--text-label);
  letter-spacing:0.08em;
  text-transform:uppercase;
  text-align:right;
  overflow-wrap:break-word;
}

/* ── Variant: def (editorial) ─────────────────────────────────────────── */
section.list-tabular.def ol {
  gap:var(--sp-md);
  flex:1; justify-content:center;
}
section.list-tabular.def ol > li {
  grid-template-columns:5cqi 17.1875cqi 1fr;
  grid-template-rows:auto auto;
  row-gap:0.3125cqi;
  padding:0;
  border:none;
  font-family:var(--font-display);
  font-size:var(--fs-emphasis);
  font-weight:700;
  color:var(--text-heading);
  letter-spacing:-0.01em;
  line-height:var(--lh-tight);
}
section.list-tabular.def ol > li:first-child { border-top:none; }
section.list-tabular.def ol > li::before {
  grid-column:1; grid-row:1 / span 2;
  font-family:var(--font-display);
  font-size:var(--fs-h2);
  font-weight:700;
  color:var(--accent);
  line-height:1;
  letter-spacing:-0.02em;
  align-self:center;
  justify-self:start;
}
section.list-tabular.def ol > li > code {
  grid-column:2; grid-row:1;
  display:block;
  width:fit-content;
  margin:0;
  padding:0;
  background:none;
  border:none;
  border-radius:0;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:600;
  color:var(--text-secondary);
  letter-spacing:0.1em;
  text-transform:uppercase;
  text-align:left;
  white-space:nowrap;
  align-self:end;
  justify-self:start;
}
section.list-tabular.def ol > li > ul > li {
  grid-column:3; grid-row:1 / span 2;
  font-family:var(--font-body);
  font-size:var(--fs-body-compact);
  font-weight:400;
  color:var(--text-body);
  line-height:var(--lh-base);
  letter-spacing:0;
  align-self:center;
}

/* def.rule — single continuous full-height accent rail */
section.list-tabular.def.rule ol {
  border-left:4px solid var(--accent);
  padding-left:var(--sp-md);
}

/* ── Variant: metric (tile) ───────────────────────────────────────────── */
section.list-tabular.metric ol > li {
  align-items:center;
  font-family:var(--font-body);
  font-size:var(--fs-body-compact);
  font-weight:600;
  color:var(--text-heading);
  letter-spacing:-0.01em;
}
section.list-tabular.metric ol > li > code {
  background:var(--bg-alt);
  border:1px solid var(--border);
  border-radius:var(--radius-md);
  padding:0.46875cqi 1.09375cqi;
  font-family:var(--font-mono);
  font-size:var(--fs-body-compact);
  font-weight:700;
  color:var(--accent);
  letter-spacing:-0.01em;
  text-align:center;
  text-transform:none;
  align-self:center;
  min-width:7.8125cqi;
  white-space:nowrap;
}

/* metric.solid — filled accent tile */
section.list-tabular.metric.solid ol > li > code {
  background:var(--accent);
  border-color:var(--accent);
  color:var(--on-accent, var(--on-dark-primary));
}

/* ── Variant: spec (mono key) ─────────────────────────────────────────── */
/* minmax(0,…) on the flexible + trailing tracks (not bare 1fr/auto) lets the
 * columns shrink below their content so a long mono key / API path wraps
 * inside its cell instead of overflowing the slide edge (which corrupted the
 * trailing glyphs). overflow-wrap on the code makes the wrap point clean. */
section.list-tabular.spec ol > li {
  grid-template-columns:3.4375cqi minmax(0, 20.3125cqi) minmax(0, 1fr) minmax(0, 15.625cqi);
  font-family:var(--font-mono);
  font-size:var(--fs-body-compact);
  font-weight:600;
  color:var(--text-heading);
  letter-spacing:0;
}
section.list-tabular.spec ol > li > code {
  color:var(--accent);
  font-weight:700;
  min-width:0;
  overflow-wrap:anywhere;
}
/* The spec row carries TWO inline codes — the key name and the type. The base
 * rule sends every `> code` to column 4, which stacked them in one cell (the
 * "LATTICESTRENG" glyph pile-up). Place the key in the name column and the
 * type in the trailing column. */
section.list-tabular.spec ol > li > code:first-of-type { grid-column:2; grid-row:1; justify-self:start; }
section.list-tabular.spec ol > li > code:nth-of-type(2) { grid-column:4; grid-row:1; justify-self:start; }

/* spec.stacked — description below name; counter spans rows */
section.list-tabular.spec.stacked ol > li {
  grid-template-columns:3.4375cqi minmax(0, 1fr) minmax(0, 15.625cqi);
  grid-template-rows:auto auto;
  row-gap:var(--sp-xs);
  font-size:var(--fs-body-compact);
}
section.list-tabular.spec.stacked ol > li::before {
  grid-row:1 / span 2;
  align-self:center;
  font-size:var(--fs-h2);
  line-height:1;
  letter-spacing:-0.02em;
}
section.list-tabular.spec.stacked ol > li > ul > li {
  grid-column:2; grid-row:2;
}
section.list-tabular.spec.stacked ol > li > code {
  min-width:0;
  overflow-wrap:anywhere;
}
/* Two codes again: key name on row 1 next to the counter, type at the row-1
 * trailing edge; the description (nested ul) sits on row 2 (base stacked rule). */
section.list-tabular.spec.stacked ol > li > code:first-of-type { grid-column:2; grid-row:1; justify-self:start; align-self:baseline; }
section.list-tabular.spec.stacked ol > li > code:nth-of-type(2) { grid-column:3; grid-row:1; justify-self:end; align-self:baseline; }

/* ── Variant: register (pill) ─────────────────────────────────────────── */
section.list-tabular.register ol > li {
  align-items:center;
  font-family:var(--font-body);
  font-size:var(--fs-body-compact);
  font-weight:600;
  color:var(--text-heading);
}
section.list-tabular.register ol > li > code {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  line-height:1;
  background:var(--accent-soft);
  color:var(--accent);
  border:none;
  padding:var(--pill-pad-y) 1.09375cqi;     /* sanctioned: wide "stamp" padding */
  border-radius:var(--pill-radius);
  font-family:var(--pill-font);
  font-size:var(--pill-fs);
  font-weight:700;                  /* sanctioned: heavier stamp weight */
  letter-spacing:0.1em;             /* sanctioned: wide tracking pairs with the uppercase opt-in */
  text-transform:uppercase;
  text-align:center;
  white-space:nowrap;
  justify-self:end;
  align-self:center;
}

/* register.outline — hairline-bordered tag */
section.list-tabular.register.outline ol > li > code {
  background:transparent;
  border:1px solid var(--border);
  color:var(--text-label);
}

/* ── Universal modifier: compact ──────────────────────────────────────── */
section.list-tabular.compact ol > li { padding:var(--sp-xs) 0; }

/* ── Box-local family reflow (engineering/decisions/2026-06-18-component-adaptive-sizing.md).
   The row is a four-track grid (counter · name · description · meta); in a tall box
   those tracks crush to slivers and the meta wraps badly. Collapse the row to a
   block flow — the counter and name lead the line, the meta sits inline after the
   name, and the description drops to its own line beneath. (Block flow, not a grid
   re-track, because the name is a bare text node the grid can place only by source
   order — a block flow lays them out in that order without fighting it.) Keyed on
   the nearest `lattice` container's aspect; the doubled class `.list-tabular.list-
   tabular` reaches the variants' (0,2,N) weight and source order keeps it last. */
@container lattice (aspect-ratio <= 0.9) {
  section.list-tabular.list-tabular ol > li {
    display: block;
    grid-template-columns: none;
  }
  section.list-tabular.list-tabular ol > li::before {
    padding-right: var(--sp-sm);
  }
  /* meta code → inline after the name (no longer a right-aligned column). */
  section.list-tabular.list-tabular ol > li > code {
    display: inline-block;
    padding-left: var(--sp-sm);
    text-align: left;
  }
  /* description (nested list) → its own line below the name. */
  section.list-tabular.list-tabular ol > li > ul { display: block; }
  section.list-tabular.list-tabular ol > li > ul > li:first-child {
    display: block;
    padding-top: var(--sp-2xs);
  }
  /* the 3-line authoring contract carries meta as a second nested li (not inline
     `<code>`); in block flow its base `grid-column:4; text-align:right` would orphan
     it right-aligned, so left-align it onto its own line like the inline-code meta. */
  section.list-tabular.list-tabular ol > li > ul > li:nth-child(2) {
    display: block;
    text-align: left;
    padding-top: var(--sp-2xs);
  }
}

/* ── Cover-rows carousel — list-tabular's owned SPLIT forms ────────────────────
   An overflowing tabular list re-authors at export into a title COVER + the rows
   windowed on clean pages (2026-06-23-read-across-carousel.md; the cover→content
   finish picked for split-panel, reused for continuity). lib/core/carousel.js emits
   `content list-tabular-split list-tabular-{cover,points} form`. Palette-blind. */

/* Cover — the table title gets its own accent field (matching split-panel's cover). */
section.list-tabular-cover {
  background: var(--accent); color: var(--on-accent);
  display: flex; flex-direction: column; justify-content: center; position: relative;
}
section.list-tabular-cover .split-feat-eye {
  font-size: var(--fs-meta); letter-spacing: 0.2em; text-transform: uppercase; opacity: 0.85;
}
section.list-tabular-cover .split-feat-h {
  font-size: var(--fs-h1); font-weight: 800; line-height: var(--lh-tight);
  /* padding, not margin, for the eyebrow/lede breathing room — the cover is a flex
     column with no row-gap, so this inset reproduces the exact spacing while staying
     inside the measurable box. */
  color: var(--on-accent); padding: var(--sp-xs) 0 var(--sp-md); max-width: 12em;
}
section.list-tabular-cover .split-feat-lede {
  font-size: var(--fs-emphasis); line-height: var(--lh-snug); opacity: 0.92; max-width: 20em;
}

/* Row pages — the rows flow under a running header of the table title. */
section.list-tabular-points .split-runhead {
  font-size: var(--fs-meta); letter-spacing: 0.2em; text-transform: uppercase;
  color: var(--text-muted); border-bottom: 1px solid var(--border);
  padding-bottom: var(--sp-xs);
}
/* The gap below the runhead's underline rides as padding-top on the rows list (not a
   runhead margin-bottom, which would sit outside the box and below the border) — same
   --sp-xl value, fully measurable. */
section.list-tabular-points .split-pts {
  list-style: none; padding: var(--sp-xl) 0 0; margin: 0;
  display: flex; flex-direction: column; gap: var(--sp-lg);
}
section.list-tabular-points .split-pts > li { border-left: 3px solid var(--accent); padding-left: var(--sp-md); }
section.list-tabular-points .split-pt-t {
  display: block; font-weight: 800; color: var(--text-heading); font-size: var(--fs-h3);
  padding-bottom: var(--sp-3xs);
}
section.list-tabular-points .split-pt-b { color: var(--text-body); font-size: var(--fs-body); line-height: var(--lh-base); }

/* === lib/components/inventory/logo-wall/logo-wall.styles.css === */
/* logo-wall — a grid of brand / partner / funder marks as social proof.
 * See lib/components/inventory/logo-wall/logo-wall.manifest.json for the contract.
 *
 * Substance: prose. The author writes a bulleted list of inline images
 * (`- ![Brand](brand.svg)`); the engine renders `<ul><li><img></li></ul>`. The
 * logo-marks transform (lib/transformers/logo-marks.js) then rewrites each
 * `<img>` into a `<span class="logo-mark">` whose SVG rides as a CSS `mask` and
 * whose fill is a palette token — so the colour is OURS, not the asset's.
 *
 * Modifier model:
 *   logo-wall          4-column wall, marks in --text-secondary (default)
 *   logo-wall dense    6-column, smaller cells — a longer roster
 *   logo-wall color    per-mark categorical --cat-*-mark hues
 *   logo-wall dark     dark canvas — every token re-tones via light-dark()
 *
 * Because the fill is `var(--logo-ink)` (a token), the wall is AA on both
 * grounds and adapts to every theme + colour-mode for free — no per-mode filter.
 * The mask is alpha-based: a mark's negative space must be real transparency
 * (the SVGs are authored as silhouettes), and fill-opacity becomes tonal depth.
 *
 * Rules are UNLAYERED (no `@layer components` wrapper) to match every other
 * component file — broad @layer activation is blocked (see engineering/
 * cascade.md), so a wrapped file would lose to unlayered rules regardless
 * of specificity. */

section.logo-wall > .cell-stage {
  --logo-cols: 4;
  /* The mark band — every logo is contained within this height so the wall
   * tiles uniformly. The cell may grow TALLER than this when a mark carries an
   * optional caption (name + pill); the band only governs the mark itself. */
  --logo-cell-h: 9cqi;
  --logo-gap: var(--sp-2xl);
}

/* The headline block (eyebrow + h2) keeps its natural height at the top;
 * the wall grows to fill the remaining canvas and centres its rows. */
section.logo-wall > .cell-stage > ul {
  list-style: none;
  margin: 0;
  padding: 0;
  width: 100%;
  flex: 1 1 auto;
  /* flex mirror of `repeat(N,1fr)` (flex shop §11.A): N marks per row, the rows centred as a
   * cluster. `--logo-col-gap` feeds the per-cell width below so tiling stays exact even when
   * a reflow uses an asymmetric gap. */
  --logo-col-gap: var(--logo-gap);
  display: flex;
  flex-wrap: wrap;
  gap: var(--logo-gap);
  align-content: center;
  justify-content: center;
  align-items: center;
}

section.logo-wall > .cell-stage > ul > li {
  /* `width` (not a flex-shorthand calc basis, which renders unreliably) tiles N marks/row. */
  width: calc((100% - (var(--logo-cols) - 1) * var(--logo-col-gap)) / var(--logo-cols));
  flex: 0 0 auto;
  box-sizing: border-box;
  /* Column, not row: the optional caption (name + pill) stacks BELOW the mark and
   * centres, rather than landing to its right. `min-height` keeps caption-less
   * cells at the mark band so a mixed wall still tiles evenly; a captioned cell
   * grows past it and the outer flex `align-content:center` re-centres the rows. */
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--sp-xs);
  min-height: var(--logo-cell-h);
}

/* The mark is a token-coloured silhouette: its SVG rides as a CSS `mask` (the
 * logo-marks transform stamps `--logo-mask:url(...)` per mark) and its fill is a
 * palette token, so every mark resolves the SAME colour through `var(--token)` —
 * one cohesive wall that re-tones per theme and per colour-mode via `light-dark()`,
 * AA on both grounds. `--logo-ink` defaults to the AA `--text-secondary`; the
 * `color` variant overrides it per mark with categorical `--cat-*-mark` hues. */
section.logo-wall > .cell-stage > ul > li > .logo-mark {
  width: 100%;
  height: var(--logo-cell-h);
  -webkit-mask-image: var(--logo-mask);
  mask-image: var(--logo-mask);
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-position: center;
  mask-position: center;
  -webkit-mask-size: contain;
  mask-size: contain;
  background-color: var(--logo-ink, var(--text-secondary));
}

/* Export path: the emulator swaps the mask span for the mark's real `<svg>`
 * (CSS mask doesn't survive print-to-PDF). The SVG is authored `fill:
 * currentColor`, so it takes the SAME `--logo-ink` token via `color` — identical
 * colour to the preview, but a robust vector in every PDF viewer. Turn the
 * mask/background treatment off and let the inline svg paint instead. */
section.logo-wall > .cell-stage > ul > li > .logo-mark-svg {
  -webkit-mask-image: none;
  mask-image: none;
  background-color: transparent;
  color: var(--logo-ink, var(--text-secondary));
  display: flex;
  align-items: center;
  justify-content: center;
}
section.logo-wall > .cell-stage > ul > li > .logo-mark-svg > svg {
  width: 100%;
  height: 100%;
  display: block;
}

/* ── Optional caption: a name and/or a pill below the mark.
 * Authored as a nested list under the image:
 *   - ![Northwind](northwind.svg)
 *     - Northwind          ← name (plain text)
 *     - `Anchor partner`   ← pill (backticked → <code>)
 * Both optional, in any combination. Substance is prose, so this is pure
 * structure + CSS — no transform. The nested <ul> is a centred column; a plain
 * <li> is the name, a <code> inside an <li> is the pill chip. The universal
 * trailing-pill rule (base.modifiers.css) only reaches a FIRST-level `li > code`,
 * so the nested pill here is ours to place — centred, not right-anchored. */
section.logo-wall > .cell-stage > ul > li > ul {
  list-style: none;
  padding: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--sp-2xs);
}

/* The name — a restrained caption that stays subordinate to the mark, in the
 * same muted register so the wall still reads as one texture. */
section.logo-wall > .cell-stage > ul > li > ul > li {
  font-size: var(--fs-meta);
  font-weight: 500;
  letter-spacing: 0.01em;
  line-height: 1.2;
  color: var(--text-muted);
  text-align: center;
}

/* The pill — a metadata chip below the name. Reuses the universal `--pill-*`
 * geometry/tokens (base.tokens.css) so it matches every other pill in the deck,
 * but centred under the mark rather than pushed to a row's right edge. */
section.logo-wall > .cell-stage > ul > li > ul > li > code {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  font-family: var(--pill-font);
  font-size: var(--pill-fs);
  font-weight: var(--pill-weight);
  letter-spacing: var(--pill-tracking);
  color: var(--pill-fg, var(--text-muted));
  background: var(--pill-bg, transparent);
  border: 1px solid var(--pill-border, var(--text-muted));
  border-radius: var(--pill-radius);
  padding: var(--pill-pad-y) var(--pill-pad-x);
  white-space: nowrap;
}

/* Dense — more marks, smaller cells, tighter gaps. */
section.logo-wall.dense > .cell-stage {
  --logo-cols: 6;
  --logo-cell-h: 6.5cqi;
  --logo-gap: var(--sp-xl);
}

/* Color — per-mark on-palette hues. The marks are masks, so there are no real
 * brand colours to keep; instead each cell takes a categorical `--cat-*-mark`
 * token (saturated, AA on both grounds, `light-dark()`-adaptive), cycling 1..12
 * so adjacent marks differ. This is the palette-driven answer to "keep the hues"
 * — cohesive with every chart/diagram in the deck, and contrast-clean by token. */
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 1)  > .logo-mark { --logo-ink: var(--cat-1-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 2)  > .logo-mark { --logo-ink: var(--cat-2-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 3)  > .logo-mark { --logo-ink: var(--cat-3-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 4)  > .logo-mark { --logo-ink: var(--cat-4-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 5)  > .logo-mark { --logo-ink: var(--cat-5-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 6)  > .logo-mark { --logo-ink: var(--cat-6-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 7)  > .logo-mark { --logo-ink: var(--cat-7-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 8)  > .logo-mark { --logo-ink: var(--cat-8-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 9)  > .logo-mark { --logo-ink: var(--cat-9-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 10) > .logo-mark { --logo-ink: var(--cat-10-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 11) > .logo-mark { --logo-ink: var(--cat-11-mark); }
section.logo-wall.color > .cell-stage > ul > li:nth-child(12n + 12) > .logo-mark { --logo-ink: var(--cat-12-mark); }

/* Dark canvas needs no mark override: `--text-secondary` / `--cat-*-mark` and the
 * caption tokens (--text-muted, --pill-*) all resolve through `light-dark()`, so
 * the whole wall re-tones for the dark ground automatically. */

/* ── Box-local family reflow (engineering/decisions/2026-06-18-component-adaptive-sizing.md).
   A wide wall of marks letterboxes into a short band in a tall box — every mark
   shrinks and the canvas reads empty. Halve the column count so each mark keeps
   presence and the rows fill down the frame. Keyed on the nearest `lattice`
   container's aspect, so it fires on a portrait deck AND inside a narrow nested
   cell. NOTE: the column count must be set on the `> ul` GRID (a descendant) —
   a `@container` rule cannot restyle its own container element (the section), so
   overriding `--logo-cols` on the section is a silent no-op (the §11 constraint). */
@container lattice (aspect-ratio <= 0.9) {
  section.logo-wall.logo-wall > .cell-stage > ul {
    --logo-cols: 2;
    --logo-col-gap: var(--sp-xl);
    /* Cohesive centred cluster — the marks read as one wall held in the slide's
       middle, rather than scattered the full height of the frame. */
    align-content: center;
    row-gap: var(--sp-2xl);
    column-gap: var(--sp-xl);
  }
  /* dense carries twice the roster — keep it denser than the default wall. */
  section.logo-wall.dense > .cell-stage > ul { --logo-cols: 3; }
}

/* === lib/components/chart/map/map.styles.css === */
/* map — spatial choropleth / highlight chart (chart-family series member).
 * See lib/components/chart/map/map.manifest.json for the contract.
 *
 * The kernel (map.transform.js) emits a <div class="map-figure"> holding an
 * SVG basemap (one <path> per region) and a legend (swatch · name · value).
 * All colour lives here so the kernel stays palette-blind: choropleth regions
 * carry a `--mix` percentage and ride a single-hue ramp off --chart-cat-1-hue;
 * highlight regions carry a `--region-hue` var-reference into a --catN slot;
 * unnamed regions take the neutral base fill. Unlayered like every other
 * component file (broad @layer activation is blocked — see cascade.md). */

:is(section.map, figure.chart-frame) .map-figure {
  /* The neutral fill an unnamed region takes — and the ANCHOR the choropleth
   * ramp mixes the hue into, so every valued region reads as "neutral + N%
   * hue". That keeps the ramp monotonic ABOVE the neutral in both light and
   * dark: a low value can never sink darker than an empty region the way a
   * mix-toward-`--bg` ramp does on a dark canvas. */
  --map-base: color-mix(in oklab, var(--text-muted) 16%, var(--bg));
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3cqi;
}
:is(section.map, figure.chart-frame) .map-svg {
  /* Also define --map-base on the SVG itself (not just .map-figure): Read·Article
   * re-hosts the bare .map-svg outside .map-figure, so the choropleth/neutral
   * regions need the base anchor on an ancestor that survives the re-host. */
  --map-base: color-mix(in oklab, var(--text-muted) 16%, var(--bg));
  min-width: 0;
  /* Width-driven (a world map is wide-short): FILL the 70% canvas zone so the
   * map scales to the room it's actually given (it was pinned small at 56cqi).
   * height:auto lets the aspect ratio set the height; max-height guards a tall
   * two-line subtitle. This BASE rule governs hero/bleed maps only — the Form and
   * non-form non-hero maps container-fill via the shared rules in chart-family.css. */
  width: 100%;
  max-width: 100%;
  height: auto;
  max-height: 100%;
  display: block;
}

/* ── Regions ──────────────────────────────────────────────────────────────
 * Unnamed regions sit on a quiet neutral fill so the named ones carry the
 * read. A hairline canvas-coloured stroke keeps adjacent states crisp —
 * the same crisp-divider idiom funnel uses between bands. */
:is(section.map, figure.chart-frame) .map-region {
  fill: var(--map-base);
  stroke: var(--bg);
  stroke-width: 0.6;
  stroke-linejoin: round;
}

/* Choropleth — one sequential ramp off --chart-cat-1-hue, mixed into the neutral
 * base (--map-base) so low values read as a faint tint of the hue OVER the
 * empty fill, never below it. The kernel sets --mix (a color-mix percentage)
 * per region: low → faint hue, high → saturated. Low→high on the ramp. */
:is(section.map, figure.chart-frame) .map-region--on {
  fill: color-mix(in oklab, var(--chart-cat-1-hue) var(--mix), var(--map-base));
}

/* Highlight — categorical: each named region rides its --catN slot hue at
 * the same 82% richness the piechart wedges + funnel bands use, so the
 * three categorical charts read as one family. The kernel sets --region-hue
 * to the slot's var reference. */
:is(section.map, figure.chart-frame) .map-region--hl {
  fill: color-mix(in oklab, var(--region-hue) 82%, var(--bg));
}

/* ── Legend ───────────────────────────────────────────────────────────────
 * The key is now SVG-native (svg-legend.js → `.chart-key-*`, styled in
 * _chart-family/chart-family.css): the kernel emits swatch <rect>s whose fills
 * mirror the region fills (highlight hue / choropleth ramp), group headings as
 * `.chart-key-head` rows, and unmatched names as a hollow `?` chip. The old HTML
 * `.map-legend` / `.map-swatch` rules are retired with it; the `.map-region-*`
 * fills below are unchanged. See 2026-06-13-svg-native-legend.md. */

/* === lib/components/math/math/math.styles.css === */
/* math — evidence.canvas.prose
 *
 * Extracted from lib/_legacy.css in Phase 4 of the destination map.
 * See lib/components/math/math.manifest.json for the component contract.
 */

/* ── MATH ──────────────────────────────────────────────────────────────────
 * Boardroom-quality math layouts for mathematicians, quants, ML researchers,
 * physicists, statisticians, and economists. KaTeX (server-side via the
 * `katex` npm package in lattice-emulator.js, native via `math: 'katex'` in
 * the engine) renders `$$…$$` (display) and `$…$` (inline). Layouts
 * surround the math with the structure each persona expects:
 *
 *   math (bare)         — defaults to `feature` (hero equation + legend)
 *   math.feature        — single hero equation, "where:" legend on the right
 *   math.derivation     — two-column proof chain: step | justification
 *   math.theorem        — Definition / Theorem / Proof stacked cards
 *   math.compare        — two- or three-column equation comparison
 *   math.canvas         — equation left, plot/diagram right
 *   math.matrix         — matrix + dimensions/properties on the right
 *   math.matrix.decompose — three matrices in sequence (A·B = C, SVD, etc.)
 *   math.stats          — estimate ± uncertainty + interpretation line
 *
 * Authoring contracts are documented per-variant below. The single rule
 * that applies to all variants: `$$…$$` becomes a centred display block;
 * `$…$` is inline and inherits surrounding font sizing.
 * ──────────────────────────────────────────────────────────────────────── */

/* ── Shared base ── */
/* Three-row grid: optional inline-code eyebrow at top, headline (h2), then content.
 * Variants override only `grid-template-columns` so they all share the same
 * vertical rhythm. align-self: center on body children centres them inside
 * the 1fr body row. */
section.math {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto auto 1fr;
  gap: var(--sp-md) var(--sp-lg);
  align-content: start;
}
/* Eyebrow — an inline-code paragraph above the heading. The central eyebrow
 * rule (base.modifiers.css) supplies the mono/uppercase chrome; this rule only
 * places it in the top grid row. Authored as `code`, never an h3, so it never
 * trips a heading-order lint. */
section.math > p:has(> code:only-child):has(+ h2) {
  grid-row: 1;
  grid-column: 1 / -1;
  margin: 0;
}
section.math > h2 {
  grid-row: 2;
  grid-column: 1 / -1;
  font-family: var(--font-display);
  font-size: var(--fs-h2);
  color: var(--text-heading);
  margin: 0;
}
/* Default body row — without this, a body item auto-places into row 1 when
 * no eyebrow is present, displacing the title. Variants that need a
 * multi-row body (canvas: equation+caption stacked, stats: vertical scaffold)
 * override grid-row on the specific items.
 * Exclude the absolutely-positioned chrome (header/footer): giving an abs-positioned
 * grid item an explicit grid-row makes that grid AREA its containing block, so the
 * running header's `top:var(--frame-inset-y)` resolved against row 3 and dropped the
 * eyebrow-line "LATTICE · MATH" down beside the body. Excluded, the header/footer
 * resolve against the section box and sit at the top/bottom berths like every slide. */
section.math > :not(h2):not(h3):not(header):not(footer) {
  grid-row: 3;
}
section.math h3 {
  font-family: var(--font-mono);
  font-size: var(--fs-meta);
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--text-secondary);
  padding: 0 0 var(--sp-xs) 0;
}
section.math p { padding: 0 0 var(--sp-xs) 0; }
section.math ul, section.math ol {
  list-style: none; padding: 0; margin: 0;
}
section.math ul > li, section.math ol > li {
  padding: 0 0 var(--sp-xs) 0;
  line-height: var(--lh-base);
}
section.math ul > li::before {
  content: '·';
  padding-right: 0.5em;
  color: var(--accent);
  font-weight: 700;
}

/* KaTeX colour + scale — the rendered math should sit in the same colour
 * tier as headings (more weight than body), and display math should feel
 * monumental without overflowing 1280×720. The 1.05 multiplier on display
 * is conservative: KaTeX's own 1.21em baseline already feels large. */
section.math .katex {
  color: var(--text-heading);
  font-size: 1em;
}
section.math .katex-display {
  margin: 0;
  padding: 0;
  overflow-x: visible;
}
section.math .katex-display > .katex {
  font-size: 1.5em;
  line-height: 1.2;
  display: block;
  text-align: center;
}
section.math .math-error {
  color: var(--warn);
  font-family: var(--font-mono);
  font-size: 0.85em;
  background: color-mix(in srgb, var(--warn) 10%, transparent);
  padding: 0.1em 0.4em;
  border-radius: var(--radius-sm);
}

/* ── math.feature (and bare .math) ──
 * Authoring:
 *   ## Title
 *   $$ \hat\beta = (X^TX)^{-1}X^Ty $$
 *   **where**
 *   - $\hat\beta$ — OLS estimator
 *   - $X$ — design matrix, $n \times p$
 *   - $y$ — response vector
 *
 * Hero equation occupies the left 60% with `.katex-display` blown up;
 * the trailing `**where**` paragraph + list anchor on the right. */
/* Authoring convention: the body is a single `<ul>` (the variable legend);
 * the "where" label is a CSS pseudo-element on the list, so the markdown
 * stays clean and the grid stays simple — equation in col 1, list in col 2,
 * both in row 3 of the body. */
section.math:where(:not(.derivation):not(.theorem):not(.compare):not(.canvas):not(.matrix):not(.stats)),
section.math.feature {
  grid-template-columns: 3fr 2fr;
  padding-bottom: var(--sp-xl);
}
section.math:where(:not(.derivation):not(.theorem):not(.compare):not(.canvas):not(.matrix):not(.stats)) > p:has(> .katex-display),
section.math.feature > p:has(> .katex-display) {
  grid-column: 1;
  grid-row: 3;
  align-self: center;
  text-align: center;
  padding-right: var(--sp-lg);
  border-right: 1px solid var(--border);
}
section.math:where(:not(.derivation):not(.theorem):not(.compare):not(.canvas):not(.matrix):not(.stats)) > p:has(> .katex-display) .katex-display > .katex,
section.math.feature > p:has(> .katex-display) .katex-display > .katex {
  font-size: 1.9em;
}
section.math:where(:not(.derivation):not(.theorem):not(.compare):not(.canvas):not(.matrix):not(.stats)) > :is(ul, ol),
section.math.feature > :is(ul, ol) {
  grid-column: 2;
  grid-row: 3;
  align-self: center;
}
section.math:where(:not(.derivation):not(.theorem):not(.compare):not(.canvas):not(.matrix):not(.stats)) > :is(ul, ol)::before,
section.math.feature > :is(ul, ol)::before {
  content: 'where';
  display: block;
  font-family: var(--font-mono);
  font-size: var(--fs-meta);
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--text-secondary);
  padding-bottom: var(--sp-sm);
}

/* ── math.derivation ──
 * Authoring:
 *   ## Title
 *   | Step                                 | Justification          |
 *   | ------------------------------------ | ---------------------- |
 *   | $f(x+h) = f(x) + f'(x)h + O(h^2)$    | Taylor, 2nd order      |
 *   | $f(x+h) - f(x) = f'(x)h + O(h^2)$    | subtract $f(x)$        |
 *   | $\frac{f(x+h)-f(x)}{h} = f'(x)+O(h)$ | divide by $h$          |
 *   | $\lim_{h\to 0} = f'(x)$              | take limit             |
 *
 * Two-column table: math left, plain-text right. */
section.math.derivation {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-bottom: var(--sp-xl);
  position: relative;
}
/* Heading taken out of flow (absolute, pinned top) so the proof-chain table
 * centres in the well below it — margin-free equivalent of the table's former
 * auto block-axis margins. */
section.math.derivation > h2,
section.math.derivation > h3 {
  /* left/right:auto keeps the heading at its in-flow (section-padded) horizontal
   * position; only the vertical is pinned so the table centres beneath it. top clears
   * the absolute header by the base section's header-clearance (6.875cqi = --sp-2xl +
   * --sp-md), so the title sits the same distance below the eyebrow as on Form slides. */
  position: absolute;
  top: calc(var(--sp-2xl) + var(--sp-md));
  padding: 0;
}
/* The proof chain centres vertically via the parent's
 * `justify-content: center` (replacing the table's former auto block-axis
 * centring, which is now measurable). The table keeps its intrinsic height. */
section.math.derivation table {
  width: 100%;
  border-collapse: collapse;
  border-spacing: 0;
}
section.math.derivation thead {
  display: none; /* headers don't earn their place; column meaning is clear */
}
section.math.derivation tbody tr {
  border-bottom: 1px solid var(--border);
}
section.math.derivation tbody tr:last-child {
  border-bottom: none;
}
section.math.derivation td {
  padding: var(--sp-sm) var(--sp-md);
  vertical-align: middle;
  font-size: var(--fs-body);
}
section.math.derivation td:first-child {
  width: 62%;
  color: var(--text-heading);
}
section.math.derivation td:last-child {
  color: var(--text-secondary);
  font-style: italic;
  border-left: 2px solid var(--border);
}
section.math.derivation tbody tr:last-child td {
  font-weight: 600;
  color: var(--text-heading);
}
section.math.derivation tbody tr:last-child td:last-child {
  font-style: normal;
  color: var(--accent);
}
/* Display math used as a row entry stays inline-block so it doesn't break
 * the row height. Override the default centred display behaviour. */
section.math.derivation td .katex-display {
  display: inline-block;
  margin: 0;
  text-align: left;
}
section.math.derivation td .katex-display > .katex {
  font-size: 1.15em;
  display: inline-block;
  text-align: left;
}

/* ── math.theorem ──
 * Authoring: blockquotes labelled by their first **Bold.** word.
 *   ## Title
 *   > **Definition.** A function $f:\mathbb{R}\to\mathbb{R}$ is continuous
 *   > at $a$ if $\lim_{x\to a} f(x) = f(a)$.
 *   >
 *   > **Theorem (IVT).** If $f$ is continuous on $[a,b]$ and $y$ lies
 *   > between $f(a)$ and $f(b)$, then $\exists c \in [a,b]$ with $f(c)=y$.
 *   >
 *   > **Proof.** By contradiction. …
 *
 * The blockquotes render as stacked colour-coded cards. Markdown wraps
 * each `>`-prefixed block in a single `<blockquote>`; theorem-card stripes
 * are coloured by position (first/middle/last) using the deck spectrum. */
section.math.theorem {
  display: flex;
  flex-direction: column;
  /* Card stack centres in the well via justify-content; the heading is taken
   * out of flow (absolute, below) so it stays pinned to the top while only the
   * cards centre — the margin-free equivalent of the old first/last-card
   * `margin:auto`. (section::after is the pagination marker, so a flex
   * pseudo-spacer pair isn't available on this non-Form component.) The
   * transparent inter-card gap is a measurable `gap` of var(--sp-sm) — padding
   * would extend each card's --bg-alt fill. */
  justify-content: center;
  gap: var(--sp-sm);
  padding-bottom: var(--sp-lg);
  position: relative;
}
section.math.theorem > h2,
section.math.theorem > h3 {
  /* left/right:auto keeps the heading at its in-flow (section-padded) horizontal
   * position; only the vertical is pinned so the cards centre beneath it. top clears
   * the absolute header by the base section's header-clearance (6.875cqi = --sp-2xl +
   * --sp-md), so the title sits the same distance below the eyebrow as on Form slides. */
  position: absolute;
  top: calc(var(--sp-2xl) + var(--sp-md));
  padding: 0;
}
section.math.theorem blockquote {
  background: var(--bg-alt);
  border-left: 4px solid var(--accent);
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  padding: var(--sp-sm) var(--sp-md);
  font-style: normal;
  color: var(--text-body);
}
/* Suppress the default "KEY INSIGHT" eyebrow that lattice.css emits on every
 * blockquote outside .quote — the bold inline label (Definition.,
 * Theorem., Proof.) carries the type, and a second label clutters the card. */
section.math.theorem blockquote::before { content: none; }
section.math.theorem blockquote p {
  margin: 0;
}
section.math.theorem blockquote p + p {
  padding-top: var(--sp-xs);
}
section.math.theorem blockquote strong:first-child {
  font-family: var(--font-mono);
  font-size: var(--fs-meta);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-weight: 700;
  color: var(--accent);
  padding-right: 0.5em;
}
/* Position-based accent stripe — Definition (start) cooler, Theorem (middle)
 * warmer, Proof (end) neutral. Uses the palette's --cN-dark categorical
 * tokens that every Lattice theme defines; falls back to --accent if a
 * future palette ever drops them. */
section.math.theorem blockquote:nth-of-type(3n+1) {
  border-left-color: var(--cat-4-mark, var(--accent));
}
section.math.theorem blockquote:nth-of-type(3n+1) strong:first-child {
  color: var(--cat-4-mark, var(--accent));
}
section.math.theorem blockquote:nth-of-type(3n+2) {
  border-left-color: var(--cat-7-mark, var(--accent));
}
section.math.theorem blockquote:nth-of-type(3n+2) strong:first-child {
  color: var(--cat-7-mark, var(--accent));
}
section.math.theorem blockquote:nth-of-type(3n) {
  border-left-color: var(--text-muted);
}
section.math.theorem blockquote:nth-of-type(3n) strong:first-child {
  color: var(--text-secondary);
}
section.math.theorem blockquote .katex-display {
  padding: var(--sp-xs) 0;
}
section.math.theorem blockquote .katex-display > .katex {
  font-size: 1.25em;
}

/* ── math.compare ──
 * Authoring: alternating h3 + content groups become columns.
 *   ## Title
 *   ### Naïve
 *   $$ E = mc^2 $$
 *   Classical kinetic-energy approximation.
 *   ### Relativistic
 *   $$ E^2 = (mc^2)^2 + (pc)^2 $$
 *   Full Einstein relation; reduces to the naïve form for $p \ll mc$.
 *
 * Renders as 2-column (or 3-column if three h3s are present) via CSS
 * multi-columns. The markdown emits a flat sibling sequence — no wrapper
 * divs — so we use `column-span:all` on h2 to keep the title full-width
 * and `break-before:column` on each subsequent h3 to start a new column. */
section.math.compare {
  display: block;
  column-count: 2;
  column-gap: var(--sp-lg);
  column-rule: 1px solid var(--border);
  column-fill: balance;
  /* Chromium ≥122 honours `align-content` on block layout — use it to pull
   * the columns to the vertical middle of the slide so a short comparison
   * doesn't leave the bottom half empty. */
  align-content: center;
  padding-bottom: var(--sp-lg);
}
section.math.compare:has(h3:nth-of-type(3)) {
  column-count: 3;
}
section.math.compare > h2 {
  column-span: all;
  padding: 0 0 var(--sp-md) 0;
}
section.math.compare > h3 {
  break-before: column;
  break-after: avoid;
  padding-bottom: var(--sp-xs);
  border-bottom: 2px solid var(--accent);
  color: var(--text-heading);
  font-size: var(--fs-meta);
}
/* The gap below the h3 underline (formerly the h3's `margin-bottom`) lives as
 * the following element's top padding so the rule keeps drawing tight to the
 * label text — measurable, and outside the border just as the margin was. */
section.math.compare > h3 + * { padding-top: var(--sp-sm); }
section.math.compare > h3:first-of-type { break-before: avoid; }
section.math.compare > p:has(> .katex-display) {
  break-inside: avoid;
  padding-bottom: var(--sp-sm);
  text-align: center;
}
section.math.compare > p:has(> .katex-display) .katex-display > .katex {
  font-size: 1.4em;
}
section.math.compare > p:not(:has(.katex-display)) {
  color: var(--text-secondary);
  padding-bottom: var(--sp-xs);
}

/* ── math.canvas ──
 * Authoring (plot via function-plot):
 *   ## Title
 *   $$ y = \frac{1}{1+e^{-x}} $$
 *   The sigmoid: $S$-shaped, asymptotes at $0$ and $1$.
 *   ```functionplot
 *   { "data": [{ "fn": "1 / (1 + exp(-x))" }],
 *     "xAxis": { "domain": [-6, 6] }, "yAxis": { "domain": [-0.1, 1.1] } }
 *   ```
 *
 * Equation + caption on the left, plot on the right. The plot child is
 * either a ```functionplot fence (function-plot, the default) or an
 * `<img>` for externally-rendered SVG / PNG. */
/* Grid-template-areas keeps equation + caption stacked in the left column
 * without a wrapper div: equation in `eq` (1fr, big), caption in `cap`
 * (auto, sized to text), plot spans both rows on the right. The plot's
 * intrinsic height no longer inflates the eq row because eq is bounded
 * by 1fr (which only takes remaining space). */
section.math.canvas {
  grid-template-columns: 2fr 3fr;
  grid-template-rows: auto auto 1fr auto;
  grid-template-areas:
    "eyebrow eyebrow"
    "title   title"
    "eq      plot"
    "cap     plot";
  padding-bottom: var(--sp-xl);
}
section.math.canvas > p:has(> code:only-child):has(+ h2) { grid-area: eyebrow; }
section.math.canvas > h2              { grid-area: title; }
section.math.canvas > p:has(.katex-display) {
  grid-area: eq;
  align-self: center;
  text-align: center;
  margin: 0;
}
section.math.canvas > p:has(.katex-display) .katex-display > .katex {
  font-size: 1.7em;
}
section.math.canvas > p:not(:has(.katex-display)):not(:has(img)) {
  grid-area: cap;
  color: var(--text-secondary);
  text-align: center;
  padding: var(--sp-sm) 0 0 0;
}
section.math.canvas > p:has(img),
section.math.canvas > :is(svg, figure, .functionplot) {
  grid-area: plot;
  align-self: center;
  justify-self: center;
}
section.math.canvas > .functionplot {
  width: 55cqi;
  height: 38cqi;
}
section.math.canvas > p:has(img) {
  margin: 0;
  text-align: center;
}
section.math.canvas > p > img {
  max-width: 100%;
  max-height: 55cqi;
  width: auto;
  height: auto;
  display: inline-block;
}

/* ── math.matrix ──
 * Authoring (default — one matrix + properties):
 *   ## Title
 *   $$ M = \begin{pmatrix} 1 & 2 & 3 \\ 4 & 5 & 6 \end{pmatrix} $$
 *   - **shape** — $2 \times 3$
 *   - **rank** — $2$
 *   - **rows** — observations
 *   - **cols** — features
 *
 * Authoring (`.decompose` — three matrices in sequence):
 *   ## Title
 *   $$ A = U\Sigma V^\top $$
 *   ### Singular value decomposition
 *   $$ U \in \mathbb{R}^{m\times m} $$
 *   $$ \Sigma \in \mathbb{R}^{m\times n} $$
 *   $$ V \in \mathbb{R}^{n\times n} $$ */
section.math.matrix {
  grid-template-columns: 3fr 2fr;
  align-content: center;
  padding-bottom: var(--sp-lg);
}
section.math.matrix > p:has(> .katex-display) {
  grid-column: 1;
  align-self: center;
  text-align: center;
}
section.math.matrix > p:has(> .katex-display) .katex-display > .katex {
  font-size: 1.7em;
}
section.math.matrix > :is(ul, ol) {
  grid-column: 2;
  align-self: center;
  padding-left: var(--sp-md);
  border-left: 1px solid var(--border);
}
section.math.matrix > :is(ul, ol) > li {
  padding-bottom: var(--sp-sm);
  color: var(--text-body);
}
section.math.matrix > :is(ul, ol) > li > strong {
  display: inline-block;
  min-width: 4em;
  font-family: var(--font-mono);
  font-size: var(--fs-meta);
  text-transform: uppercase;
  letter-spacing: 0.18em;
  color: var(--text-secondary);
  font-weight: 600;
  padding-right: 0.5em;
}

/* `.decompose` overrides the grid to a block layout so the secondary
 * equations can sit inline-block in a row. The lead equation + h3 are
 * full-width block; the remaining `<p>` siblings flow horizontally as
 * a 3-up row (text-align: center on the parent centres them as a group). */
/* Block layout with align-content:center centres the whole group
 * (title → lead eq → divider → subhead → component row) vertically.
 * The 3 component equations need block display to flow inline-block in a
 * row; flex column would stack them. Modern Chromium (≥122) supports
 * `align-content` on block — older preview Chromium falls back to
 * top-anchored content, which is still readable. */
section.math.matrix.decompose {
  display: block;
  align-content: center;
  padding-bottom: var(--sp-lg);
  text-align: center;
}
section.math.matrix.decompose > h2 {
  padding: 0 0 var(--sp-md) 0;
  text-align: left;
}
section.math.matrix.decompose > p:has(> .katex-display):first-of-type {
  padding-bottom: var(--sp-md);
  border-bottom: 1px solid var(--border);
}
section.math.matrix.decompose > p:has(> .katex-display):first-of-type .katex-display > .katex {
  font-size: 2.1em;
}
section.math.matrix.decompose > h3 {
  text-align: center;
  /* Top padding carries the gap below the lead equation's divider (formerly
   * the equation's `margin-bottom`), keeping the rule tight to the equation;
   * bottom padding replaces the h3's own `margin-bottom`. */
  padding-top: var(--sp-md);
  padding-bottom: var(--sp-sm);
}
section.math.matrix.decompose > p:has(> .katex-display):not(:first-of-type) {
  display: inline-block;
  width: calc((100% - 2 * var(--sp-lg)) / 3);
  padding: 0 var(--sp-xs);
  vertical-align: middle;
}
section.math.matrix.decompose > p:has(> .katex-display):not(:first-of-type) .katex-display > .katex {
  font-size: 1.3em;
}

/* ── math.stats ──
 * Authoring:
 *   ## Title
 *   $$ \hat\beta = 0.42 \pm 0.03 $$
 *   > 95% CI: $[0.36,\, 0.48]$
 *   > $p < 0.001$, $n = 1{,}204$
 *
 *   For every additional unit of $X$, $Y$ rises by 0.42 SD — roughly an 8 %
 *   shift on the baseline outcome.
 *
 * Hero estimate ± SE, blockquote of uncertainty/test stats, interpretation
 * line at the bottom. */
/* Flex column with justify-content:center pulls the whole stack (title →
 * hero estimate → blockquote → interpretation) to the vertical middle so
 * the boardroom number lands at eye-level instead of orphaning an empty
 * lower half. */
section.math.stats {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding-bottom: var(--sp-xl);
  gap: var(--sp-sm);
}
section.math.stats > h2 {
  text-align: center;
  padding: 0 0 var(--sp-md) 0;
}
section.math.stats > p:has(> .katex-display):first-of-type {
  text-align: center;
  margin: 0;
}
section.math.stats > p:has(> .katex-display):first-of-type .katex-display > .katex {
  font-size: 2.6em;
  color: var(--accent);
  font-weight: 700;
}
section.math.stats > blockquote {
  border-left: none;
  background: none;
  padding: 0 0 var(--sp-md) 0;
  text-align: center;
  font-style: normal;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: var(--fs-meta);
  letter-spacing: 0.12em;
}
section.math.stats > blockquote p {
  padding: 0 0 0.15em 0;
}
section.math.stats > blockquote::before { content: none; }
section.math.stats > p:not(:has(> .katex-display)):not(:first-of-type) {
  text-align: center;
  max-width: 60cqi;
  margin: 0;
  color: var(--text-body);
  font-size: var(--fs-body);
  line-height: var(--lh-base);
}

/* ── Box-local family reflow (engineering/decisions/2026-06-18-component-adaptive-sizing.md).
   The hero+legend (`feature`/bare) and matrix+properties (`matrix`) layouts put the
   equation and its annotations in two columns; in a tall box those crush. Collapse
   each by spanning BOTH children full-width (`grid-column: 1 / -1`) and stacking the
   legend/properties beneath the equation. IMPORTANT: the columns can't be removed by
   restyling the section's own `grid-template-columns` — a `@container` rule cannot
   style its own container element (§11). Spanning the descendants 1/-1 takes the full
   width regardless of the section's column tracks, which a container query CAN do.
   `derivation`/`theorem`/`stats` are already single-column. (`compare` uses CSS
   multi-`column-count` and `canvas` uses `grid-template-areas` — both are section-
   element properties a container query can't reach, so they stay landscape; see the
   manifest `adapt.families` note.) Keyed on the nearest `lattice` container's aspect;
   the doubled class `.math.math` matches the variant rules' weight (and beats the
   zero-specificity `:where()` bare-math selector). */
@container lattice (aspect-ratio <= 0.9) {
  /* feature (+ bare): equation full-width, legend full-width beneath it. */
  section.math.math:where(:not(.derivation):not(.theorem):not(.compare):not(.canvas):not(.matrix):not(.stats)) > p:has(> .katex-display),
  section.math.math.feature > p:has(> .katex-display) {
    grid-column: 1 / -1; grid-row: 3;
    align-self: start; padding-top: var(--sp-xl);
    border-right: none; padding-right: 0; padding-bottom: var(--sp-md);
  }
  section.math.math:where(:not(.derivation):not(.theorem):not(.compare):not(.canvas):not(.matrix):not(.stats)) > :is(ul, ol),
  section.math.math.feature > :is(ul, ol) {
    grid-column: 1 / -1; grid-row: 4; align-self: start;
  }
  /* Tall frame = room for a monumental hero equation; scale it up so it owns the
     canvas instead of floating small in a void. */
  section.math.math:where(:not(.derivation):not(.theorem):not(.compare):not(.canvas):not(.matrix):not(.stats)) > p:has(> .katex-display) .katex-display > .katex,
  section.math.math.feature > p:has(> .katex-display) .katex-display > .katex {
    font-size: 2.7em;
  }
  /* matrix: equation full-width over properties; left rule → top rule. */
  section.math.math.matrix > p:has(> .katex-display) { grid-column: 1 / -1; grid-row: 3; align-self: start; padding-top: var(--sp-xl); }
  section.math.math.matrix > p:has(> .katex-display) .katex-display > .katex { font-size: 2.4em; }
  section.math.math.matrix > :is(ul, ol) {
    grid-column: 1 / -1; grid-row: 4; align-self: start;
    padding-left: 0; border-left: none;
    padding-top: var(--sp-md); border-top: 1px solid var(--border);
  }
}

/* `compare` (CSS multi-`column-count`) and `canvas` (`grid-template-areas`) put their
   layout on the SECTION — section-element properties a `@container` query can't reach
   (§11). They key on the deck-wide `data-orientation` stamp instead (the sanctioned
   path; cf. split-compare): on a portrait deck `compare` reads as one column and
   `canvas` stacks the equation over the plot. */
section.math.compare[data-orientation="portrait"] { column-count: 1; }
section.math.compare[data-orientation="portrait"] > h3 { break-before: avoid; }
section.math.canvas[data-orientation="portrait"] {
  grid-template-columns: 1fr;
  grid-template-rows: auto auto auto auto 1fr;
  grid-template-areas: "eyebrow" "title" "eq" "cap" "plot";
}

/* ── function-plot SVG styling ──
 * function-plot stamps inline `stroke="..."` attributes on its trace paths
 * (`.line-0`, `.line-1`, …) and axis chrome (`stroke="black"` on `.domain`,
 * `fill="currentColor"` on tick text). To bring it into the palette we
 * override those with !important on the inline attributes. The first
 * three traces ride the editorial accents (accent → cool → warm);
 * further traces fall back to muted so they read as supporting context. */
section .functionplot .function-plot {
  font-family: var(--font-mono);
  color: var(--text-body);
  background: transparent;
}
section .functionplot .function-plot .domain {
  stroke: var(--text-muted) !important;
  opacity: 0.6 !important;
}
section .functionplot .function-plot .tick line {
  stroke: var(--border) !important;
}
section .functionplot .function-plot .tick text {
  fill: var(--text-muted) !important;
  font-size: var(--fs-meta);
}
section .functionplot .function-plot .axis-label,
section .functionplot .function-plot .x.axis-label,
section .functionplot .function-plot .y.axis-label {
  fill: var(--text-heading) !important;
  font-family: var(--font-body);
  font-size: var(--fs-meta);
  font-weight: 600;
}
section .functionplot .function-plot .line-0 {
  stroke: var(--accent) !important;
  stroke-width: 2.5 !important;
}
section .functionplot .function-plot .line-1 {
  stroke: var(--cat-4-mark, var(--text-heading)) !important;
  stroke-width: 2.5 !important;
}
section .functionplot .function-plot .line-2 {
  stroke: var(--cat-7-mark, var(--text-muted)) !important;
  stroke-width: 2.5 !important;
}
section .functionplot .function-plot :is(.line-3, .line-4, .line-5) {
  stroke: var(--text-muted) !important;
  stroke-width: 2 !important;
}
section .functionplot .function-plot .annotations .annotation,
section .functionplot .function-plot .annotations text {
  fill: var(--text-muted) !important;
  stroke: var(--text-muted) !important;
}
section .functionplot-error {
  color: var(--warn);
  font-family: var(--font-mono);
  font-size: var(--fs-meta);
  padding: var(--sp-sm);
  border: 1px dashed var(--warn);
  border-radius: var(--radius-sm);
}

/* === lib/components/comparison/matrix-2x2/matrix-2x2.styles.css === */
/* matrix-2x2 — extracted from lib/_legacy.css (batch 4).
 * See lib/components/matrix-2x2/matrix-2x2.manifest.json for the component contract.
 */

/* ── MATRIX-2X2 ────────────────────────────────────────────────────────
 * ## heading
 * `Axis-X · Axis-Y`         (eyebrow, optional — renders as inline-code label)
 * - Top-left              \
 * - Top-right              \  exactly four top-level items, in
 * - Bottom-left            /  declaration order = TL · TR · BL · BR
 * - Bottom-right          /
 *
 * Implementation: a 2×2 CSS grid on the bare ul/ol. Each li is a card
 * with the body nested as an inner ul. The four quadrants share visual
 * chrome; the bottom-right cell carries an accent ring as the conventional
 * "high-priority" or "outcome" cell (SWOT: opportunities · Eisenhower: do).
 * Authors who want a different accent cell can swap items in the markdown.
 * ──────────────────────────────────────────────────────────────────────── */
section.matrix-2x2 > .cell-stage { display:flex; flex-direction:column; }
/* 2×2 as FLEX, not grid (flex cell-tree §10/§11 — flex shop). flex-wrap with cells
 * sized `calc(50% - gap/2)` reproduces the `1fr 1fr / 1fr 1fr` grid pixel-identically
 * (§13: 359/1,000,500 = 0.036 %). The cells' `box-sizing:border-box` is load-bearing:
 * under content-box, width + padding + border exceeds 50 % and the second card wraps
 * (runbook gotcha 1). Equal heights resolve because `.cell-stage` gives this list a
 * definite (flex:1, min-height:0) height (gotcha 2). */
section.matrix-2x2 > .cell-stage > ul,
section.matrix-2x2 > .cell-stage > ol {
  display:flex; flex-wrap:wrap; align-content:stretch;
  gap:var(--sp-md); flex:1;
  list-style:none; padding:0; margin:0;
}
section.matrix-2x2 > .cell-stage > ul > li,
section.matrix-2x2 > .cell-stage > ol > li {
  box-sizing:border-box;
  width:calc(50% - var(--sp-md) / 2);
  height:calc(50% - var(--sp-md) / 2);
  background:var(--bg-alt);
  border:1px solid var(--border);
  border-radius:var(--radius-md);
  padding:var(--sp-md);
  display:flex; flex-direction:column; gap:var(--sp-xs);
  font-weight:700; color:var(--text-heading);
  font-size:var(--fs-body);
  position:relative; overflow:hidden;
}
/* Convention: the fourth (bottom-right) quadrant is the "outcome" cell. */
section.matrix-2x2 > .cell-stage > ul > li:nth-child(4),
section.matrix-2x2 > .cell-stage > ol > li:nth-child(4) {
  border-color:var(--on-accent-soft);
  background:var(--accent-soft);
}
/* Body — nested ul/ol becomes the cell prose. */
section.matrix-2x2 li > ul,
section.matrix-2x2 li > ol {
  list-style:none; padding:0; margin:0;
}
section.matrix-2x2 li > ul > li,
section.matrix-2x2 li > ol > li {
  font-size:var(--fs-body-compact);
  font-weight:400;
  color:var(--text-body);
  line-height:var(--lh-base);
}

/* Hardening: element siblings of <strong> in a card li don't inherit
 * the parent's font-weight:700. Covers cases like `<strong>Title.</strong>
 * <em>italic body</em>`. Text-node siblings still inherit (CSS can't
 * target text nodes); the manifest validator catches that case at
 * lint time. See CARD_STYLE_LAYOUTS in lib/components/index.js. */
section.matrix-2x2 :is(ul,ol) > li > strong ~ * { font-weight: 400; }

/* ── Box-local family reflow (2026-06-18-component-adaptive-sizing.md). Wide and
 * square keep the 2×2 (a square box reads the quadrants fine); tall and strip
 * collapse to a single column. Keyed on the nearest `lattice` container's aspect,
 * so it fires on a portrait deck AND inside a narrow nested cell — replacing the
 * deck-wide data-orientation stamp. */
/* `.matrix-2x2.matrix-2x2` (class doubled) reaches (0,2,2) to match the original
 * `[data-orientation]` reflow's specificity and stay robust to future variant
 * grid rules — the role the attribute played. */
@container lattice (aspect-ratio <= 0.9) {
  /* Tall/strip → single column: flex-column, each card flex:1 to split the height
   * (the flex mirror of the grid's `grid-auto-rows:minmax(0,1fr)`). */
  section.matrix-2x2.matrix-2x2 > .cell-stage > ul,
  section.matrix-2x2.matrix-2x2 > .cell-stage > ol {
    flex-direction: column;
    flex-wrap: nowrap;
  }
  section.matrix-2x2.matrix-2x2 > .cell-stage > ul > li,
  section.matrix-2x2.matrix-2x2 > .cell-stage > ol > li {
    width: 100%;
    height: auto;
    flex: 1;
    min-height: 0;
  }
}

/* ── Struck elevation (base.tokens.css --elevation-card) ── lift the cards; vertical
 * berth (padding-block, never margin — #20) so the stage's overflow:clip doesn't
 * shear the shadow. Shadow has no horizontal extent, so no horizontal berth. */
section.matrix-2x2 > .cell-stage > ol > li {
  box-shadow: var(--elevation-card);
}
section.matrix-2x2 > .cell-stage {
  padding-block: var(--elevation-berth);
}

/* === lib/components/legal/obligation-matrix/obligation-matrix.styles.css === */
/* obligation-matrix — comparison.matrix.structure
 *
 * Extracted from lib/_legacy.css in Phase 4 of the destination map.
 * See lib/components/obligation-matrix/obligation-matrix.manifest.json for the component contract.
 */

/* ── OBLIGATION-MATRIX ────────────────────────────────────────────────
 * Markdown table layout. Rows = regulations, columns = obligations.
 *
 * <!-- _class: obligation-matrix -->
 * | Regulation | Notice | Consent | Retention | Breach | DSAR |
 * | ---------- | :----: | :-----: | :-------: | :----: | :--: |
 * | CCPA       | [x]    | [-]     | [x]       | [x]    | [x]  |
 *
 * Cells are authored with the state-marker grammar [x]/[-]/[ ]/[/], decoded
 * into status-coloured state discs (masked SVG via --state-mark). Variants:
 * .heat (cell fills), .pills (cell pills), .lanes (row stripes),
 * .asymmetric (cards).
 * ──────────────────────────────────────────────────────────────────── */
section.obligation-matrix > .cell-stage { display:flex; flex-direction:column; }
section.obligation-matrix table {
  width:100%;
  border-collapse:separate;
  border-spacing:0;
  font-size:var(--fs-body-compact);
  flex:1;
  table-layout:auto;
}
section.obligation-matrix thead tr { background:var(--spectrum-structure) bottom / 100% 2px no-repeat; }
section.obligation-matrix thead th {
  font-family:var(--font-label);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.10em;
  text-transform:uppercase;
  color:var(--text-label);
  padding:0.46875cqi var(--sp-sm) 0.78125cqi;
  text-align:center;
  border-bottom:1px solid var(--border);
}
section.obligation-matrix thead th:first-child { text-align:left; }
section.obligation-matrix td {
  padding:0.78125cqi var(--sp-sm);
  border-bottom:1px solid var(--border);
  text-align:center;
  vertical-align:middle;
  color:var(--text-body);
}
section.obligation-matrix td:first-child {
  text-align:left;
  font-weight:700;
  color:var(--text-heading);
  white-space:nowrap;
  padding-left:var(--sp-md);
}
/* Soft row zebra for grid scan. */
section.obligation-matrix tbody tr:nth-child(odd) td:not(:first-child) {
  background:color-mix(in srgb, var(--accent) 4%, transparent);
}

/* ── State glyphs + .heat chrome — appended Phase 7 ──
 * Universal state-token grammar (filled / half / empty / slashed disc)
 * rendered for obligation-matrix cells, plus the .heat variant's
 * cell-tint chrome that makes the table read as a heat map.
 * Originally at lib/_legacy.css lines 1238-1449 under the
 * LEGAL & REGULATORY LAYOUTS section.
 */

/* ── State glyphs ─────────────────────────────────────────────────────
 * Author writes the universal [x]/[-]/[ ]/[/] grammar; the engine/
 * emulator/runtime transforms strip the marker and wrap the cell
 * content in
 *   <span class="state {pass|warn|fail|skip} {state-full|state-half|state-empty|state-slashed}">…</span>.
 * The shape class selects the in-disc mark (check / dash / x / slash via
 * --state-mark); the semantic class resolves --state-color. SHAPE is the
 * primary channel — readable in greyscale, unambiguous for colour-blind
 * viewers. The disc (this element) + masked mark (::after) follow the
 * scalar-knob recipe shared with checklist / verdict-grid; no font
 * dependency, no Unicode glyphs.
 *
 * Default colour mapping is the per-category coverage palette
 * (applies = green; partial = amber; exempt = red; skipped = muted).
 * The universal `.heat` modifier (top of LAYOUTS section) flips to the
 * risk axis (applies = alarm red, exempt = relief green). This layout
 * additionally adds heat-aware cell-tint chrome below. */
section.obligation-matrix td .state {
  position:relative;
  display:inline-block;
  width:calc(1.4em * var(--state-disc-scale)); height:calc(1.4em * var(--state-disc-scale));
  border-radius:50%;
  box-sizing:border-box;
  vertical-align:middle;
  /* Hide any trailing label ([x] Applies fully…) while keeping em units
   * resolving against the inherited cell font-size. Setting font-size:0
   * here would collapse the disc to 0. The ::after mark is position:absolute
   * so text-indent never touches it. */
  overflow:hidden;
  text-indent:200%;
  white-space:nowrap;
  line-height:1;
  /* Disc fill + ring + lift from the scalar knobs (default Ringed Solid or
   * a .checks-* variant). Colours mixed here from --state-color. Mirror
   * recipe: checklist.styles.css, verdict-grid.styles.css. */
  background:color-mix(in srgb, var(--state-color, var(--text-muted)) var(--state-fill-pct), transparent);
  box-shadow:
    0 0 0 var(--state-ring-outer-w) color-mix(in srgb, var(--state-color, var(--text-muted)) var(--state-ring-mix), black),
    inset 0 0 0 var(--state-ring-inner-w) var(--state-color, var(--text-muted));
}
section.obligation-matrix td .state.pass { --state-color:var(--pass); }
section.obligation-matrix td .state.warn { --state-color:var(--warn); }
section.obligation-matrix td .state.fail { --state-color:var(--fail); }
section.obligation-matrix td .state.skip { --state-color:var(--text-muted); }
/* exempt — `[ ]` is "not subject to this obligation", a NEUTRAL state (not a
 * gap): a true hollow ring (empty centre; see `.state.todo` in base.modifiers). */
section.obligation-matrix td .state.todo { --state-color:var(--text-label); }
/* Mark overlay — masked symbol (check / dash / x / slash) on the disc.
 * Mark colour from --state-mark-pct (0% = knockout to --bg). */
section.obligation-matrix td .state::after {
  content:'';
  position:absolute; inset:0;
  background-color:color-mix(in srgb, var(--state-color, var(--text-muted)) var(--state-mark-pct), var(--bg));
  -webkit-mask:var(--state-mark) center / 100% 100% no-repeat;
          mask:var(--state-mark) center / 100% 100% no-repeat;
}

/* .heat chrome — palette inversion comes from the universal
 * section.heat overlay; this block adds the cell-background tint that
 * makes the table read as a heat map at a glance. */
section.obligation-matrix.heat tbody tr td:not(:first-child) { background:none; }
section.obligation-matrix.heat td:has(> .state.pass) {
  background:color-mix(in srgb, var(--fail) 14%, var(--bg));
}
section.obligation-matrix.heat td:has(> .state.warn) {
  background:color-mix(in srgb, var(--warn) 14%, var(--bg));
}
section.obligation-matrix.heat td:has(> .state.fail) {
  background:color-mix(in srgb, var(--pass) 10%, var(--bg));
}
section.obligation-matrix.heat td:has(> .state.skip) {
  background:color-mix(in srgb, var(--text-muted) 6%, var(--bg));
}
/* Bracket-frame echo at the row level. Each row carries a doubled left
 * border (matching the authority-chain.bracket aesthetic) so the matrix
 * reads as one bracketed structure; the first cell carries the bracket,
 * the rest stay flush. */
section.obligation-matrix.heat tbody tr td:first-child {
  border-left:6px double var(--accent);
  padding-left:var(--sp-md);
}
section.obligation-matrix.heat tbody tr td:last-child {
  border-right:6px double var(--accent);
  padding-right:var(--sp-md);
}
section.obligation-matrix.heat thead tr th:first-child {
  border-left:6px double var(--accent);
  padding-left:var(--sp-md);
}
section.obligation-matrix.heat thead tr th:last-child {
  border-right:6px double var(--accent);
  padding-right:var(--sp-md);
}

/* === lib/components/chart/piechart/piechart.styles.css === */
/* piechart — extracted from lib/_legacy.css (batch 9).
 * See lib/components/piechart/piechart.manifest.json for the component contract.
 */

/* ── PIECHART · donut ──
 * SVG wedges emitted at build time; legend rendered to the right.
 * The donut hole (when modifier `donut` is present) is left blank. */
/* .chart-body inherits the shared width + padding (sp-lg / sp-2xl) so the
 * surface panel matches every other chart's size and inset — no
 * piechart-specific override. */
:is(section.piechart, figure.chart-frame) .piechart-figure {
  /* SVG-native legend (2026-06-13-svg-native-legend.md): the figure holds ONE
     self-contained <svg> (diagram + spine + key in one viewBox). It only needs
     to centre + size that SVG; the 70/30 split, spine and key now live INSIDE
     the viewBox, so they scale with the diagram by construction (no CSS grid,
     no `cqh`-in-`font-size`). container-type:size lets the SVG's height:100cqh
     resolve against this box. */
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  flex: 1 1 auto;
  min-height: 0;
  container-type: size;
}
:is(section.piechart, figure.chart-frame) .piechart-svg {
  flex: 0 0 auto;
  /* CONTAINER-FILL (2026-07-04-chart-container-fill-sizing.md). The parent
     (.piechart-figure) is a container-type:size
     box, so the SVG fills BOTH axes of that definite box; its preserveAspectRatio
     `meet` fits the unit inside, whichever dimension binds — shrink-to-fit, never
     clip, resolution-independent. (Was height-bound: height:100cqh; width:auto.) */
  width: 100%;
  height: 100%;
  display: block;
}
/* Cover is full-bleed. With the key now INSIDE the SVG the figure has no
   intrinsic-height child, so a %/cqh chain collapses to 0 (blank). Mirror the
   proven radar:is(.claim-hero, .claim-bleed) fix: drop the figure's size-containment so the SVG's `cqi`
   resolves against the SECTION (container-type:size), and give the SVG an
   explicit `cqi` height that scales the whole unit (disc + key) up. The viewBox
   `meet` keeps it undistorted; max-height guards a tall two-line caption. */
section.piechart:is(.claim-hero, .claim-bleed) .piechart-figure {
  container-type: normal;
  height: auto;
  width: 100%;
  max-width: 100%;
}
section.piechart:is(.claim-hero, .claim-bleed) .piechart-svg {
  height: 38cqi;
  width: auto;
  max-height: 100%;
  max-width: 100%;
}
/* IN-FORM (section.form). Under the Form the masthead/footer Cells are reserved
   via the section's padding, squeezing the flex column
   (section → .chart-body flex:1 → .piechart-figure flex:1). The CHART-BODY fills
   the stage reliably via flex — even in print — but its descendants do NOT: in
   the print-media Chromium that exports the PDF, a `flex:1` *figure* whose sole
   content is a replaced <svg> will NOT grow to fill the chart-body
   (replaced-content intrinsic size wins), and `height:100cqh`/`%`/abs-inset read
   against the figure all collapse toward 0 — the donut shrank to a ~40px
   thumbnail. A naive `Ncqi` HEIGHT was the opposite failure: cqi is a WIDTH unit
   (~589px against the section at HD), far taller than the squeezed band, so the
   oversized SVG overflowed and `.chart-body{overflow:hidden}` CLIPPED the ring +
   legend to a fragment (the `max-height:100cqh` guard, read against the section,
   never engaged). See 2026-06-15-form-chart-clip.md.

   ROBUST FIX — size the SVG off the CHART-BODY's content box:
     · make `.chart-body` the size-query container (`container-type:size`); its
       cqh basis is exactly the chart-body fill height MINUS its own padding =
       the real available figure area, and it tracks every chrome combo (0/1/2
       -line subtitle ± caption) — verified empirically in print media;
     · collapse the figure's box out with `display:contents` so the SVG sizes
       straight off the chart-body container (the `flex:1` figure cannot mediate
       the height in print);
     · `height:100cqh` on the SVG → it fills the available area, width follows
       the unified viewBox aspect, so the WHOLE unit (disc + key) scales and
       never overflows/clips, HD and 4K alike.
   Scoped to section.form so non-form pie rendering stays byte-identical. */
section.form.piechart:not(.claim-hero):not(.claim-bleed) .chart-body {
  container-type: size;
}
section.form.piechart:not(.claim-hero):not(.claim-bleed) .piechart-figure {
  display: contents;
}
section.form.piechart:not(.claim-hero):not(.claim-bleed) .piechart-svg {
  width: 100%;
  height: 100%;
}
:is(section.piechart, figure.chart-frame) .piechart-svg .wedge {
  /* Stroke colour is the slot's --catN-ink (set per nth-child below); the
   * wedge fill is the same hue's --catN-fill. Pale fill + deep border on a
   * light canvas, deep fill + pale border on dark — the shared chart model. */
  stroke-width: 1.5;
  paint-order: stroke;
}
/* SVG-native legend TYPE is now shared across the four keyed charts — see the
   `.chart-key-*` rules in _chart-family/chart-family.css (the geometry is emitted
   by svg-legend.js). The pie no longer owns per-chart key text rules. */

/* Categorical wedge / swatch palette — six-rotation on the shared chart
 * category model (--catN-fill = wedge fill, --catN-ink = wedge border /
 * swatch border). Pale fill + deep border on light, deep fill + pale border
 * on dark; fill and border always the same hue. Six is the cap for
 * perceptual distinction (Wong 2011, Cleveland-McGill, IBM Carbon);
 * pies that need >6 categories should consolidate "Other" or split.
 *
 * Wedges count by nth-of-TYPE, not nth-child: the SVG's first child is the
 * <defs> block (gradient definitions), which would offset nth-child by one and
 * shift every wedge's border to the NEXT slot's hue (the teal wedge picking up
 * --cat6 rose was the visible tell). nth-of-type(<path>) ignores <defs> AND the
 * trailing spine <rect> / legend <rect>+<text> (different element types). The
 * wedge FILL here is overridden by the kernel's inline radial gradient; these
 * rules supply the per-slot STROKE (--catN-ink). The legend swatches are now
 * SVG <rect class="pie-key-swatch"> coloured inline by the kernel (slot hue +
 * --catN-ink edge), so they no longer ride these selectors.
 * See engineering/gotchas.md "Pie wedge borders off-by-one". */
:is(section.piechart, figure.chart-frame) .wedge:nth-of-type(6n+1) { fill: var(--chart-cat-1-fill); stroke: var(--chart-cat-1-ink); }
:is(section.piechart, figure.chart-frame) .wedge:nth-of-type(6n+2) { fill: var(--chart-cat-2-fill); stroke: var(--chart-cat-2-ink); }
:is(section.piechart, figure.chart-frame) .wedge:nth-of-type(6n+3) { fill: var(--chart-cat-3-fill); stroke: var(--chart-cat-3-ink); }
:is(section.piechart, figure.chart-frame) .wedge:nth-of-type(6n+4) { fill: var(--chart-cat-4-fill); stroke: var(--chart-cat-4-ink); }
:is(section.piechart, figure.chart-frame) .wedge:nth-of-type(6n+5) { fill: var(--chart-cat-5-fill); stroke: var(--chart-cat-5-ink); }
:is(section.piechart, figure.chart-frame) .wedge:nth-of-type(6n)   { fill: var(--chart-cat-6-fill); stroke: var(--chart-cat-6-ink); }

/* === lib/components/legal/policy-recommendation/policy-recommendation.styles.css === */
/* policy-recommendation — legal · statement · panel · structure
 *
 * A legislative recommendation: a stance VERDICT badge in the masthead bay, the
 * recommendation as the hoisted title, then the argument in the stage — impact
 * lede, evidence-grounded reasons, and the closing legislative ASK.
 *
 * Palette-blind (var(--token) only, no hex) and margin-free (padding / gap).
 * The stance variant (`adopt` / `amend` / `oppose` / `defer`) sets three seams —
 * --stance (the strong color), --stance-bg (its tint), --stance-label (the badge
 * text) — and the badge, the masthead rule, the stage rail, the reason borders,
 * and the ask bar all read from them, so one variant recolors the whole brief.
 *
 * Rules are UNLAYERED (no `@layer components` wrapper) to match every other
 * component file — broad @layer activation is blocked, and an unlayered base rule
 * beats a layered one regardless of specificity (engineering/cascade.md).
 */

  /* ── Stance seams. Base = a neutral recommendation with no verdict. ──────────
   * `--stance-bg` is derived from `--stance` as an OPAQUE tint over the canvas —
   * NOT the theme's `--*-bg` soft tokens, which are `color-mix(… N%, transparent)`.
   * A semi-transparent fill renders fine over white but reads as near-black to the
   * WCAG contrast gate (it can't composite alpha), sinking the ask bar's heading
   * to ~1.8:1. Mixing over `--bg` gives the SAME color over the light canvas while
   * staying opaque, so the gate measures the real navy-on-tint (~9:1) and the
   * "filled stance bar" reads as filled. Each variant sets only `--stance`; the
   * bg re-derives from it lazily at use. */
  section.policy-recommendation {
    --stance: var(--accent);
    --stance-bg: color-mix(in srgb, var(--stance) 12%, var(--bg));
    --stance-label: "Recommendation";
  }
  section.policy-recommendation.adopt  { --stance: var(--pass); --stance-label: "Adopt"; }
  section.policy-recommendation.amend  { --stance: var(--warn); --stance-label: "Amend"; }
  section.policy-recommendation.oppose { --stance: var(--fail); --stance-label: "Oppose"; }
  section.policy-recommendation.defer  { --stance: var(--text-secondary); --stance-label: "Defer"; }

  /* ── Masthead: the legislative letterhead. A stance hairline under the band, and
   *    the verdict badge docked in the reserved right bay. ───────────────────── */
  section.policy-recommendation > .cell-masthead {
    border-bottom: 2px solid var(--stance);
    padding-bottom: var(--sp-xs);
  }
  section.policy-recommendation > .cell-masthead > .masthead-bay::before {
    content: var(--stance-label);
    font-family: var(--font-label);
    font-size: var(--fs-meta);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: var(--stance);
    background: var(--stance-bg);
    border: 1px solid var(--stance);
    border-radius: var(--radius-sm);
    padding: var(--sp-3xs) var(--sp-sm);
    white-space: nowrap;
  }

  /* ── Stage: the argument. A stance rail ties the body to the verdict above. ─── */
  section.policy-recommendation > .cell-stage {
    display: flex;
    flex-direction: column;
    gap: var(--sp-md);
    padding-left: var(--sp-lg);
    border-left: 4px solid var(--stance);
  }

  /* Impact — the one-line framing of the stakes. */
  section.policy-recommendation > .cell-stage > p {
    font-size: var(--fs-message);
    color: var(--text-secondary);
    line-height: var(--lh-snug);
    padding: 0;
  }

  /* Rationale — evidence-grounded reasons; the reason bold, its evidence nested. */
  section.policy-recommendation > .cell-stage > ul {
    list-style: none;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: var(--sp-md);
    flex: 1;
    justify-content: center;
  }
  section.policy-recommendation > .cell-stage > ul > li {
    padding-left: var(--sp-md);
    border-left: 3px solid var(--stance);
    font-size: var(--fs-message);
    line-height: var(--lh-snug);
    font-weight: 700;
    color: var(--text-heading);
  }
  /* Nested evidence line — resets to body weight/color; the citation rides a chip. */
  section.policy-recommendation > .cell-stage > ul > li > ul {
    list-style: none;
    padding: var(--sp-3xs) 0 0 0;
  }
  section.policy-recommendation > .cell-stage > ul > li > ul > li {
    font-weight: 400;
    color: var(--text-body);
    font-size: var(--fs-body);
    line-height: var(--lh-base);
  }
  /* Element siblings of the bolded lead don't inherit its weight (matches the
   * CARD_STYLE_LAYOUTS hardening in cards-grid). */
  section.policy-recommendation > .cell-stage > ul > li > :is(ul, ol) { font-weight: 400; }

  /* Citation chip — the trailing inline-code on an evidence line. */
  section.policy-recommendation > .cell-stage > ul > li > ul > li > code {
    font-family: var(--pill-font);
    font-size: var(--pill-fs);
    font-weight: var(--pill-weight);
    letter-spacing: var(--pill-tracking);
    border-radius: var(--pill-radius);
    padding: var(--pill-pad-y) var(--pill-pad-x);
    white-space: nowrap;
    background: var(--bg-alt);
    border: 1px solid var(--border);
    color: var(--text-secondary);
  }

  /* The ask — the closing legislative call to action, a filled stance bar.
   * The trailing blockquote renders as a DIRECT `section > blockquote` on some
   * paths and inside `.cell-stage` on others, so match it with a descendant
   * combinator (this component has exactly one blockquote). policy-recommendation
   * is excluded from the base KEY INSIGHT treatment (base.modifiers.css), so these
   * rules own the blockquote uncontested. */
  section.policy-recommendation blockquote {
    background: var(--stance-bg);
    border: 1px solid var(--stance);
    border-left: 4px solid var(--stance);
    border-radius: var(--radius-md);
    padding: var(--sp-sm) var(--sp-md);
    flex-shrink: 0;
  }
  section.policy-recommendation blockquote::before {
    content: "The ask";
    display: block;
    font-family: var(--font-label);
    font-size: var(--fs-meta);
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--stance);
    padding-bottom: var(--sp-3xs);
  }
  section.policy-recommendation blockquote p {
    font-family: var(--font-body);
    font-size: var(--fs-message);
    color: var(--text-heading);
    line-height: var(--lh-snug);
    padding: 0;
  }

  /* ── Portrait / square reflow (adapt.mode: reflow). Tighten the rhythm and let
   *    the reasons pack from the top instead of centering in a tall box. ─────── */
  @container lattice (aspect-ratio <= 1.05) {
    section.policy-recommendation > .cell-stage { gap: var(--sp-sm); }
    section.policy-recommendation > .cell-stage > ul {
      flex: 0 0 auto;
      justify-content: flex-start;
    }
  }

/* === lib/components/comparison/pricing/pricing.styles.css === */
/* pricing — plan tiers with prices, feature checklists, and one recommended
 * column. See lib/components/comparison/pricing/pricing.manifest.json.
 *
 * Substance: structure. Authoring shape mirrors verdict-grid (nested cards
 * with [x]/[/]/[-] state markers), so the SAME badge transform fires on it —
 * `verdictGridBadges` (marp), the emulator's verdict-grid pass, and the
 * runtime's transformVerdictGridBadges all match `.pricing` too. Everything
 * else is CSS:
 *   ul > li             one tier card (auto-bold name, like cards-grid)
 *   li > code           the price (trailing inline code, promoted to display)
 *   li > em             the *Most popular* marker → a corner ribbon; its
 *                       presence (`:has(> em)`, a standalone :has — safe per
 *                       gotchas.md) elevates the card
 *   li > ul > li .badge feature rows (disc + label; pill chrome stripped)
 *   li > ul > li:last   the marker-less "who it's for" line, pinned to bottom
 *
 * Rules are UNLAYERED (no `@layer components` wrapper) to match every other
 * component file — broad @layer activation is blocked (see engineering/
 * cascade.md), so a wrapped file would lose to unlayered rules like the
 * shared `.badge` chrome regardless of specificity.
 */

section.pricing > .cell-stage { display: flex; flex-direction: column; }

/* ── Tier grid ── three columns by default; `two` / `four` adjust. */
section.pricing > .cell-stage > ul {
  /* flex mirror of `repeat(N,1fr)` (flex shop §11.A): N equal tiers per row, wrapping any
   * extras; align-items:stretch (default) gives a row of equal-height tiers. */
  display: flex;
  flex-wrap: wrap;
  align-content: stretch;
  gap: var(--sp-md);
  /* padding = berth so the stage's overflow:clip doesn't shear the tier-card
   * elevation shadow (base.tokens.css --elevation-berth). Not margin (#20). */
  flex: 1; list-style: none; padding: var(--elevation-berth); margin: 0;
}
section.pricing.two > .cell-stage > ul { --pricing-cols: 2; }
section.pricing.two > .cell-stage > ul > li { width: calc(100% / 2 - var(--sp-md) / 2); }
section.pricing.four > .cell-stage > ul { --pricing-cols: 4; }
section.pricing.four > .cell-stage > ul > li { width: calc(100% / 4 - 3 * var(--sp-md) / 4); }

/* ── Tier card ── auto-bold name via the card's own weight (cards-grid
 * pattern); children revert below. */
section.pricing > .cell-stage > ul > li {
  position: relative;
  /* outer flex item: N tiers per row (mirror of the 1fr columns). Uses `width` (not a
   * `flex`-shorthand calc basis, which renders unreliably) with the matrix-2x2 formula
   * `100%/N - (N-1)/N·gap` so N cards + (N-1) gaps tile the row exactly. Default 3; .two /
   * .four below. */
  width: calc(100% / 3 - 2 * var(--sp-md) / 3);
  box-sizing: border-box;
  min-width: 0;
  background: var(--bg-alt);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: var(--sp-md);
  display: flex; flex-direction: column; align-items: flex-start;
  font-size: var(--fs-message);
  font-weight: 700; color: var(--text-heading);
  line-height: var(--lh-tight);
  overflow: hidden;
  /* Struck elevation — zero-blur, light-dark()-flipping lift (base.tokens.css). */
  box-shadow: var(--elevation-card);
}
/* Back-compat: if an author wraps the name in **…**, render it identically. */
section.pricing > .cell-stage > ul > li > strong { font-weight: inherit; color: inherit; }

/* ── Price ── trailing inline code, promoted to a display figure. */
section.pricing > .cell-stage > ul > li > code {
  display: block;
  font-family: var(--font-display);
  font-size: var(--fs-emphasis);
  font-weight: 700; letter-spacing: 0;
  color: var(--text-heading);
  background: none; border: none; padding: var(--sp-2xs) 0 var(--sp-sm) 0;
}

/* ── Recommendation ribbon ── the author's *marker* renders top-right. */
section.pricing > .cell-stage > ul > li > em {
  position: absolute; top: 0; right: 0;
  font-style: normal; font-weight: 700;
  font-family: var(--pill-font);
  font-size: var(--pill-fs); letter-spacing: var(--pill-tracking);
  text-transform: uppercase;
  color: var(--on-accent); background: var(--accent);
  padding: var(--pill-pad-y) var(--sp-sm);
  border-bottom-left-radius: var(--radius-md);
}

/* ── Elevated tier ── any card carrying a marker (standalone :has). */
section.pricing > .cell-stage > ul > li:has(> em) {
  background: var(--accent-soft);
  border-color: var(--accent);
  /* accent ring composed OVER the Struck lift — this tier both pops and floats. */
  box-shadow: inset 0 0 0 1px var(--accent), var(--elevation-card);
  color: var(--on-accent-soft);
}
section.pricing > .cell-stage > ul > li:has(> em) > code { color: var(--on-accent-soft); }

/* ── Feature list ── fills the card so the caption can pin to the bottom;
 * weight reverts from the card's 700. */
section.pricing > .cell-stage > ul > li > ul {
  list-style: none; padding: var(--sp-sm) 0 0 0; margin: 0;
  width: 100%; flex: 1 1 auto;
  display: flex; flex-direction: column; gap: var(--sp-2xs);
  font-weight: 400;
}
section.pricing > .cell-stage > ul > li > ul > li {
  font-size: var(--fs-body-compact);
  font-weight: 400; color: var(--text-body);
  line-height: var(--lh-snug);
}
/* Badge feature rows — strip verdict-grid's pill chrome, keep the disc +
 * mark (::before/::after) and left-align. Padding is preserved so the
 * absolute ::after mark stays registered over the ::before disc. */
section.pricing > .cell-stage > ul > li > ul > li > .badge {
  background: none; border: none;
  justify-content: flex-start;
  font-family: inherit; font-size: inherit; font-weight: 400;
  letter-spacing: 0; color: var(--text-body);
}
/* ── "Who it's for" line ── the marker-less last nested li, pinned bottom. */
section.pricing > .cell-stage > ul > li > ul > li:last-child {
  flex: 1 1 auto; display: flex; flex-direction: column; justify-content: flex-end;
  padding-top: var(--sp-sm);
  font-size: var(--fs-meta); color: var(--text-muted);
}
section.pricing > .cell-stage > ul > li:has(> em) > ul > li:last-child { color: var(--on-accent-soft); }

/* ── Portrait / square reflow (social/mobile @sizes). Keyed on the deck-wide
 * data-orientation stamp (lib/engine/slides.js); landscape untouched. See
 * 2026-06-16-social-mobile-portrait-sizes.md (phase 3). */  Tiers stack to one column (the standard mobile pricing pattern).
section.pricing[data-orientation="portrait"] > .cell-stage > ul {
  flex-direction: column;
}
section.pricing[data-orientation="portrait"] > .cell-stage > ul > li {
  flex: 0 0 auto;
}
/* Box-local family reflow (2026-06-18-component-adaptive-sizing.md): tall+strip
 * (≤0.9) stack the tiers to one column, keyed on the nearest `lattice` container
 * so it fires on a portrait deck AND inside a narrow nested cell — replacing the
 * deck-wide data-orientation stamp. Doubled class reaches (0,2,2) to match the
 * [data-orientation] reflow it mirrors. */
@container lattice (aspect-ratio <= 0.9) {
  section.pricing.pricing > .cell-stage > ul {
    flex-direction: column;
  }
  section.pricing.pricing > .cell-stage > ul > li {
    flex: 0 0 auto;
  }
}

/* === lib/components/chart/progress/progress.styles.css === */
/* progress — extracted from lib/_legacy.css (batch 9).
 * See lib/components/progress/progress.manifest.json for the component contract.
 */

/* ── PROGRESS ──
 * Stack of horizontal bars, one per list item. Each row carries a label,
 * a bar (filled to --pct), a numeric readout, and an optional status pill.
 * The fill colour tints with the status. */
:is(section.progress, figure.progress).chart-frame .chart-body {
  /* Inherit the base width (calc(100cqi - 2*sp-2xl), centered) and padding so
   * the surface panel matches every other chart — the old width:100% +
   * max-width:76.5cqi made the progress panel noticeably narrower (big side
   * margins) than the rest. Bars still stretch + gap within the shared width. */
  align-items: stretch;
  gap: var(--sp-md);
}
/* Every row uses the SAME fixed grid template, so the 1fr track is
 * identical across rows. `auto` columns would size to per-row content
 * (varying status-pill widths) and make tracks disagree. */
:is(section.progress, figure.progress) .progress-bars {
  display: flex;
  flex-direction: column;
  row-gap: 0.46875cqi;
  width: 100%;
}
:is(section.progress, figure.progress) .progress-row {
  display: grid;
  /* label · track · pill — the % readout now lives INSIDE the fill (right-
   * aligned on the colored bar, like a gantt bar's in-bar label), so it no
   * longer needs its own column. */
  grid-template-columns: 18.75cqi 1fr 7.5cqi;
  align-items: center;
  column-gap: var(--sp-md);
}
:is(section.progress, figure.progress) .progress-label {
  font-size: var(--fs-body);
  font-weight: 500;
  color: var(--text-heading);
  text-align: right;
}
:is(section.progress, figure.progress) .progress-track {
  position: relative;
  /* NO rail. The track is a transparent positioning context only — the fill is
   * a self-contained bordered tile that "shoots forward" on the bare canvas
   * (like a gantt bar floating on its lane). A gray rail behind it diluted the
   * row and washed the fill out; the magnitude is carried by the bar's length,
   * its leading-edge intensity (see the fill), and the printed %. overflow:hidden
   * + radius clip the fill's rounded corners. */
  height: 2.5cqi;
  background: transparent;
  border-radius: 0.46875cqi;
  overflow: hidden;
}
:is(section.progress, figure.progress) .progress-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--pct) * 1%);
  /* CHART-FAMILY MATERIAL, progress-SPECIALIZED GEOMETRY. Progress shares the
   * family's hue/ink palette (--fill-* below), 1px hue-tint border, and 4px
   * vivid left accent — the same MATERIAL as the kanban card / gantt bar /
   * state node. What it specializes is the GRADIENT: progress is the only
   * family member with a magnitude (--pct), so it encodes that magnitude in the
   * fill rather than wearing the shared vertical wash. The gradient runs
   * HORIZONTALLY (the direction the bar grows) and "shoots forward" — pale/dark
   * tail at the origin ramping to a saturated LEADING-EDGE head whose intensity
   * scales with --pct: a 92% bar ramps to a vivid head, a 12% bar stays dim and
   * stalled. So value is double-encoded (length AND intensity). The head mix %
   * is calc(base + --pct * k); canvas-aware via light-dark() — mixes into --bg
   * on light, toward black on dark (mirrors --state-*-fill, mud-free). The other
   * members keep the shared --chart-fill-* vertical wash (they have no --pct).
   * A bar with no status is the categorical cat1 slot; status variants re-point
   * the --fill-* pair. Authors pin a categorical hue with `--fill`. */
  --fill-hue: var(--fill, var(--chart-cat-1-hue));
  --fill-ink: var(--chart-cat-1-ink);
  background: linear-gradient(90deg,
    light-dark(color-mix(in oklab, var(--fill-hue) 12%, var(--bg)),
               color-mix(in oklab, var(--fill-hue) 30%, black)) 0%,
    light-dark(color-mix(in oklab, var(--fill-hue) calc(20% + var(--pct) * 0.52%), var(--bg)),
               color-mix(in oklab, var(--fill-hue) calc(38% + var(--pct) * 0.58%), black)) 100%);
  border: var(--chart-hairline) solid color-mix(in oklab, var(--fill-hue) var(--chart-fill-edge), var(--border));
  border-left: var(--chart-fill-accent) solid var(--fill-ink);
  border-radius: 0.46875cqi;
  transition: none;
  /* The % readout rides the bar's leading edge: right-aligned ON the colored
   * fill, like a gantt bar's in-bar label. --text-heading clears the wash on
   * both canvases. */
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 0.625cqi;
  overflow: hidden;
}
/* Each status re-points the --fill-* pair; the canonical recipe picks it up.
 * Canvas-aware via light-dark(), so one rule each. */
:is(section.progress, figure.progress) .progress-fill[data-s="on-track"],
:is(section.progress, figure.progress) .progress-fill[data-s="done"],
:is(section.progress, figure.progress) .progress-fill[data-s="live"] { --fill-hue: var(--state-pass-hue); --fill-ink: var(--state-pass-ink); }
:is(section.progress, figure.progress) .progress-fill[data-s="at-risk"],
:is(section.progress, figure.progress) .progress-fill[data-s="warn"]   { --fill-hue: var(--state-warn-hue); --fill-ink: var(--state-warn-ink); }
:is(section.progress, figure.progress) .progress-fill[data-s="blocked"],
:is(section.progress, figure.progress) .progress-fill[data-s="fail"]   { --fill-hue: var(--state-fail-hue); --fill-ink: var(--state-fail-ink); }
:is(section.progress, figure.progress) .progress-fill[data-s="deferred"] { --fill-hue: var(--state-mute-hue); --fill-ink: var(--state-mute-ink); }
:is(section.progress, figure.progress) .progress-pct {
  font-family: var(--font-mono);
  font-size: var(--fs-meta);
  font-weight: 700;
  color: var(--text-heading);
  /* The readout rides the fill's LEADING EDGE — exactly where the gradient ramps
   * to its most saturated head (calc(20% + --pct*0.52%), up to 72%), so a high-%
   * bar's dark --text-heading lost contrast on the LIGHT canvas (gantt sidesteps
   * this by capping its flat fill at 38%; progress can't — its vivid head IS the
   * magnitude signal, and on the DARK canvas it reads great). Rather than flatten
   * the fill, the number sits on a small READOUT PLATE: the bar's own hue mixed
   * hard toward the canvas (pale on light, deep on dark) so --text-heading always
   * clears it, on either canvas, at any --pct. Stays in-family (hue-tinted, not a
   * jarring white box) and reads as an intentional data badge. */
  background: light-dark(color-mix(in oklab, var(--fill-hue) 16%, var(--bg)),
                         color-mix(in oklab, var(--fill-hue) 22%, black));
  padding: 0.16cqi 0.55cqi;
  border-radius: 0.55cqi;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  line-height: 1;
}
/* Pills right-align in their column so all pill right edges line up. */
:is(section.progress, figure.progress) .progress-row > .chart-status,
:is(section.progress, figure.progress) .progress-row > .chart-status-empty {
  justify-self: end;
}
/* Optional row sub-bullet — rendered as a small footnote under the bar. */
:is(section.progress, figure.progress) .progress-note {
  grid-column: 2 / 3;
  /* Nudge the note up under the bar via transform (was margin-top: -0.3125cqi).
   * Transform is the measurable, margin-free equivalent — no margin to collapse
   * outside the grid/flex content box and confuse virtual-list scrollHeight. */
  transform: translateY(-0.3125cqi);
  font-size: var(--fs-meta);
  color: var(--text-secondary);
  font-style: italic;
}

/* ── Box-local FILL (square + tall + strip, ≤1.05): the bars already stack, but
 * on a tall/square box they crowd the top and leave the canvas empty. Distribute
 * the rows down the full height and thicken the tracks so the bars read big.
 * Keyed on the nearest `lattice` container; landscape untouched. See
 * engineering/decisions/2026-06-19-chart-adaptive-sizing.md. */
@container lattice (aspect-ratio <= 1.05) {
  :is(section.progress, figure.progress) .progress-bars {
    height: 100%;
    justify-content: space-evenly;
    row-gap: var(--sp-md);
  }
  :is(section.progress, figure.progress) .progress-track { height: 4cqi; }
  :is(section.progress, figure.progress) .progress-label { font-size: var(--fs-message); }
}

/* === lib/components/inventory/q-and-a/q-and-a.styles.css === */
/* q-and-a — anticipated questions paired with prepared answers. The
 * end-of-pitch "what we expect to be asked" slide: a few weighty defenses of
 * a recommendation. Distinct from a reference `faq` (many terse look-ups) and
 * from `list-criteria` (evaluation criteria + rationale).
 *
 * Substance: structure. Pure CSS over the native nested list — no
 * post-processor, so no three-render-path wiring. The author writes:
 *
 *   - Question text?
 *     - The prepared answer.
 *
 * The top-level li is the question; the nested li is the answer. Questions are
 * indexed (01, 02, …) by a CSS counter, so `ul` and `ol` render identically.
 *
 * Looks — mutually exclusive, pick at most one:
 *   q-and-a          editorial ledger — numbered index + accent rule (default)
 *   q-and-a spine    sequential walkthrough — accent nodes on a vertical spine
 *   q-and-a rail     question / answer columns, numbered (exhibit table)
 *   q-and-a tab      underlined prompts — a true header underline per question
 *   q-and-a grid     two-up quadrant grid for density, with a gradient cross
 *
 * Universal modifiers (compose with the default ledger):
 *   q-and-a solo     one question, one answer, given the whole slide
 *   q-and-a compact  denser rhythm for five-plus pairs
 *   q-and-a dark     dark canvas (every colour is a light-dark() token, so the
 *                    five looks invert without per-look overrides)
 *
 * Rules are UNLAYERED (no `@layer components` wrapper) to match every other
 * component file — broad @layer activation is blocked (see engineering/
 * cascade.md), so a wrapped file would lose to unlayered rules regardless
 * of specificity.
 *
 * ── QUESTION WRAPPER (flex enabler) ───────────────────────────────────────
 * The org is flex-first ("flex shop", flex cell-tree §10). Every look here is flex —
 * including `rail` (number | question | answer columns) and `grid` (2×2 quadrants with a
 * reserved question row), which need to SIZE the question. Flex sizes items you can select,
 * and the question is a list item's lead text — so q-and-a opts into `slotLabelLift` (the
 * shared markdown-it kernel rule, same as decision / statute-stack / actors): the question is
 * wrapped in `<strong>`, giving flex a selectable hook (`> li > strong`). The wrapper is
 * visually TRANSPARENT (font:inherit) for the stream looks; rail/grid use it for layout.
 * A bare renderer that skips the kernel (raw VS Code preview) leaves the question unwrapped —
 * rail/grid then fall back to the single-column ledger via `:not(:has(> strong))`. */

section.q-and-a > .cell-stage {
  /* Index gutter — proportional to the number's own size, NOT a fixed step. The "01"
   * counter is sized off --fs-message, which grows from landscape to portrait; a fixed
   * gutter cleared the number in landscape but the portrait number overran it (the
   * "01Why" collision). Sizing the gutter off the counter keeps a constant gap in
   * every orientation without over-widening (which would crush the text column). */
  --qa-index: calc(var(--fs-message) * 0.8); /* the index number reads as a label, not a 2nd headline */
  --qa-gutter: calc(var(--sp-xs) + var(--qa-index) * 2.1);
  --qa-gap: var(--sp-md); /* vertical gap between pairs */
}

/* The pair stack fills the canvas below the headline and centres its rows. */
section.q-and-a > .cell-stage > :is(ul, ol) {
  list-style: none;
  margin: 0;
  padding: 0;
  width: 100%;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: var(--qa-gap);
  /* `--lat-split-offset` is set by the auto-splitter on a cover-paginate body page (the
     count of pairs on prior pages), so a split q-and-a continues its index (…03, 04) rather
     than restarting at 01 on every page. 0 (the default) on an unsplit slide. */
  counter-reset: qa var(--lat-split-offset, 0);
}

/* ── default · editorial ledger ───────────────────────────────────────── */
/* One Q/A pair. The li's own text is the question; the nested list is the
 * answer. A 2px accent rule runs down the left of each pair and the numbered
 * index hangs in the gutter, baseline-aligned with the question. */
section.q-and-a > .cell-stage > :is(ul, ol) > li {
  counter-increment: qa;
  position: relative;
  padding-left: var(--qa-gutter);
  border-left: 2px solid var(--accent);
  font-family: var(--font-display);
  font-size: var(--fs-message);
  font-weight: 600;
  color: var(--text-heading);
  line-height: var(--lh-snug);
}
section.q-and-a > .cell-stage > :is(ul, ol) > li::before {
  content: "0" counter(qa);
  position: absolute;
  left: var(--sp-xs);
  top: 0;
  font-family: var(--font-mono);
  font-size: var(--qa-index);
  font-weight: 600;
  line-height: var(--lh-snug);
  color: var(--accent);
}
/* The question is lifted into <strong> by slotLabelLift so flex can size it (rail/grid).
 * Transparent by default — it inherits the question's own type so the stream looks
 * (ledger / spine / tab / solo / compact) read exactly as a bare text node would. */
section.q-and-a > .cell-stage > :is(ul, ol) > li > strong {
  font: inherit;
  color: inherit;
  letter-spacing: inherit;
}

/* Answer — the nested list, reset off the question's weight/size/colour. */
section.q-and-a > .cell-stage > :is(ul, ol) > li > :is(ul, ol) {
  list-style: none;
  padding: var(--sp-xs) 0 0;
}
section.q-and-a > .cell-stage > :is(ul, ol) > li > :is(ul, ol) > li {
  font-family: var(--font-body);
  font-size: var(--fs-body);
  font-weight: 400;
  color: var(--text-body);
  line-height: var(--lh-base);
}

/* ── spine — sequential walkthrough ───────────────────────────────────── */
/* Drops the ledger rule and index for a vertical spine with accent nodes; the
 * node halo is the canvas colour so it punches cleanly through the line. */
section.q-and-a.spine > .cell-stage > :is(ul, ol) {
  position: relative;
  /* border-box so the spine's own `padding-left` is absorbed WITHIN the inherited
   * `width:100%` (base ul rule) — `box-sizing` isn't inherited, so a content-box ul
   * would add sp-xl on top of 100% and push the answer column past the stage's right
   * edge (horizontal clip on a long answer line). #547. */
  box-sizing: border-box;
  padding-left: var(--sp-xl);
  gap: var(--sp-lg);
}
section.q-and-a.spine > .cell-stage > :is(ul, ol)::before {
  content: "";
  position: absolute;
  left: 0.4cqi;
  top: 0.5em;
  bottom: 0.5em;
  width: 0.16cqi;
  background: var(--border);
}
section.q-and-a.spine > .cell-stage > :is(ul, ol) > li {
  padding-left: 0;
  border-left: none;
}
section.q-and-a.spine > .cell-stage > :is(ul, ol) > li::before {
  content: "";
  left: calc(-1 * var(--sp-xl));
  top: 0.42em;
  width: 0.95cqi;
  height: 0.95cqi;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 0.3cqi var(--bg);
}

/* ── rail — question / answer columns ─────────────────────────────────── */
/* The pair becomes a three-column exhibit row: number | question | answer,
 * separated by a hairline. The index drops into the flow as the first cell. */
section.q-and-a.rail > .cell-stage > :is(ul, ol) {
  gap: var(--sp-lg);
}
/* flex mirror of `grid-template-columns:auto minmax(0,0.46fr) minmax(0,0.54fr)`: the index is
 * a natural-width first item; the question (<strong>) and answer (ul) split the rest 46:54 via
 * matching flex-grow on a zero basis — exactly what the two fr tracks did. */
section.q-and-a.rail > .cell-stage > :is(ul, ol) > li {
  display: flex;
  align-items: start;
  column-gap: var(--sp-2xl);
  padding-left: 0;
  padding-bottom: var(--sp-lg);
  border-left: none;
  border-bottom: 1px solid var(--border);
}
section.q-and-a.rail > .cell-stage > :is(ul, ol) > li:last-child {
  padding-bottom: 0;
  border-bottom: none;
}
section.q-and-a.rail > .cell-stage > :is(ul, ol) > li::before {
  content: counter(qa);
  position: static;
  flex: 0 0 auto;
  font-weight: 700;
}
section.q-and-a.rail > .cell-stage > :is(ul, ol) > li > strong {
  flex: 0.46 1 0;
  min-width: 0;
}
section.q-and-a.rail > .cell-stage > :is(ul, ol) > li > :is(ul, ol) {
  flex: 0.54 1 0;
  min-width: 0;
  padding: 0;
}

/* ── tab — underlined prompts ─────────────────────────────────────────── */
/* No index; a short accent underline sits tight beneath each question, then
 * the answer drops below it with its own breathing room. */
section.q-and-a.tab > .cell-stage > :is(ul, ol) {
  gap: var(--sp-lg);
}
section.q-and-a.tab > .cell-stage > :is(ul, ol) > li {
  padding-left: 0;
  border-left: none;
}
section.q-and-a.tab > .cell-stage > :is(ul, ol) > li::before {
  display: none;
}
section.q-and-a.tab > .cell-stage > :is(ul, ol) > li > :is(ul, ol) {
  position: relative;
  /* the sp-2xs that separated the question from the underline now rides INSIDE the ul as
     extra top padding, with the underline (::before) dropped by the same sp-2xs so it lands
     where it did — keeps the box measurable (no margin-top above the ul). */
  padding-top: calc(var(--sp-md) + var(--sp-2xs));
}
section.q-and-a.tab > .cell-stage > :is(ul, ol) > li > :is(ul, ol)::before {
  content: "";
  position: absolute;
  top: var(--sp-2xs);
  left: 0;
  width: 2.4em;
  height: 0.25cqi;
  background: var(--accent);
}

/* ── grid — two-up quadrant density ───────────────────────────────────── */
/* Four pairs in a 2×2 grid divided by a gradient hairline cross. Each cell's
 * header reserves two lines so question tops and answer baselines align across
 * a row whether or not a question wraps. */
/* flex mirror of a 2×2 grid (flex shop §11.A, the matrix-2x2 recipe): wrap four cells, each
 * a border-box half-minus-half-gap in both axes, so they tile the quadrant. */
section.q-and-a.grid > .cell-stage > :is(ul, ol) {
  display: flex;
  flex-direction: row;   /* override the base column stream — the quadrant tiles in rows */
  flex-wrap: wrap;
  align-content: stretch;
  gap: var(--sp-xl) var(--sp-2xl);
  position: relative;
}
section.q-and-a.grid > .cell-stage > :is(ul, ol)::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 1px;
  transform: translateX(-50%);
  background: linear-gradient(to bottom, transparent, var(--border) 18%, var(--border) 82%, transparent);
}
section.q-and-a.grid > .cell-stage > :is(ul, ol)::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  height: 1px;
  transform: translateY(-50%);
  background: linear-gradient(to right, transparent, var(--border) 18%, var(--border) 82%, transparent);
}
section.q-and-a.grid > .cell-stage > :is(ul, ol) > li {
  box-sizing: border-box;
  width: calc(50% - var(--sp-2xl) / 2);
  height: calc(50% - var(--sp-xl) / 2);
  /* flex mirror of `grid-template-rows:minmax(3em,auto) auto` + the outer `align-items:center`:
   * a centred column whose question (<strong>) reserves a 3em row so answer tops baseline-align
   * across the quadrant whether or not a question wraps. */
  display: flex;
  flex-direction: column;
  justify-content: center;
  row-gap: var(--sp-xs);
  border-left: none;
}
section.q-and-a.grid > .cell-stage > :is(ul, ol) > li > strong {
  min-height: 3em;
}
section.q-and-a.grid > .cell-stage > :is(ul, ol) > li > :is(ul, ol) {
  padding: 0;
}

/* ── bare-renderer fallback ────────────────────────────────────────────────
 * rail + grid size the question via the lifted <strong>. A renderer that skips the kernel
 * (raw VS Code preview) leaves the question unwrapped, so there's no hook to proportion —
 * fall back to a single-column stack rather than mis-size an unselectable text node. */
section.q-and-a:is(.rail, .grid) > .cell-stage > :is(ul, ol):not(:has(> li > strong)) {
  display: flex;
  flex-direction: column;
  flex-wrap: nowrap;
  gap: var(--qa-gap);
}
section.q-and-a:is(.rail, .grid) > .cell-stage > :is(ul, ol):not(:has(> li > strong)) > li {
  display: block;
  width: auto;
  height: auto;
}
section.q-and-a.grid > .cell-stage > :is(ul, ol):not(:has(> li > strong))::before,
section.q-and-a.grid > .cell-stage > :is(ul, ol):not(:has(> li > strong))::after {
  display: none;
}

/* ── compact — the density escape hatch for five-plus pairs ───────────── */
/* A pure opt-in on the ledger: the question and its index drop from message to
 * body type, the answer to compact-body, and the gaps close. */
section.q-and-a.compact > .cell-stage {
  --qa-gap: var(--sp-sm);
}
section.q-and-a.compact > .cell-stage > :is(ul, ol) > li {
  font-size: var(--fs-body);
}
section.q-and-a.compact > .cell-stage > :is(ul, ol) > li::before {
  font-size: var(--fs-body);
}
section.q-and-a.compact > .cell-stage > :is(ul, ol) > li > :is(ul, ol) {
  padding-top: var(--sp-2xs);
}
section.q-and-a.compact > .cell-stage > :is(ul, ol) > li > :is(ul, ol) > li {
  font-size: var(--fs-body-compact);
}

/* ── solo — one question, one answer, the whole slide ─────────────────── */
/* Solo sizes the question (and its index) off --fs-emphasis, so it re-bases --qa-index
 * to that scale — the gutter (calc'd from --qa-index) then clears the larger number too,
 * rather than overrunning a gutter sized for the default index. */
section.q-and-a.solo {
  --qa-index: calc(var(--fs-emphasis) * 0.8);
}
section.q-and-a.solo > .cell-stage > :is(ul, ol) {
  gap: 0;
}
section.q-and-a.solo > .cell-stage > :is(ul, ol) > li {
  font-size: var(--fs-emphasis);
  line-height: var(--lh-tight);
}
section.q-and-a.solo > .cell-stage > :is(ul, ol) > li::before {
  font-size: var(--qa-index);
  line-height: var(--lh-tight);
}
section.q-and-a.solo > .cell-stage > :is(ul, ol) > li > :is(ul, ol) {
  padding-top: var(--sp-md);
}
section.q-and-a.solo > .cell-stage > :is(ul, ol) > li > :is(ul, ol) > li {
  font-size: var(--fs-message);
  line-height: var(--lh-snug);
}

/* ── Box-local family reflow (engineering/decisions/2026-06-18-component-adaptive-sizing.md).
   The default ledger, spine, and tab looks are already single-column streams and
   need no reflow. Two looks pack horizontally and crush in a tall box: `grid`
   (2×2 quadrant) and `rail` (number | question | answer columns). Collapse both to
   a single vertical column — grid drops its cross rules, rail falls back to the
   ledger's hanging-index form — so a portrait deck (or a narrow nested cell) reads
   one pair per band. Keyed on the nearest `lattice` container's aspect. */
@container lattice (aspect-ratio <= 0.9) {
  /* grid 2×2 → one column; retire the dividing cross. The container is a flex/grid
     descendant (`> ul`) so the container query CAN restyle it: drop to a flex column
     so the pairs pack by content height + gap (the grid's stretched auto-rows left
     huge gaps), and reset each pair's reserved two-line header to natural height. */
  section.q-and-a.grid > .cell-stage > :is(ul, ol) {
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: stretch;
    gap: var(--sp-lg);
  }
  /* release the quadrant cell sizing — natural-height pairs in the single column. */
  section.q-and-a.grid > .cell-stage > :is(ul, ol) > li { width: auto; height: auto; justify-content: flex-start; }
  section.q-and-a.grid > .cell-stage > :is(ul, ol) > li > strong { min-height: 0; }
  section.q-and-a.grid > .cell-stage > :is(ul, ol)::before,
  section.q-and-a.grid > .cell-stage > :is(ul, ol)::after { display: none; }
  /* rail columns → the ledger's hanging-index block so Q and A stack legibly. */
  section.q-and-a.rail > .cell-stage > :is(ul, ol) > li {
    display: block;
    position: relative; /* self-contained context for the absolute index ::before */
    padding-left: var(--qa-gutter);
    padding-bottom: var(--sp-lg);
    border-left: 2px solid var(--accent);
  }
  section.q-and-a.rail > .cell-stage > :is(ul, ol) > li::before {
    content: "0" counter(qa);
    position: absolute;
    left: var(--sp-md);
    top: 0;
  }
  section.q-and-a.rail > .cell-stage > :is(ul, ol) > li > :is(ul, ol) { padding-top: var(--sp-xs); }
}

/* === lib/components/chart/quadrant/quadrant.styles.css === */
/* quadrant — extracted from lib/_legacy.css (batch 8).
 * See lib/components/quadrant/quadrant.manifest.json for the component contract.
 */

/* ── QUADRANT ───────────────────────────────────────────────────────────────
 * Native 2×2 quadrant chart — build-time SVG, no charting library.
 *
 * Source contract: a group-by-quadrant nested <ul>. Each top-level <li> is
 * a quadrant label (reading order: TL, TR, BL, BR); nested <li>s are items
 * with a trailing `<code>x, y</code>` pill. The eyebrow declares axis names
 * and (optionally) per-axis ranges + threshold target lines.
 *
 * Layout output:
 *   <div class="quadrant-figure" data-variant="default" data-groups="4" data-items="N">
 *     <svg class="quadrant-svg" viewBox="0 0 420 348">
 *       <g class="quadrant-tints">…four region rects…</g>
 *       <g class="quadrant-frame">…bounds + midlines/target lines…</g>
 *       <g class="quadrant-axes">…axis labels + corner ticks…</g>
 *       <g class="quadrant-labels">…four corner labels…</g>
 *       <g class="quadrant-plot">…dots + dot labels…</g>
 *     </svg>
 *   </div>
 *
 * One default + five modifier variants — see lib/quadrant.js. `minimal`
 * (no tints) and `dark` (lifted grid) are composable cross-cutting
 * modifiers handled here in CSS.
 *
 * Per-cell colour rides --cell-color, set per-rect/dot/label from the
 * categorical palette in lib/quadrant.js. Layouts stay palette-blind.
 *
 * Sibling implementations:
 *   - lib/quadrant.js       transform module (canonical)
 *   - lattice-emulator.js   per-slide HTML-string transform
 *   - lib/engine           the engine render path
 *   - lattice-runtime.js    DOM transform for marp-vscode preview
 */

/* Palette routing — two contexts, one custom-property pair:
 *
 *   --cell-fill   pale -light background tint (region rect, hull, bubble)
 *   --cell-ink    deep -dark AA-paired ink (dot, label, stroke, text)
 *
 * Every variant draws straight from the curated categorical palette in
 * reading order — cell 0=TL→c1, 1=TR→c2, 2=BL→c3, 3=BR→c4 — exactly like
 * the other chart-family members (piechart, radar) cycle cN. There is no
 * per-quadrant semantic hue routing and no `--c-quadrant-*` alias layer:
 * the four corners are categories, coloured c1…c4, fill paired with ink
 * from the same slot (`--cN-light` / `--cN-dark`). Cohort inherits the
 * same `[data-cell]` routing — its groups are categories too. Themes tune
 * the look by tuning cN, not a quadrant-only token set. */
:is(section.quadrant, figure.chart-frame) {
  --quadrant-frame:   color-mix(in srgb, var(--text-muted) 42%, transparent);
  --quadrant-split:   color-mix(in srgb, var(--text-muted) 28%, transparent);
  --quadrant-target:  color-mix(in srgb, var(--text-muted) 78%, transparent);
  /* On-field labels sit on the vivid pie-matched zone fills, so they take
   * maximum-contrast ink rather than the softened --text-heading: true black
   * on the light canvas, true white on dark. light-dark() flips it off the
   * same color-scheme that drives every other token, so dark decks get white
   * labels automatically. */
  --quadrant-label-ink: light-dark(black, white);
}

/* Categorical routing — reading-order cN, mapped onto the shared chart
 * category model (fill = --catN-fill, ink/border = --catN-ink). That model
 * lives in _chart-family.css and guarantees fill + border share a hue and
 * flip with the canvas (pale fill / deep border on light, deep fill / pale
 * border on dark). The quadrant just assigns slots 1-4 in reading order. */
:is(section.quadrant, figure.chart-frame) [data-cell="0"] { --cell-fill: var(--chart-cat-1-fill); --cell-ink: var(--chart-cat-1-ink); }
:is(section.quadrant, figure.chart-frame) [data-cell="1"] { --cell-fill: var(--chart-cat-2-fill); --cell-ink: var(--chart-cat-2-ink); }
:is(section.quadrant, figure.chart-frame) [data-cell="2"] { --cell-fill: var(--chart-cat-3-fill); --cell-ink: var(--chart-cat-3-ink); }
:is(section.quadrant, figure.chart-frame) [data-cell="3"] { --cell-fill: var(--chart-cat-4-fill); --cell-ink: var(--chart-cat-4-ink); }

/* quadrant is a chart-family member — section layout, header/body/caption
 * skeleton and h2 styling all come from section.chart-frame. The figure
 * just slots into .chart-body as a centred flex row of svg (+ optional
 * legend, for the cohort variant). */
/* .chart-body inherits the shared width + padding (sp-lg / sp-2xl) so the
 * surface panel matches every other chart's size and inset — no
 * quadrant-specific override. */

/* .viz-frame merge: quadrant's title now hoists into the standard `.masthead-lede`
 * band (the masthead cell owns the header treatment for every chart), so the old
 * `.chart-header` background/hairline overrides here are retired — the element no
 * longer exists. */

:is(section.quadrant, figure.chart-frame) .quadrant-figure {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-xl);
  width: 100%;
  /* Fill the canvas so the SVG scales to the height the slide grants —
   * responsive: shrinks under a below-note/blockquote, grows under `full`. */
  height: 100%;
  min-height: 0;
}

/* The COHORT variant is excluded — it ships the SVG-native key (diagram + spine +
 * key in one viewBox) and is sized by the shared rule in chart-family.css, so the
 * old square-ish `aspect-ratio:420/348` + `50cqh` cap (which would letterbox the
 * now-wider unit) must not reach it. */
:is(section.quadrant, figure.chart-frame) .quadrant-svg:not(.quadrant-svg--cohort) {
  /* Section-relative fill, capped at 50cqh (50% slide height). Outside the
   * Form the common quadrant is NOT in a query-container figure, so `cqh`
   * here means the SLIDE; keep the resolution-stable cqh cap it shipped
   * with (#180). */
  height: 100%;
  max-height: 50cqh;
  width: auto;
  /* Mirrors the kernel's viewBox (quadrant.transform.js `vbHeight`). The lower
   * 28 units carry the bottom quadrant names; a chart with NO names emits the
   * shorter box and says so with `data-band="none"`. A stale ratio here does
   * not clip — `meet` letterboxes — but it shrinks the plot for nothing. */
  aspect-ratio: 420 / 348;
  flex: 0 1 auto;
  overflow: visible;
}
:is(section.quadrant, figure.chart-frame) .quadrant-svg[data-band="none"] {
  aspect-ratio: 420 / 320;   /* no quadrant names → no band to reserve */
}
/* IN-FORM (section.form) — the pie's proven fill-the-parent pattern
 * (piechart.styles.css §IN-FORM, 2026-06-15-form-chart-clip.md), which the
 * cohort variant already inherited via chart-family.css §IN-FORM. Under the
 * Form, `.chart-body` is a size-query container, which RE-BASES `cqh` from
 * the slide to the chart-body's content box — so the slide-based
 * `max-height:50cqh` above silently became "half the body" and shrank the
 * common quadrant to a thumbnail. Mirror the pie exactly:
 *   · `.chart-body` is already `container-type:size` (chart-family.css);
 *   · collapse the figure's box with `display:contents` so the SVG sizes
 *     straight off the chart-body (a flex figure can't mediate the height
 *     of a replaced <svg> in print);
 *   · `height:100cqh` on the SVG → fills the available body area, width
 *     follows the 420/320 viewBox aspect, `max-width:100%` guards narrow
 *     bodies. The chart-body's own centering flex column takes over the
 *     figure's centering job.
 * Non-form rendering keeps the slide-based rule above, byte-identical. */
section.form.quadrant:not(.claim-hero):not(.claim-bleed) .quadrant-figure {
  display: contents;
}
section.form.quadrant:not(.claim-hero):not(.claim-bleed) .quadrant-svg:not(.quadrant-svg--cohort) {
  /* Container-fill (2026-07-04-chart-container-fill-sizing.md): the .chart-body is a container-type:size box and the
     figure is display:contents, so the SVG fills BOTH axes of that definite box;
     preserveAspectRatio `meet` fits the 420/348 plot inside, shrink-to-fit.
     max-height:none + flex:0 0 auto clear the base rule's slide-relative 50cqh cap
     and flex-shrink, which would otherwise re-clamp the plot to half the stage. */
  width: 100%;
  height: 100%;
  max-height: none;
  flex: 0 0 auto;
}

/* ── Native 2×2 quadrant SVG chrome — appended Phase 4 ──
 * Originally lived in lib/_legacy.css under the CHART FAMILY section.
 * Includes per-cell tints, plot frame + split lines, axis labels,
 * scatter dots + per-dot labels, and 5 variants (bubble, trail,
 * cohort, threshold, plus the default scatter).
 */

/* ── Quadrant tints: per-cell fills behind the plot ───────────────────── */
/* PROTOTYPE (kanban-finish standardization): the region blocks were the
 * loudest fill in the family (the salmon-red Quick Wins quadrant read far
 * stronger than the same hue's airy radar wash). fill-opacity drops the four
 * tints ~40% into the family's quiet register so identity is carried by the
 * vivid white-ringed dots at the edge, not by shouting region blocks. */
:is(section.quadrant, figure.chart-frame) .quadrant-tint {
  fill: var(--cell-fill);
  fill-opacity: 0.6;
  stroke: none;
}

/* ── Plot frame + split lines ─────────────────────────────────────────── */
:is(section.quadrant, figure.chart-frame) .quadrant-bounds {
  fill: none;
  stroke: var(--quadrant-frame);
  stroke-width: 1.25;
}
:is(section.quadrant, figure.chart-frame) .quadrant-split {
  stroke: var(--quadrant-split);
  stroke-width: 1;
}
/* Threshold variant: target lines pop more than ordinary centerlines. */
:is(section.quadrant, figure.chart-frame) .quadrant-split[data-kind="target"] {
  stroke: var(--quadrant-target);
  stroke-width: 1.75;
  stroke-dasharray: 5 4;
}

/* ── Axis labels + corner ticks ───────────────────────────────────────── */
/* SVG font-size bypass: labels sit inside a ~420×348-unit SVG viewBox, so
 * CSS px ≠ pt. Values are intentional deviations from the 12-token scale;
 * scoped to :is(section.quadrant, figure.chart-frame) so themes can override per-component via the token. */
:is(section.quadrant, figure.chart-frame) {
  --quadrant-axis-size: 12px;  /* raised from 11px — axis name, still below token min */
  --quadrant-tick-size: 10px;  /* raised from 8px (≈5.7pt at desk) */
}
:is(section.quadrant, figure.chart-frame) .quadrant-axis-name {
  fill: var(--text-heading);
  font-family: var(--font-body);
  font-size: var(--quadrant-axis-size);
  font-weight: 600;
  letter-spacing: 0.02em;
}
:is(section.quadrant, figure.chart-frame) .quadrant-tick {
  fill: var(--text-muted);
  font-family: var(--font-mono, var(--font-body));
  font-size: var(--quadrant-tick-size);
  font-weight: 500;
}

/* ── Quadrant corner labels ───────────────────────────────────────────── */
/* Category colour rides the region tint + dots (cN); the label TEXT is
 * maximum-contrast ink (--quadrant-label-ink: black on light / white on
 * dark) — no --bg halo. cN-dark ink can't clear AA as text on its own tint,
 * so text never uses cell-ink; and softened --text-heading reads a touch
 * light on the vivid zones, so the labels take true black/white instead. */
:is(section.quadrant, figure.chart-frame) .quadrant-label {
  /* The name takes ITS QUADRANT'S ink, which binds it to the block it describes
   * — the whole job of a region label. `--cell-ink` is routed from the
   * `data-cell` the label carries.
   *
   * But it is DARKENED toward the page's own heading ink first, because
   * `--chart-cat-N-ink` is a GRAPHICAL ink: it was designed and gated at the
   * 3:1 WCAG 1.4.11 floor for dots, strokes and borders. This is the first
   * place it carries text, which needs 4.5:1 — and taking it raw put 12 of 216
   * theme × mode × cell combinations below AA (`concrete` light bottom-right
   * measured 3.04:1, down from 10.56:1 when the name was maximum-contrast
   * black/white inside the tint).
   *
   * 65% is measured, not guessed: it is the largest hue share that clears AA in
   * EVERY theme (worst case `concrete` light at 4.99:1). More hue is prettier
   * and illegible somewhere. `check-viz-render.js` now gates this, so the floor
   * cannot silently move again. */
  fill: color-mix(in oklab, var(--cell-ink, var(--quadrant-label-ink)) 65%, var(--text-heading));
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
/* Magic variant: heavier, more ceremonial labels with extra tracking. */
:is(section.quadrant, figure.chart-frame) .quadrant-label--magic {
  font-size: 12px;
  letter-spacing: 0.08em;
}
/* Threshold variant: zone names live ON the chart as action prompts. */
:is(section.quadrant, figure.chart-frame) .quadrant-label--zone {
  font-size: 10.5px;
  letter-spacing: 0.06em;
}

/* ── Scatter dots + per-dot labels ────────────────────────────────────── */
:is(section.quadrant, figure.chart-frame) .quadrant-dot {
  fill: var(--cell-ink);
  stroke: var(--bg);
  stroke-width: 2;
}
:is(section.quadrant, figure.chart-frame) .quadrant-dot-label {
  fill: var(--quadrant-label-ink);
  font-family: var(--font-body);
  font-size: 8.5px;
  font-weight: 500;
}

/* ── Bubble variant: √-area bubble + smart label position ─────────────── */
:is(section.quadrant, figure.chart-frame) .quadrant-bubble {
  fill: var(--cell-fill);
  stroke: var(--cell-ink);
  stroke-width: 1.5;
}
/* Value text is neutral heading ink — high-contrast both inside the pale
 * cN-light bubble fill and above it on the canvas (cN-dark would not clear
 * AA on its own same-hue tint). */
:is(section.quadrant, figure.chart-frame) .quadrant-bubble-value {
  fill: var(--text-heading);
  font-family: var(--font-body);
  font-size: 8.5px;
  font-weight: 700;
}
:is(section.quadrant, figure.chart-frame) .quadrant-bubble-label {
  fill: var(--quadrant-label-ink);
  font-family: var(--font-body);
  font-size: 8.5px;
  font-weight: 500;
}

/* ── Trail variant: faded before + dashed connector + solid after ─────── */
:is(section.quadrant, figure.chart-frame) .quadrant-trail-line {
  stroke: var(--cell-ink);
  stroke-width: 1.5;
  stroke-dasharray: 3 3;
  stroke-linecap: round;
  opacity: 0.7;
}
:is(section.quadrant, figure.chart-frame) .quadrant-trail-before {
  fill: none;
  stroke: var(--cell-ink);
  stroke-width: 1.5;
  opacity: 0.6;
}
:is(section.quadrant, figure.chart-frame) .quadrant-trail-after {
  fill: var(--cell-ink);
  stroke: var(--bg);
  stroke-width: 1.5;
}

/* ── Cohort variant: convex hulls + centroid labels + legend ──────────── */
:is(section.quadrant, figure.chart-frame) .quadrant-hull {
  fill: var(--cell-fill);
  stroke: var(--cell-ink);
  stroke-width: 1.25;
  stroke-linejoin: round;
  opacity: 0.65;
}
:is(section.quadrant, figure.chart-frame) .quadrant-hull-line {
  stroke: var(--cell-ink);
  stroke-width: 1.5;
  stroke-linecap: round;
  opacity: 0.65;
}
:is(section.quadrant, figure.chart-frame) .quadrant-cohort-label {
  fill: var(--quadrant-label-ink);
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
/* The cohort key is now SVG-native (svg-legend.js → `.chart-key-*`, styled in
 * _chart-family/chart-family.css); the old HTML `.quadrant-legend` rules are
 * retired with it. See 2026-06-13-svg-native-legend.md. */

/* ── Threshold variant: target badges at the axis crossings ───────────── */
:is(section.quadrant, figure.chart-frame) .quadrant-target-badge {
  fill: var(--quadrant-target);
  font-family: var(--font-mono, var(--font-body));
  font-size: 9px;
  font-weight: 700;
}

/* ── minimal: no fills, fainter grid (composable) ─────────────────────── */
section.quadrant.minimal .quadrant-tint {
  fill: none;
}
section.quadrant.minimal {
  --quadrant-frame: color-mix(in srgb, var(--text-muted) 28%, transparent);
  --quadrant-split: color-mix(in srgb, var(--text-muted) 18%, transparent);
}
section.quadrant.minimal .quadrant-bubble {
  fill: none;
}
section.quadrant.minimal .quadrant-hull {
  fill: none;
}

/* ── dark: lift frame + split for dark surfaces (composable) ──────────── */
section.quadrant.dark {
  --quadrant-frame:  color-mix(in srgb, var(--text-muted) 58%, transparent);
  --quadrant-split:  color-mix(in srgb, var(--text-muted) 42%, transparent);
  --quadrant-target: color-mix(in srgb, var(--text-muted) 88%, transparent);
}

