/* === lib/components/chart/radar/radar.styles.css === */
/* radar — extracted from lib/_legacy.css (batch 8).
 * See lib/components/radar/radar.manifest.json for the component contract.
 */

/* ── RADAR ───────────────────────────────────────────────────────────────────
 * Native radar / spider chart — build-time SVG, no charting library.
 *
 * Source contract: one series-major nested <ul> per slide. Each top-level
 * <li> is a series; nested <li>s are `axis <code>value</code>`. The eyebrow
 * <code> may pin the value scale (`0–100`); otherwise it auto-fits the data.
 * lib/radar.js parses the list, resolves the scale, and emits a positioned
 * SVG — deterministic, palette-blind, zero client-side JS.
 *
 * Layout output:
 *   <div class="radar-figure" data-variant="default" data-axes="N" data-series="M">
 *     <svg class="radar-svg" viewBox="0 0 300 300">
 *       <g class="radar-grid">…rings + spokes…</g>
 *       <g class="radar-axes">…axis labels…</g>
 *       <g class="radar-ticks">…ring values…</g>
 *       <g class="radar-plot">…series polygons + vertex dots…</g>
 *     </svg>
 *     <ol class="radar-legend">…</ol>
 *   </div>
 *
 * One default + five modifier variants. Per-variant DOM differs (target adds
 * gap segments, benchmark adds an envelope band, quadrant adds sectors,
 * small-multiples emits one mini per series) — see lib/radar.js. `minimal`
 * (stroke-only) and `dark` are composable cross-cutting modifiers handled
 * here in CSS.
 *
 * Series colour rides --series-color, set per polygon/dot from the
 * categorical palette in lib/radar.js. Layouts stay palette-blind.
 *
 * Sibling implementations:
 *   - lib/radar.js          transform module (canonical)
 *   - lattice-emulator.js   per-slide HTML-string transform
 *   - lib/engine           the engine render path
 *   - lattice-runtime.js    DOM transform for marp-vscode preview
 */

:is(section.radar, figure.chart-frame) {
  --radar-grid:       color-mix(in srgb, var(--text-muted) 42%, transparent);
  --radar-grid-soft:  color-mix(in srgb, var(--text-muted) 20%, transparent);
  --radar-spoke:      color-mix(in srgb, var(--text-muted) 34%, transparent);
  --radar-fill:       18%;   /* series-colour share in the polygon fill */
}

/* radar is a chart-family member — section layout, header/body/caption
 * skeleton and h2 styling all come from section.chart-frame. The figure
 * just slots into .chart-body as a centred flex row of svg + legend. */
/* .chart-body inherits the shared width + padding (sp-lg / sp-2xl) so the
 * surface panel matches every other chart's size and inset — no radar-specific
 * override. */

:is(section.radar, figure.chart-frame) .radar-figure {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-xl);
  /* Fill the canvas (.chart-body) so the SVG can scale to the height the
   * slide actually grants — responsive: shrinks when a below-note/blockquote
   * eats vertical space, grows under the `full` modifier. */
  height: 100%;
  width: 100%;
  min-height: 0;
}

:is(section.radar, figure.chart-frame) .radar-svg {
  /* Sizing (height-bound on the unified viewBox aspect — diagram + key as one
   * unit) is the shared SVG-native rule in _chart-family/chart-family.css. The
   * old square `aspect-ratio:1/1` is retired: the viewBox is no longer square
   * (it now includes the key rail), so forcing a square letterboxed the whole
   * unit small. Only the rim-label overflow stays radar's own — axis labels
   * paint just outside the plot box. */
  overflow: visible;
}

/* Mermaid radar-beta styling (`.radarCurve-N`, `.radarGraticule`, …) used to
 * live here, but it targets MERMAID's radar output, not this native component
 * (which uses `.radar-poly` / `.radar-ring` below). It now lives with the other
 * Mermaid type overrides in lib/integrations/mermaid/mermaid.css, re-pointed
 * onto the engine `--cN` palette (N curves, not two brand accents). */

/* ── Native radar SVG chrome — appended Phase 4 ──
 * Originally lived in lib/_legacy.css under the CHART FAMILY section.
 * Includes the ring + spoke grid, axis tick labels, series polygons,
 * legend, gap/delta variants for compare/over-under, and small-multiples.
 */

/* ── Grid: concentric ring polygons + radial spokes ───────────────────── */
:is(section.radar, figure.chart-frame) .radar-ring {
  fill: none;
  stroke: var(--radar-grid-soft);
  stroke-width: 1;
}
:is(section.radar, figure.chart-frame) .radar-ring[data-ring="4"] {
  stroke: var(--radar-grid);   /* outer ring carries the chart edge */
}
:is(section.radar, figure.chart-frame) .radar-spoke {
  stroke: var(--radar-spoke);
  stroke-width: 1;
}

/* ── Axis + tick labels ───────────────────────────────────────────────── */
/* SVG font-size bypass: axis/tick labels sit inside a ~300-unit SVG viewBox,
 * so CSS px ≠ pt. 15px ≈ 11.25pt would be too large for rim labels on a
 * 300-unit viewBox. These are intentional deviations from the 12-token scale.
 * Scoped to :is(section.radar, figure.chart-frame) so themes can override per-component via the token. */
:is(section.radar, figure.chart-frame) {
  --radar-axis-label-size: 11px;  /* raised from 9px (≈6.4pt at desk) */
  --radar-tick-size:        9px;  /* raised from 6.5px (≈4.6pt at desk) */
}
:is(section.radar, figure.chart-frame) .radar-axis-label {
  fill: var(--text-heading);
  font-family: var(--font-body);
  font-size: var(--radar-axis-label-size);
  font-weight: 600;
}
:is(section.radar, figure.chart-frame) .radar-tick {
  fill: var(--text-muted);
  font-family: var(--font-mono, var(--font-body));
  font-size: var(--radar-tick-size);
  /* font-weight raised to 600 (matching the cover-variant lift) so faint
   * sub-token-size ticks have enough stroke weight to be legible. */
  font-weight: 600;
}

/* ── Series polygons + vertex dots ────────────────────────────────────── */
:is(section.radar, figure.chart-frame) .radar-poly {
  fill: color-mix(in srgb, var(--series-color) var(--radar-fill), transparent);
  stroke: var(--series-color);
  stroke-width: 2;
  stroke-linejoin: round;
}
:is(section.radar, figure.chart-frame) .radar-dot {
  fill: var(--series-color);
  stroke: var(--bg);
  stroke-width: 1;
}

/* ── Legend ───────────────────────────────────────────────────────────────
 * The key is now SVG-native (svg-legend.js → `.chart-key-*`, styled in
 * _chart-family/chart-family.css). A muted reference series (target / before /
 * comparison band) is keyed with a quiet swatch from the kernel rather than the
 * old dashed-chip CSS. The HTML `.radar-legend` rules are retired with it. See
 * 2026-06-13-svg-native-legend.md. */

/* ── target: actual vs a reference polygon, per-axis gap segments ─────── */
:is(section.radar, figure.chart-frame) .radar-poly--target {
  fill: none;
  stroke: var(--text-muted);
  stroke-width: 1.5;
  stroke-dasharray: 4 3;
}
:is(section.radar, figure.chart-frame) .radar-gap {
  stroke-width: 3;
  stroke-linecap: round;
}
/* Semantic state tokens — --pass / --fail come from lattice.css :root,
 * tuned per theme. Was --cat-green / --cat-rose before the 2026-05-15
 * themes refactor (commit 552e84a) removed the named-cat tokens. */
:is(section.radar, figure.chart-frame) .radar-gap[data-dir="under"] {
  stroke: var(--state-fail-ink);
}
:is(section.radar, figure.chart-frame) .radar-gap[data-dir="over"] {
  stroke: color-mix(in srgb, var(--state-pass-ink) 60%, transparent);
  stroke-width: 2;
}

/* ── delta: before → after, per-axis change segments ──────────────────── */
:is(section.radar, figure.chart-frame) .radar-poly--before {
  fill: none;
  stroke: var(--text-muted);
  stroke-width: 1.5;
  stroke-dasharray: 4 3;
}
:is(section.radar, figure.chart-frame) .radar-delta-seg {
  stroke-width: 3;
  stroke-linecap: round;
}
:is(section.radar, figure.chart-frame) .radar-delta-seg[data-dir="up"]   { stroke: var(--state-pass-ink); }
:is(section.radar, figure.chart-frame) .radar-delta-seg[data-dir="down"] { stroke: var(--state-fail-ink); }
:is(section.radar, figure.chart-frame) .radar-delta-seg[data-dir="flat"] { stroke: var(--radar-spoke); }

/* ── benchmark: hero series over a min–max envelope band ──────────────── */
:is(section.radar, figure.chart-frame) .radar-band {
  fill: color-mix(in srgb, var(--text-muted) 22%, transparent);
  stroke: color-mix(in srgb, var(--text-muted) 48%, transparent);
  stroke-width: 1;
}
:is(section.radar, figure.chart-frame) .radar-poly--hero {
  stroke-width: 2.75;
}

/* ── quadrant: axes grouped into tinted sectors ───────────────────────── */
:is(section.radar, figure.chart-frame) .radar-sector {
  fill: color-mix(in srgb, var(--series-color) 8%, transparent);
  stroke: none;
}
:is(section.radar, figure.chart-frame) .radar-sector-mean {
  fill: none;
  stroke: var(--series-color);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-dasharray: 2 3;
  opacity: 0.8;
}
:is(section.radar, figure.chart-frame) .radar-sector-label {
  fill: var(--series-color);
  font-family: var(--font-body);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* ── small-multiples: one mini radar per series ───────────────────────── */
:is(section.radar, figure.chart-frame) .radar-figure[data-variant="small-multiples"] {
  gap: 0;
}
:is(section.radar, figure.chart-frame) .radar-multiples {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: center;
  gap: var(--sp-md) var(--sp-lg);
  flex: 1 1 auto;
}
:is(section.radar, figure.chart-frame) .radar-mini {
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--sp-3xs);
}
/* Small-multiple minis size in cqi, not px (#1184). A fixed 188px pinned each
 * mini to a PHYSICAL size: it held ~19.6% of the chart body at HD but collapsed
 * to ~4.9% at 4K while the cqi-sized type around it grew ~3×, so the minis
 * shrank away from their own captions.
 *
 * The token is calibrated by MEASUREMENT against the surface whose BYTES ship —
 * the emulator document Chrome prints the PDF from, AT THE VIEWPORT IT PRINTS
 * AT (1280x720; `lattice-emulator.js` setViewport before `page.pdf`). There
 * `cqi` resolves against the nearest size container's CONTENT box, `.chart-body`
 * at 921.8px, so 1cqi = 9.218px and the old 188px is 20.399cqi.
 *
 * The viewport is not a detail: loading the same document at puppeteer's default
 * 800x600 gives a 960px body and answers 19.583cqi, which renders 180.5px — a 4%
 * shrink dressed up as a units cleanup. Measure the surface, at the size the
 * surface actually runs.
 *
 * A differently-padded HOST resolves the same token against ITS chart body and
 * gets a proportionally different pixel size. That is the point of the change,
 * not a defect: the mini is meant to be a fraction of its container. Only the
 * PDF path can be pinned to a number, so that is the one calibrated. */
:is(section.radar, figure.chart-frame) {
  --radar-mini-size: 20.399cqi;
}
/* The mini's viewBox is widened by MINI_LABEL_PAD each side (radar.transform.js)
 * so a six-letter rim label can't break mid-word. Height still pins the 300-unit
 * diagram, so the DIAGRAM's rendered size is unchanged; the extra width is
 * label bleed. The ratio mirrors the kernel's viewBox — 340/300. */
:is(section.radar, figure.chart-frame) .radar-svg--mini {
  width: calc(var(--radar-mini-size) * 340 / 300);
  height: var(--radar-mini-size);
}
:is(section.radar, figure.chart-frame) .radar-svg--mini .radar-axis-label {
  font-size: 11px;   /* the mini keeps the 300-unit plot, so label units too */
}
:is(section.radar, figure.chart-frame) .radar-mini-label {
  font-size: var(--fs-meta);
  font-weight: 600;
  color: var(--series-color);
}

/* ── minimal: stroke-only polygons, fainter grid (composable) ─────────── */
section.radar.minimal .radar-poly {
  fill: none;
}
section.radar.minimal .radar-poly--hero {
  fill: none;
}
section.radar.minimal {
  --radar-grid:      color-mix(in srgb, var(--text-muted) 26%, transparent);
  --radar-grid-soft: color-mix(in srgb, var(--text-muted) 13%, transparent);
}
section.radar.minimal .radar-band {
  fill: none;
}

/* ── dark: lift grid for the dark surface (composable) ───────────────────
 * --text-heading / --text-body / --bg follow light-dark(), so axis labels,
 * legend ink and the dot halo flip on their own — only the grid tokens
 * (built on the fixed --text-muted) need a nudge for dark-surface contrast. */
section.radar.dark {
  --radar-grid:       color-mix(in srgb, var(--text-muted) 62%, transparent);
  --radar-grid-soft:  color-mix(in srgb, var(--text-muted) 32%, transparent);
  --radar-spoke:      color-mix(in srgb, var(--text-muted) 52%, transparent);
  --radar-fill:       24%;
}

/* ── RADAR · COVER ──────────────────────────────────────────────────────
 * `cover` is the global full-bleed-with-caption modifier (base.variants.css),
 * and the chart family generalizes it (chart-family.css `section.chart-frame
 * :is(.claim-hero, .claim-bleed)`): the bleed, hidden chrome, exposed title, filled chart-body, and the
 * sheen caption band all come from there. This block adds only radar's own
 * extras — centring and scaling up the single SVG unit (diagram + key), and the
 * lifted scale ticks. Pure CSS. */

/* The cover unit is now ONE svg (diagram + spine + key in one viewBox), so cover
 * just CENTRES + scales it: equal 1fr gutters flank the auto-width svg so the
 * whole unit centres on the slide (the key scales up with the diagram — the
 * "cover just works" property of the SVG-native key). */
section.radar:is(.claim-hero, .claim-bleed) .radar-figure {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  width: 100%;
  max-width: 100%;
  height: auto;
}
/* Explicit cqi size scales the unit up (the base flex-height / cap both fail at
 * full-bleed); max-height guards against a tall two-line caption. */
section.radar:is(.claim-hero, .claim-bleed) .radar-svg {
  grid-column: 2;
  justify-self: center;
  height: 36cqi;
  width: auto;
  max-height: 100%;
  max-width: 100%;
}

/* Scale ticks read too faint at full-bleed size — lift them off --text-muted
 * to a stronger heading mix and add weight so the 0–10 scale stays legible. */
section.radar:is(.claim-hero, .claim-bleed) .radar-tick {
  fill: color-mix(in srgb, var(--text-heading) 80%, transparent);
  font-weight: 600;
}

/* === lib/components/comparison/redline/redline.styles.css === */
/* redline — comparison.canvas.prose
 *
 * Extracted from lib/_legacy.css in Phase 4 of the destination map.
 * See lib/components/redline/redline.manifest.json for the component contract.
 *
 * STAGE CELL (flex cell-tree §6, 2026-06-26). redline is in STAGE_MIGRATED, so the
 * masthead lift wraps its body (the blockquotes + annotation/rationale list — the
 * eyebrow + h2 lift into the `.cell-masthead` band) into the frame's bounded
 * `.cell-stage` cell. Every body rule below addresses `> .cell-stage > …`; the
 * `.split` / `.three-col` read-across grids live ON the stage cell, so an
 * over-stuffed diff clips at — and is REPORTED at — the stage edge (the overflow
 * probe's `.cell-stage` selector), not silently inside a column.
 *
 * KEY-INSIGHT GATE. The central blockquote eyebrow rule in
 * lib/base/base.modifiers.css excludes redline (`:not(.redline)`), so a
 * redline never inherits the "KEY INSIGHT" label — bare/annotated redlines
 * render a clean diff, and the `.split` / `.stacked` / `.three-col` variants'
 * own OLD / NEW blockquote::before labels apply unopposed (no source-order
 * race). The doubled-class selectors below (`.split.split`, …) are a legacy
 * specificity bump from the _legacy.css split; with the gate in place they
 * are no longer load-bearing, but are retained as harmless.
 */

/* ── REDLINE ──────────────────────────────────────────────────────────
 * Textual diff. Uses <ins> / <del> HTML (or ~~md~~ for deletions).
 *
 * <!-- _class: redline -->
 * `Cal. Civ. Code §1798.130 · amendment SB-362`
 * > A business shall <del>provide</del> <ins>publish on its homepage</ins>
 * > a clear and conspicuous link <ins>titled "Your Privacy Choices"</ins>
 * > that enables a consumer to opt out…
 *
 * Variants: .split (old | new), .annotated (numbered margin notes),
 * .stacked (old block atop new block), .three-col (old | new | rationale).
 * ──────────────────────────────────────────────────────────────────── */
section.redline > .cell-stage { display:flex; flex-direction:column; gap:var(--sp-sm); }
/* A body code-only paragraph (the first lifts into the masthead as the kicker; this
 * only matches a SECOND one left in the stage). */
section.redline > .cell-stage > p:has(> code:only-child) {
  margin:0;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  letter-spacing:0.04em;
  color:var(--accent);
}
section.redline > .cell-stage > p:has(> code:only-child) > code {
  background:none; border:none; padding:0; color:inherit;
}
section.redline > .cell-stage > blockquote {
  padding:var(--sp-md) var(--sp-lg);
  background:var(--bg-alt);
  border:1px solid var(--border);
  border-left:4px solid var(--text-muted);
  border-radius:0 var(--radius-md) var(--radius-md) 0;
  font-family:var(--font-display);
  font-size:var(--fs-body);
  line-height:var(--lh-relaxed);
  color:var(--text-heading);
  flex:1;
}
section.redline > .cell-stage > blockquote > p { margin:0; }
section.redline > .cell-stage > blockquote > p + p { padding-top:var(--sp-sm); }
/* Insertions and deletions — ins/del HTML, also ~~md~~ which renders as s. */
section.redline ins, section.redline :is(p) ins {
  text-decoration:underline;
  text-decoration-thickness:2px;
  text-decoration-color:var(--pass);
  color:var(--pass);
  background:var(--pass-bg);
  padding:0 0.234375cqi;
  border-radius:var(--radius-sm);
  font-style:normal;
  font-weight:600;
}
section.redline del, section.redline s {
  text-decoration:line-through;
  text-decoration-thickness:2px;
  text-decoration-color:var(--fail);
  color:var(--fail);
  background:var(--fail-bg);
  padding:0 0.234375cqi;
  border-radius:var(--radius-sm);
  opacity:0.85;
}
/* Annotation list — appears below the quote, gives reviewer plain-English
 * rationale for each numbered delta in the text. */
section.redline > .cell-stage > ol,
section.redline > .cell-stage > ul {
  list-style:none; padding:0;
  display:flex; flex-direction:column; gap:var(--sp-xs);
}
section.redline > .cell-stage > :is(ol, ul) > li {
  font-size:var(--fs-body);
  color:var(--text-body);
  line-height:var(--lh-snug);
  padding-left:var(--sp-md);
  border-left:2px solid var(--accent);
}
section.redline > .cell-stage > :is(ol, ul) > li::marker { content:''; }
section.redline > .cell-stage > :is(ol, ul) > li > strong {
  display:inline-block;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.10em;
  color:var(--accent);
  padding-right:var(--sp-xs);
}

/* .split — two blockquotes side-by-side: old left, new right. The masthead band is
 * a flex sibling ABOVE the stage now, so the grid is just the two cards (row 1) +
 * the read-across note list (row 2, full width). */
section.redline.split > .cell-stage { display:grid; grid-template-columns:1fr 1fr; column-gap:var(--sp-md); grid-template-rows:minmax(0, 1fr) auto; row-gap:var(--sp-sm); }
section.redline.split.split > .cell-stage > blockquote { min-width:0; min-height:0; overflow:hidden; }
section.redline.split.split > .cell-stage > blockquote:nth-of-type(1) {
  grid-column:1; grid-row:1;
  border-left-color:var(--fail);
  background:color-mix(in srgb, var(--fail) 4%, var(--bg-alt));
}
section.redline.split.split > .cell-stage > blockquote:nth-of-type(1)::before {
  content:'OLD';
  display:block;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.12em;
  color:var(--fail);
  padding-bottom:var(--sp-xs);
}
section.redline.split.split > .cell-stage > blockquote:nth-of-type(2) {
  grid-column:2; grid-row:1;
  border-left-color:var(--pass);
  background:color-mix(in srgb, var(--pass) 4%, var(--bg-alt));
}
section.redline.split.split > .cell-stage > blockquote:nth-of-type(2)::before {
  content:'NEW';
  display:block;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.12em;
  color:var(--pass);
  padding-bottom:var(--sp-xs);
}
section.redline.split > .cell-stage > :is(ol, ul) { grid-column:1 / -1; grid-row:2; }

/* .annotated — single passage with numbered sup markers; annotations below. */
/* sanctioned: a superscript footnote marker — stays raised + small (0.7em,
 * vertical-align:super) rather than a centred inline-flex pill. Geometry that
 * doesn't fight the superscript routes through the --pill-* tokens. */
section.redline.annotated > .cell-stage > blockquote sup {
  display:inline-block;
  background:var(--accent);
  color:var(--on-accent);
  font-family:var(--pill-font);
  font-size:0.7em;
  font-weight:700;
  padding:0 0.4em;
  border-radius:var(--pill-radius);
  line-height:1.4;
  vertical-align:super;
}
section.redline.annotated > .cell-stage > :is(ol, ul) {
  counter-reset:rl;
  padding-top:var(--sp-md);
}
section.redline.annotated > .cell-stage > :is(ol, ul) > li {
  counter-increment:rl;
  position:relative;
  padding-left:calc(var(--sp-lg) + var(--sp-xs));
}
/* sanctioned: positioned annotation counter, anchored to the list-row origin
 * (absolute). Footnote weight (700) is kept; radius + font route to tokens. */
section.redline.annotated > .cell-stage > :is(ol, ul) > li::before {
  content:counter(rl);
  position:absolute; left:0; top:0.156cqi;
  display:inline-flex; align-items:center; justify-content:center;
  background:var(--accent); color:var(--on-accent);
  font-family:var(--pill-font);
  font-size:var(--pill-fs);
  font-weight:700;
  letter-spacing:var(--pill-tracking);
  padding:0 0.5em;
  border-radius:var(--pill-radius);
  line-height:1.4;
}

/* .stacked — two blockquotes vertically: old on top (struck), new below. */
section.redline.stacked.stacked > .cell-stage > blockquote:nth-of-type(1) {
  background:color-mix(in srgb, var(--fail) 5%, var(--bg-alt));
  border-left-color:var(--fail);
  text-decoration:line-through;
  text-decoration-color:color-mix(in srgb, var(--fail) 40%, transparent);
  opacity:0.78;
}
section.redline.stacked.stacked > .cell-stage > blockquote:nth-of-type(1)::before {
  content:'OLD — prior text';
  display:block;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.12em;
  color:var(--fail);
  text-decoration:none;
  padding-bottom:var(--sp-xs);
}
section.redline.stacked.stacked > .cell-stage > blockquote:nth-of-type(2) {
  background:color-mix(in srgb, var(--pass) 5%, var(--bg-alt));
  border-left-color:var(--pass);
}
section.redline.stacked.stacked > .cell-stage > blockquote:nth-of-type(2)::before {
  content:'NEW · current';
  display:block;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.12em;
  color:var(--pass);
  padding-bottom:var(--sp-xs);
}

/* .three-col — old | new | rationale columns. The author writes two
 * blockquotes plus a list for the rationale column. With the masthead lifted to
 * its own band, the stage grid is a single content row of three columns. */
/* minmax(0,1fr) (not bare 1fr) caps the content row at its flex share so a
 * long clause can't push the grid past the slide edge and clip mid-word;
 * the blockquote guard below keeps overflow inside its own track. */
/* OLD/NEW carry full clauses and need the width; WHY is a short pill stack that under-fills
 * its track — so the diff columns are wider than the rationale (was 1/1/1.1, which starved
 * OLD/NEW into extra wrapped lines and clipped the denser NEW card). (#569) */
section.redline.three-col > .cell-stage { display:grid; grid-template-columns:1.15fr 1.15fr 0.85fr; column-gap:var(--sp-md); grid-template-rows:minmax(0, 1fr); row-gap:var(--sp-sm); }
section.redline.three-col.three-col > .cell-stage > blockquote { min-width:0; min-height:0; overflow:hidden; }
/* The three columns are narrow, so the cards read snug — not the default single-column
 * `--lh-relaxed` — and carry tighter block padding. Both cards share one grid-row height
 * (minmax(0,1fr)); the denser side (NEW) needs the reclaimed lines to seat without clipping
 * its last line. (#569) */
section.redline.three-col.three-col > .cell-stage > blockquote { line-height:var(--lh-snug); padding-block:var(--sp-sm); }
section.redline.three-col.three-col > .cell-stage > blockquote:nth-of-type(1) {
  grid-column:1; grid-row:1;
  border-left-color:var(--fail);
  background:color-mix(in srgb, var(--fail) 4%, var(--bg-alt));
  font-size:var(--fs-body);
}
section.redline.three-col.three-col > .cell-stage > blockquote:nth-of-type(1)::before {
  content:'OLD'; display:block;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.12em;
  color:var(--fail);
  padding-bottom:var(--sp-xs);
}
section.redline.three-col.three-col > .cell-stage > blockquote:nth-of-type(2) {
  grid-column:2; grid-row:1;
  border-left-color:var(--pass);
  background:color-mix(in srgb, var(--pass) 4%, var(--bg-alt));
  font-size:var(--fs-body);
}
section.redline.three-col.three-col > .cell-stage > blockquote:nth-of-type(2)::before {
  content:'NEW'; display:block;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.12em;
  color:var(--pass);
  padding-bottom:var(--sp-xs);
}
section.redline.three-col > .cell-stage > :is(ol, ul) {
  grid-column:3; grid-row:1;
  align-self:stretch;
}
section.redline.three-col > .cell-stage > :is(ol, ul)::before {
  content:'WHY';
  display:block;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.12em;
  color:var(--accent);
  padding-bottom:var(--sp-xs);
}


/* ════════════════════════════════════════════════════════════════════════
 * MODIFIERS — cross-cutting authorial intent flags
 * ────────────────────────────────────────────────────────────────────────
 * Modifiers compose with any layout. They redefine palette/spacing
 * variables on the section element; layouts that read those variables
 * via var() pick up the new values automatically. This keeps modifiers
 * additive — no per-layout cascade edits required.
 *
 * Composition rules:
 *   - Modifiers never collide with layouts; any modifier may pair with
 *     any layout where the appendix matrix in references/proposals.md
 *     marks it ● or ○.
 *   - When two density modifiers are stacked (e.g. compact loose), the
 *     last one in the source order wins, per normal cascade.
 *   - Layout-specific modifiers (declared further below) compose with
 *     cross-cutting modifiers.
 *
 * Reference: references/proposals.md §2 (modifier catalogue), §4.5 (rollout).
 * ════════════════════════════════════════════════════════════════════════ */

/* ── PORTRAIT REFLOW — the COLLAPSE move (Fit Ladder) ──────────────────────
 * The wide read-across variants (.split = old|new, .three-col = old|new|why) can't hold
 * their columns legibly in a narrow box, so in a PORTRAIT box they COLLAPSE the STAGE grid
 * to a single stacked column — OLD block, NEW block, (WHY list) in reading order. The
 * per-block OLD/NEW labels + pass/fail tints carry over unchanged (they key off :nth-of-type,
 * not the grid; grid-column/grid-row go inert under flex). Keyed on the static
 * `data-orientation` stamp, NOT @container: the section IS the `lattice` query-container, so it
 * can't restyle its OWN display via a container query (only descendants can) — a layout flipping
 * its own box uses the [data-orientation] section-flip (spine §2.1, as split-panel / citation-card
 * do). This is the static stamp, so it holds in the Persona-2 portrait EXPORT (no JS). Doubled
 * classes + the attribute beat the grid rules' specificity. This is the portrait form that lets
 * redline retire its landscape lock — the default/.annotated/.stacked variants were already
 * vertical. See engineering/decisions/2026-06-25-retire-landscape-locks-portrait-everything.md. */
section.redline.split.split[data-orientation="portrait"] > .cell-stage,
section.redline.three-col.three-col[data-orientation="portrait"] > .cell-stage {
  display:flex; flex-direction:column; gap:var(--sp-sm);
}
/* size each block to its content (the grid set flex/overflow guards for the columns);
   a too-long stacked diff then overflows the slide honestly rather than clipping a block. */
section.redline.split.split[data-orientation="portrait"] > .cell-stage > blockquote,
section.redline.three-col.three-col[data-orientation="portrait"] > .cell-stage > blockquote {
  flex:0 0 auto; overflow:visible;
}
section.redline.three-col.three-col[data-orientation="portrait"] > .cell-stage > :is(ol, ul) { align-self:stretch; }

/* ── block-split slides (carousel.js redline-blocks) ──
 * When the collapsed stack is still too tall, the splitter gives OLD and NEW their own slides.
 * One block per slide means :nth-of-type can't carry the OLD/NEW identity, so it rides an
 * explicit rl-old / rl-new class — these mirror the .stacked variant's tint + label. The
 * slide drops .split/.three-col, so there is no nth-of-type rule to fight (no doubled class
 * needed). Palette-blind (HARD #3). */
section.redline > .cell-stage > blockquote.rl-old {
  border-left-color:var(--fail);
  background:color-mix(in srgb, var(--fail) 5%, var(--bg-alt));
}
section.redline > .cell-stage > blockquote.rl-old::before {
  content:'OLD — prior text'; display:block;
  font-family:var(--font-mono); font-size:var(--fs-meta); font-weight:700;
  letter-spacing:0.12em; color:var(--fail); padding-bottom:var(--sp-xs);
}
section.redline > .cell-stage > blockquote.rl-new {
  border-left-color:var(--pass);
  background:color-mix(in srgb, var(--pass) 5%, var(--bg-alt));
}
section.redline > .cell-stage > blockquote.rl-new::before {
  content:'NEW · current'; display:block;
  font-family:var(--font-mono); font-size:var(--fs-meta); font-weight:700;
  letter-spacing:0.12em; color:var(--pass); padding-bottom:var(--sp-xs);
}

/* ── Struck elevation (base.tokens.css --elevation-card) ── lift the cards; vertical
 * berth (padding-block, never margin — #20) so the stage's overflow:clip doesn't
 * shear the shadow. Shadow has no horizontal extent, so no horizontal berth. */
section.redline > .cell-stage > blockquote {
  box-shadow: var(--elevation-card);
}
section.redline > .cell-stage {
  padding-block: var(--elevation-berth);
}

/* === lib/components/legal/regulatory-update/regulatory-update.styles.css === */
/* regulatory-update — progression.ledger.structure
 *
 * Extracted from lib/_legacy.css in Phase 4 (completed via Phase 7
 * finale after three failed attempts). See lib/components/regulatory-
 * update/manifest.json for the component contract.
 *
 * SPECIFICITY-BUMP HACK (transitional). Every section.regulatory-update
 * selector in this file is doubled to section.regulatory-update.regulatory-
 * update. Why: slides authored as `<!-- _class: regulatory-update timeline -->`
 * carry BOTH `.regulatory-update` AND `.timeline` classes, so
 * `section.timeline > ol > li::before { content: counter(timeline-counter) }`
 * (specificity 0,1,4) and `section.timeline h2 { margin-bottom: var(--sp-xl) }`
 * (specificity 0,1,2) MATCH and tie with the corresponding regulatory-
 * update rules.
 *
 * Pre-extraction, regulatory-update's CSS lived at the very end of
 * _legacy.css and won by source order. Post-extraction, this file
 * bundles alphabetically BEFORE lib/components/timeline/styles.css —
 * so timeline now wins source order, replacing the leading-zero
 * counter with plain decimal and inflating h2 margin-bottom by 36px.
 *
 * The doubled class adds 0,1,0 to every selector → 0,2,N → beats the
 * timeline component's 0,1,N rules on specificity, not source order.
 * Same pattern as the citation-card / redline hacks earlier in the
 * branch. Tracked for cleanup once the broader cascade story is
 * designed (likely: namespace component selectors more defensively,
 * or activate @layer once _legacy.css is fully retired).
 *
 * Pixel-check verified: 22/23 decks byte/pixel-clean against
 * pre-phase-5b baseline (component-gallery diffs are leftover from
 * earlier journey + math slide additions, not regulatory-update).
 */

/* ── REGULATORY-UPDATE ────────────────────────────────────────────────
 * Period-bounded changelog. "What's new" rhythm.
 *
 * <!-- _class: regulatory-update -->
 * `Q1 2026 · Federal · State · International`
 * 1. EU AI Act
 *    - `Title III · High-risk systems`
 *    - Conformity-assessment pre-market obligation took effect.
 *    - `Effective Feb 2026`
 * 2. FTC Order
 *    - `In re BetterHelp · §5 unfairness`
 *    - …
 *
 * Authoring contract: top-level li carries ONLY the regulation name
 * (auto-bolded by slotLabelLift). Nested ul carries the body — first
 * item is the citation chip (only-child <code>), middle items are
 * prose, last item is the impact / date pill (only-child <code>).
 *
 * Default = vertical changelog (numbered, citation chip, body, pill).
 * Variants: .cards, .timeline, .diff-bands, .priority.
 * ──────────────────────────────────────────────────────────────────── */
section.regulatory-update > .cell-stage { display:flex; flex-direction:column; }
section.regulatory-update.regulatory-update > .cell-stage > p:has(> code:only-child) {
  margin:0;
  padding-bottom:var(--sp-md);
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  letter-spacing:0.06em;
  color:var(--accent);
}
section.regulatory-update.regulatory-update > .cell-stage > p:has(> code:only-child) > code {
  background:none; border:none; padding:0; color:inherit;
}
section.regulatory-update.regulatory-update > .cell-stage > ol,
section.regulatory-update.regulatory-update > .cell-stage > ul {
  list-style:none; padding:0; margin:0;
  counter-reset:upd;
  display:flex; flex-direction:column;
  gap:var(--sp-xs);
  flex:1;
}
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li {
  counter-increment:upd;
  display:grid;
  grid-template-columns:auto auto auto 1fr auto;
  grid-template-rows:auto auto;
  column-gap:var(--sp-md);
  row-gap:0.234375cqi;
  align-items:baseline;
  padding:0.625cqi var(--sp-md);
  background:var(--bg-alt);
  border:1px solid var(--border);
  border-left:3px solid var(--accent);
  border-radius:var(--radius-md);
  color:var(--text-body);
  font-size:var(--fs-body);
  line-height:var(--lh-snug);
}
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li::marker { content:''; }
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li::before {
  content:counter(upd, decimal-leading-zero);
  grid-column:1; grid-row:1;
  font-family:var(--font-mono);
  font-size:var(--fs-body);
  font-weight:700;
  color:var(--accent);
  letter-spacing:0.04em;
}
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li > strong:first-child {
  grid-column:2; grid-row:1;
  font-size:var(--fs-body);
  font-weight:700;
  color:var(--text-heading);
}
/* Body list uses display:contents so its <li> children land directly in
 * the parent grid. Cite chip on row 1 col 3, prose on row 2 spans 2-4,
 * pill on row 1 col 5 (right-anchored). */
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li > ul,
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li > ol {
  display:contents;
  list-style:none;
}
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li {
  font-size:var(--fs-body);
  color:var(--text-body);
}
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li::marker { content:''; }
/* Citation chip — first nested item, only-child <code>. Row 1, col 3. */
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li:first-child:has(> code:only-child) {
  grid-column:3; grid-row:1;
}
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li:first-child:has(> code:only-child) > code {
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:600;
  color:var(--text-secondary);
  background:none; border:none; padding:0;
}
/* Prose body — middle nested items. Row 2 spans cols 2-4. */
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li:not(:first-child):not(:last-child) {
  grid-column:2 / span 3; grid-row:2;
}
/* Impact / date pill — last nested item, only-child <code>. Row 1, col 5. */
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li:last-child:has(> code:only-child) {
  grid-column:5; grid-row:1;
  justify-self:end;
}
section.regulatory-update.regulatory-update > .cell-stage > :is(ol, ul) > li > :is(ul, ol) > li:last-child:has(> code:only-child) > code {
