section.regulatory-update.regulatory-update.cards > .cell-stage > :is(ol, ul) > li::before { grid-row:1; }
section.regulatory-update.regulatory-update.cards > .cell-stage > :is(ol, ul) > li > strong:first-child { grid-row:1; grid-column:2; }
section.regulatory-update.regulatory-update.cards > .cell-stage > :is(ol, ul) > li > :is(ul, ol) {
