section.regulatory-update.regulatory-update.diff-bands > .cell-stage > h3 + :is(ol, ul) { padding-top:var(--sp-xs); }
section.regulatory-update.regulatory-update.diff-bands > .cell-stage > h3:nth-of-type(8n+1) { color:var(--pass); border-color:var(--pass); }
section.regulatory-update.regulatory-update.diff-bands > .cell-stage > h3:nth-of-type(8n+2) { color:var(--warn); border-color:var(--warn); }
section.regulatory-update.regulatory-update.diff-bands > .cell-stage > h3:nth-of-type(8n+3) { color:var(--fail); border-color:var(--fail); }
section.regulatory-update.regulatory-update.diff-bands > .cell-stage > h3:nth-of-type(8n+4) { color:var(--accent); border-color:var(--accent); }

/* .priority — tiered priority badges. */
section.regulatory-update.regulatory-update.priority > .cell-stage > :is(ol, ul) > li::before {
