section.split-panel.steps .panel-right > :is(ul,ol) > li > :is(ul,ol) > li { font-size:var(--fs-body); font-family:var(--font-body); color:var(--text-body); line-height:var(--lh-relaxed); }

/* ── .watermark — accent panel + letterform + points + meta footer (former split-list) ── */
section.split-panel.watermark .panel-left { width:34%; background:var(--accent); justify-content:flex-end; }
section.split-panel.watermark .panel-left::before { background:var(--on-accent-watermark); height:4px; }
