section.split-panel.watermark .panel-left > p:has(> code:only-child) > code { color:var(--on-accent-secondary); background:none; border:none; padding:0; border-radius:0; }
section.split-panel.watermark .panel-left > h5 { position:absolute; top:var(--sp-xl); margin:0; color:var(--on-accent-secondary); }
section.split-panel.watermark .panel-right { padding:var(--sp-xl) var(--sp-xl) var(--sp-xl) var(--sp-lg); }
section.split-panel.watermark .panel-right h3 { font-family:inherit; text-transform:none; letter-spacing:normal; border-bottom:none; padding-bottom:0.3125cqi; color:var(--text-heading); }
section.split-panel.watermark .panel-right p { font-size:var(--fs-body); line-height:var(--lh-relaxed); padding-bottom:var(--sp-md); }
section.split-panel.watermark .panel-right > :is(ul,ol) { display:flex; flex-direction:column; justify-content:flex-start; gap:var(--sp-sm); flex:1; list-style:none; padding:0; margin:0; }
section.split-panel.watermark .panel-right > ol { counter-reset:panel-counter; }
section.split-panel.watermark .panel-right > :is(ul,ol) > li { display:grid; align-content:start; justify-items:start; background:var(--bg-alt); border:1px solid var(--border); border-left:1px solid var(--border); border-radius:var(--radius-md); padding:1.09375cqi 1.40625cqi; font-size:var(--fs-body); color:var(--text-heading); font-weight:700; line-height:var(--lh-snug); }
section.split-panel.watermark .panel-right > ol > li { counter-increment:panel-counter; grid-template-columns:3.59375cqi 1fr; grid-auto-rows:auto; column-gap:0.78125cqi; justify-items:stretch; padding:0; overflow:hidden; border:none; }
section.split-panel.watermark .panel-right > ol > li::before { content:counter(panel-counter); grid-column:1; grid-row:1 / span 10; align-self:stretch; display:flex; align-items:center; justify-content:center; background:var(--accent); color:var(--on-accent, var(--on-dark-primary)); font-family:var(--font-mono); font-size:1.875cqi /* cqi-ok: counter numeral inside a fixed accent disc */; font-weight:800; }
section.split-panel.watermark .panel-right > ol > li > :is(strong,span,p,em) { grid-column:2; padding:0.703125cqi 1.25cqi 0.234375cqi; margin:0; font-size:var(--fs-body); color:var(--text-heading); font-weight:700; line-height:var(--lh-snug); }
section.split-panel.watermark .panel-right > ol > li > :is(strong,span,p,em):last-child { padding-bottom:0.703125cqi; }
section.split-panel.watermark .panel-right > :is(ul,ol) > li > strong { display:block; }
/* Card body. `width:100% + padding` would overflow a content-box, so border-box (#198).
 * Only the NUMBERED (ol) card insets the body to match its header's 1.25cqi (the header
 * rule above) — the plain (ul) card's header has no inset, so its body stays flush; a
 * shared rule mis-aligned one or the other. The doubled `.watermark.watermark` lifts the
 * ol-body inset above this general rule regardless of source order. */
section.split-panel.watermark .panel-right > :is(ul,ol) > li > :is(ul,ol) { display:block; list-style:none; padding:0.3125cqi 0 0 0; margin:0; width:100%; box-sizing:border-box; }
section.split-panel.watermark.watermark .panel-right > ol > li > :is(ul,ol) { grid-column:2; padding:0.3125cqi 1.25cqi 0 1.25cqi; }
section.split-panel.watermark .panel-right > :is(ul,ol) > li > :is(ul,ol) > li { display:block; list-style:none; background:none; border:none; border-radius:0; padding:0; margin:0; font-size:var(--fs-body); color:var(--text-body); line-height:var(--lh-snug); font-weight:400; }
section.split-panel.watermark .panel-right > :is(ul,ol) > li > :is(ul,ol) > li > p { margin:0; }
/* optional metadata footer — a trailing ul after the main list (Audience · Intent) */
section.split-panel.watermark .panel-right :is(ol,ul) + ul { padding-top:var(--sp-sm); border-top:1px solid var(--border); display:flex; flex-direction:column; gap:0.3125cqi; flex:0 0 auto; list-style:none; }
section.split-panel.watermark .panel-right :is(ol,ul) + ul > li { display:block; background:none; border:none; border-radius:0; padding:0; margin:0; font-size:var(--fs-body); font-weight:400; color:var(--text-body); line-height:var(--lh-snug); }
section.split-panel.watermark .panel-right :is(ol,ul) + ul > li::before { font-weight:700; color:var(--text-heading); padding-right:0.4em; }
section.split-panel.watermark .panel-right :is(ol,ul) + ul > li:nth-child(1)::before { content:"Audience ·"; }
section.split-panel.watermark .panel-right :is(ol,ul) + ul > li:nth-child(2)::before { content:"Intent ·"; }
section.split-panel.watermark { --marp-slide-header-color: var(--on-accent-secondary); --marp-slide-footer-color: var(--on-accent-secondary); }

/* Hardening: element siblings of <strong> in a card li don't inherit
 * the parent's font-weight:700. See CARD_STYLE_LAYOUTS in lib/components/index.js. */
section.split-panel :is(ul,ol) > li > strong ~ * { font-weight: 400; }

/* ── Portrait / square reflow (social/mobile @sizes). The left rail stacks
 * above the content panel instead of beside it. Keyed on the deck-wide
 * data-orientation stamp (lib/engine/slides.js); landscape untouched. See
 * 2026-06-16-social-mobile-portrait-sizes.md (phase 3). */
section.split-panel[data-orientation="portrait"] { flex-direction: column; }
section.split-panel[data-orientation="portrait"] .panel-left { width: auto; }

/* ── Feature-cover carousel — split-panel's owned SPLIT forms ──────────────────
   When an overflowing split-panel can't fit its heavy feature panel beside its
   supporting points in a tall box, the Fit Ladder re-authors it as a sequence
   (2026-06-23-read-across-carousel.md; recipe SP3): the feature gets a full cover,
   then the points flow on clean pages. lib/core/carousel.js emits the role sections
   (`content split-panel-split split-panel-{cover,points} form`). Palette-blind. */

/* Cover — the feature gets its moment: accent field, watermark, hero heading. */
section.split-panel-cover {
  background: var(--accent); color: var(--on-accent);
  display: flex; flex-direction: column; justify-content: center;
  position: relative;
}
/* The watermark bleeds off the corner — but a positioned descendant overflowing the
   section inflates its scrollWidth/Height (which the overflow measure reads as a clip),
   so contain it in a box that fills the section and is the scroll container for the
   bleed. The section's own overflow is left to the `content` layer. */
section.split-panel-cover .split-feat-bleed {
  position: absolute; inset: 0; overflow: hidden; pointer-events: none;
}
section.split-panel-cover .split-feat-wm {
  position: absolute; right: -0.08em; bottom: -0.28em; line-height: 0.8;
  font-size: 20em; font-weight: 800; opacity: 0.13; pointer-events: none;
}
section.split-panel-cover .split-feat-eye {
  font-size: var(--fs-meta); letter-spacing: 0.2em; text-transform: uppercase; opacity: 0.85;
}
section.split-panel-cover .split-feat-h {
  /* h1, not hero — a split-panel heading can be a full sentence, and hero overflows
     the cover past ~10 words. h1 keeps a short title dramatic and a long one fitting. */
  font-size: var(--fs-h1); font-weight: 800; line-height: var(--lh-tight);
  color: var(--on-accent); padding: var(--sp-xs) 0 var(--sp-md); max-width: 12em;
}
section.split-panel-cover .split-feat-lede {
  font-size: var(--fs-emphasis); line-height: var(--lh-snug); opacity: 0.92; max-width: 20em;
}

/* Point pages — the supporting points flow under a running header of the feature. */
section.split-panel-points .split-runhead {
  font-size: var(--fs-meta); letter-spacing: 0.2em; text-transform: uppercase;
  color: var(--text-muted); border-bottom: 1px solid var(--border);
  padding-bottom: var(--sp-xs);
}
section.split-panel-points .split-pts {
  list-style: none; padding: var(--sp-xl) 0 0 0; margin: 0;
  display: flex; flex-direction: column; gap: var(--sp-lg);
}
section.split-panel-points .split-pts > li { border-left: 3px solid var(--accent); padding-left: var(--sp-md); }
section.split-panel-points .split-pt-t {
  display: block; font-weight: 800; color: var(--text-heading); font-size: var(--fs-h3);
  padding-bottom: var(--sp-3xs);
}
section.split-panel-points .split-pt-b { color: var(--text-body); font-size: var(--fs-body); line-height: var(--lh-base); }

/* ── Struck elevation (base.tokens.css --elevation-card) ── lift the cards; vertical
 * berth (padding-block, never margin — #20) so the stage's overflow:clip doesn't
 * shear the shadow. Shadow has no horizontal extent, so no horizontal berth. */
section.split-panel.watermark .panel-right > :is(ul,ol) > li {
  box-shadow: var(--elevation-card);
}
section.split-panel > .cell-stage {
  padding-block: var(--elevation-berth);
}

/* === lib/components/chart/state-chart/state-chart.styles.css === */
/* state-chart — native state machine diagram, browser-measured layout.
 *
 * Build time emits HTML state nodes (the browser sizes them to their
 * content — any label, script, font), a transitions JSON data attr, and
 * an empty SVG overlay. A browser pass (installStateChartLayout, run by
 * puppeteer for the PDF and by lattice-runtime for the marp-vscode
 * preview) measures the laid-out nodes with getBoundingClientRect and
 * draws the edges + start (●) / terminal (◎) markers into the SVG.
 *
 *   <div class="state-chart-figure" data-variant="default" data-sc-transitions="[…]">
 *     <ol class="state-nodes">
 *       <li class="state-node" data-index="N" [data-kind="start|terminal"] [data-s="…"]>
 *         <span class="state-index" [data-s="…"]>N</span>   (status colours the badge)
 *         <span class="state-label">…</span>
 *       </li>
 *     </ol>
 *     <svg class="state-chart-edges">…filled by the browser pass…</svg>
 *   </div>
 *   <ol class="state-legend">…swatch + label per distinct status…</ol>
 *
 * Nodes are NEUTRAL (--bg-alt) so colour is reserved for meaning: status is NOT
 * a wide text pill (a state machine shows flow, not a dashboard) — it folds into
 * the top-right index numeral, which becomes a colour-coded badge (number = the
 * state ID, colour = the status), using the same AA-vetted tone vocabulary
 * chart-family's .chart-status uses (pass/warn/fail/info/mute) and decoded by the
 * legend band below. Mirrors journey's glyph-in-a-disc + legend. Palette-blind
 * throughout — no hex literals, no !important, no :has() chains.
 *
 * Sibling implementations (three-renderer parity via the shared registry):
 *   - lib/components/chart/state-chart/state-chart.transform.js  kernel + browser fn
 *   - lib/components/chart/_chart-family/chart-family.js         dispatch
 *   - lattice-emulator.js                                        emits the bootstrap
 *   - lib/runtime/index.js → lattice-runtime.js                  preview pass
 */

section.state-chart {
  --state-node-fill: var(--bg-alt);
  --state-node-ink: var(--text-heading);
  --state-node-stroke: var(--diagram-stroke);
  --state-edge: var(--diagram-line);
  --state-edge-back: color-mix(in oklab, var(--diagram-line) 55%, transparent);
  --state-index-ink: var(--text-muted);
  --state-marker: var(--diagram-line);
  --state-label-bg: var(--bg);
}

section.state-chart.chart-frame .chart-body {
  width: 100%;
  padding: var(--sp-md) var(--sp-2xl);
  display: flex;
  flex-direction: column;       /* figure stacks above the status legend band */
  align-items: center;
  justify-content: center;
  gap: var(--sp-sm);
  /* Fill the stage by GROW with a ZERO basis — not `auto`, whose content-basis
   * the absolutely-positioned scale box (its natural height can be many times the
   * stage) confuses into collapsing the body to its padding. Basis 0 makes the
   * body take its full flex share = the stage height, so the figure viewport below
   * is definite and the letterbox scale has a real box to fit into. */
  flex: 1 1 0;
  min-height: 0;
}

/* Figure = the flex VIEWPORT + the positioning context for the scale box. It fills
 * the available stage height (flex:1 1 auto in .chart-body's column) so the caption +
 * status legend keep their space. It must NOT size to the content — the scale box is
 * `position:absolute` (out of flow) precisely so a tall machine's natural height can't
 * flow into the flex basis and collapse the chain; the figure fills the stage by grow,
 * and draw() scales the absolute box to fit here (2026-07-16-state-chart-self-scale.md). */
section.state-chart .state-chart-figure {
  position: relative;
  flex: 1 1 0;             /* zero basis: fill the body by grow, not by content */
  min-height: 0;
  width: 100%;
}

/* Scale box — the NATURAL-SIZE geometry root (nodes + the absolutely-placed SVG
 * overlay), width:fit-content sized to the padded node column (the bow-gutter padding
 * is real space inside it). OUT OF FLOW (absolute, centred via top/left 50% +
 * translate) so the flex viewport above never inherits its height. draw() reads its
 * natural box, routes the edges into it, then appends `scale()` to letterbox it into
 * the viewport — like the pie's <svg>, but for HTML content. */
section.state-chart .state-chart-scale {
  position: absolute;
  top: 50%;
  left: 50%;
  width: fit-content;
  transform-origin: center center;
  transform: translate(-50%, -50%);   /* centred; draw() appends the fit scale() */
}

/* Node column (TB, default) — centred, content-sized HTML nodes. The
 * generous horizontal padding is the bow gutter: forward skips bow into
 * the right gutter, back-edges into the left, so they stay inside the
 * figure and never clip. Vertical padding hosts the start/terminal
 * markers. Sits above the edge layer. */
section.state-chart .state-nodes {
  list-style: none;
  margin: 0;
  padding: 4.375cqi 10cqi;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2.65625cqi;
  position: relative;
  z-index: 1;
}

/* LR row — nodes flow left-to-right, centred on the cross (vertical) axis.
 * Horizontal padding hosts the start (left) / terminal (right) markers;
 * the larger vertical padding is the bow gutter (forward below, back
 * above). overflow-x lets long rows scroll without clipping the bows. */
section.state-chart .state-chart-figure[data-sc-dir="lr"] .state-nodes {
  flex-direction: row;
  align-items: center;
  /* Tighter horizontal gutter + gap than the comment's original 60/56: at 5
   * nodes the row overran the slide and clipped the terminal node (a static
   * PDF can't scroll). Narrower gutters fit the documented 4–6 node range. */
  padding: 7.8125cqi 3.125cqi;
  gap: 3.125cqi;
}

/* Curved (TB with bowed back-edges): a 5-state flow plus start + terminal
 * markers overran the slide height and clipped the terminal ◉ at the bottom.
 * Tighten the vertical rhythm (the wide horizontal padding stays — it hosts
 * the bowed back-edge). */
section.state-chart .state-chart-figure[data-sc-style="curved"] .state-nodes {
  padding-top: 3.4375cqi;
  padding-bottom: 3.4375cqi;
  gap: 2.03125cqi;
}

section.state-chart .state-node {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: var(--sp-sm);
  max-width: 25cqi;
  padding: 0.78125cqi 1.25cqi;
  /* THE CANONICAL CHART FILL (chart-family.css): every node is a quiet neutral
   * slate tile, exactly like a kanban card with no lane. The node fill is ALWAYS
   * neutral — status colour lives only in the index badge (see below), never the
   * node fill, so a green "on-track" node can't blend into a green wash. */
  --fill-hue: var(--text-muted);
  --fill-ink: var(--diagram-stroke);
  background: linear-gradient(180deg,
    light-dark(color-mix(in oklab, var(--fill-hue) var(--chart-fill-top-l),    var(--bg)),
               color-mix(in oklab, var(--fill-hue) var(--chart-fill-top-d),    black)) 0%,
    light-dark(color-mix(in oklab, var(--fill-hue) var(--chart-fill-bottom-l), var(--bg)),
               color-mix(in oklab, var(--fill-hue) var(--chart-fill-bottom-d), black)) 100%);
  border: var(--chart-hairline) solid color-mix(in oklab, var(--fill-hue) var(--chart-fill-edge), var(--border));
  border-left: var(--chart-fill-accent) solid var(--fill-ink);
  color: var(--state-node-ink);
  border-radius: 0.46875cqi;
  font-weight: 500;
  line-height: 1.25;
}

/* Nodes stay NEUTRAL — a kanban card with no lane. Status is deliberately NOT
 * painted onto the node fill: a green "on-track" node would overload green's
 * fixed semantic and widen the column. Colour lives in the small .state-dot
 * (decoded by the legend band) — the one hue on an otherwise quiet tile.
 * (data-s is kept on the node for the dot and the start/terminal cues.) */

section.state-chart .state-node .state-label {
  min-width: 0;
}

/* The index numeral doubles as the status badge: a status-LESS node keeps a
 * quiet top-right ref numeral; a status node turns that numeral into a small
 * coloured badge (index + status in ONE element — no separate dot, no widening
 * the node). The badge and the legend swatch share the .chart-status pill fill
 * recipe (AA-vetted: --text-heading on a hue-into-bg tint + a vivid --pill-ink
 * edge), so a node's badge reads identically to its legend key. */
section.state-chart .state-node .state-index {
  position: absolute;
  top: 0.15625cqi;
  right: 0.390625cqi;
  font-size: 0.703125cqi; /* cqi-ok: index numeral inside a cqi-sized state node */
  font-variant-numeric: tabular-nums;
  color: var(--state-index-ink);
  pointer-events: none;
}

/* Shared status-tone swatch recipe (badge + legend dot). */
section.state-chart .state-index[data-s],
section.state-chart .state-dot {
  --pill-hue: var(--state-info-hue);
  --pill-ink: var(--state-info-ink);
  background: linear-gradient(180deg,
    light-dark(color-mix(in oklab, var(--pill-hue) 33%, var(--bg)), color-mix(in oklab, var(--pill-hue) 48%, black)) 0%,
    light-dark(color-mix(in oklab, var(--pill-hue) 54%, var(--bg)), color-mix(in oklab, var(--pill-hue) 64%, black)) 100%);
  border: var(--chart-hairline) solid var(--pill-ink);
}
section.state-chart .state-index[data-s="on-track"], section.state-chart .state-dot[data-s="on-track"],
section.state-chart .state-index[data-s="done"],     section.state-chart .state-dot[data-s="done"],
section.state-chart .state-index[data-s="live"],     section.state-chart .state-dot[data-s="live"]
  { --pill-hue: var(--state-pass-hue); --pill-ink: var(--state-pass-ink); }
section.state-chart .state-index[data-s="at-risk"],  section.state-chart .state-dot[data-s="at-risk"],
section.state-chart .state-index[data-s="warn"],     section.state-chart .state-dot[data-s="warn"]
  { --pill-hue: var(--state-warn-hue); --pill-ink: var(--state-warn-ink); }
section.state-chart .state-index[data-s="blocked"],  section.state-chart .state-dot[data-s="blocked"],
section.state-chart .state-index[data-s="fail"],     section.state-chart .state-dot[data-s="fail"]
  { --pill-hue: var(--state-fail-hue); --pill-ink: var(--state-fail-ink); }
section.state-chart .state-index[data-s="pilot"],    section.state-chart .state-dot[data-s="pilot"],
section.state-chart .state-index[data-s="decision"], section.state-chart .state-dot[data-s="decision"]
  { --pill-hue: var(--state-info-hue); --pill-ink: var(--state-info-ink); }
section.state-chart .state-index[data-s="deferred"], section.state-chart .state-dot[data-s="deferred"]
  { --pill-hue: var(--state-mute-hue); --pill-ink: var(--state-mute-ink); }

/* Status badge — the numeral inside a coloured disc, overhanging the top-right
 * corner (so it never overlaps the label). The wide horizontal node gutter
 * absorbs the overhang without clipping. */
section.state-chart .state-index[data-s] {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  top: -0.55cqi;
  right: -0.55cqi;
  min-width: 1.65cqi;
  height: 1.65cqi;
  padding: 0 0.32cqi;
  border-radius: 0.825cqi;
  color: var(--text-heading);
  font-size: 0.78125cqi; /* cqi-ok: index numeral inside a cqi-sized badge */
  font-weight: 600;
  line-height: 1;
}

/* Legend swatch — same recipe as the badge, a plain disc (no numeral). */
section.state-chart .state-dot {
  flex: 0 0 auto;
  width: 1.1cqi;
  height: 1.1cqi;
  border-radius: 50%;
}

/* Status legend band — a centred row of dot + label, decoding the node dots.
 * Same shape as journey's .journey-legend (flex-wrap key band). */
section.state-chart .state-legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--sp-xs) var(--sp-lg);
  list-style: none;
  margin: 0;
  padding: 0;
  font-size: var(--fs-body-compact);
  color: var(--text-secondary, var(--text-body));
}
section.state-chart .state-legend-item {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-xs);
}
section.state-chart .state-legend-label {
  font-family: var(--pill-font);
  letter-spacing: var(--pill-tracking);
}

/* Start / terminal redundancy cues alongside the SVG ●/◎ glyphs. Every node now
 * carries a 4px accent; the start node reads heavier (keeps its neutral/status
 * stripe colour), the terminal keeps its outline ring. */
section.state-chart .state-node[data-kind="start"] {
  border-left-width: clamp(7px, 0.546875cqi, 9px);
}

section.state-chart .state-node[data-kind="terminal"] {
  outline: 0.1171875cqi solid var(--state-node-stroke);
  outline-offset: 0.15625cqi;
}

/* SVG edge overlay — covers the whole figure; the browser pass sets its
 * viewBox to the figure's measured pixel box so 1 unit == 1px. Behind the
 * node column so node fills hide any sub-pixel edge overhang. */
section.state-chart .state-chart-edges {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  overflow: visible;
  z-index: 0;
}

section.state-chart .state-edge {
  fill: none;
  stroke: var(--state-edge);
  stroke-width: 0.109375cqi;
  stroke-linecap: round;
}

/* ── Box-local portrait fill (tall/narrow box) ───────────────────────────────
 * The default machine is ALREADY vertical (top-to-bottom column), so a tall box
 * needs no reflow — but the inter-node gap is `cqi` (a share of WIDTH), so on a
 * narrow portrait box it shrinks and the chain strands itself in the middle with
 * dead space above and below. Let the node column take the full height and
 * distribute the states down it; the browser edge-pass re-measures the laid-out
 * positions, so the arrows follow. (An `lr` machine is already flipped back to
 * this vertical default at build time — see state-chart.transform.js.) Keyed on
 * the nearest `lattice` container; landscape untouched. ≤0.9 = tall+strip.
 * 2026-06-19-chart-adaptive-sizing.md §10. */
@container lattice (aspect-ratio <= 0.9) {
  /* The figure viewport already fills the stage (flex:1). The SCALE BOX must also
   * take the full height so `.state-nodes { height:100% }` below resolves against a
   * DEFINITE height and `space-evenly` has room to distribute — otherwise the box's
   * default auto height collapses the fill (the node column strands in the middle).
   * At full height the natural column ≈ the viewport, so the landscape self-scale is
   * a no-op here (raw ≈ 1); portrait fills by distribution, landscape by letterbox. */
  section.state-chart .state-chart-scale { height: 100%; }
  section.state-chart .state-nodes {
    height: 100%;
    justify-content: space-evenly;
  }
}

section.state-chart .state-edge[data-dir="back"] {
  stroke: var(--state-edge-back);
  stroke-dasharray: 4 3;
}

section.state-chart .state-edge[data-self="true"] {
  stroke-width: 0.1015625cqi;
}

section.state-chart .state-edge-arrow {
  fill: var(--state-edge);
  stroke: none;
}

section.state-chart .state-edge-arrow[data-dir="back"] {
  fill: var(--state-edge-back);
}

/* Edge labels sit ON the line at its midpoint (centred). The halo is a
 * background-coloured stroke painted UNDER the glyphs (paint-order:stroke),
 * knocking out the edge behind the text so the line visibly breaks around
 * the label with a clear gap on each side. */
section.state-chart .state-edge-label {
  fill: var(--state-node-ink);
  font-size: 0.859375cqi; /* cqi-ok: edge label on a cqi-sized transition arrow */
  font-family: var(--font-mono);
  paint-order: stroke;
  stroke: var(--state-label-bg);
  stroke-width: 0.46875cqi;
  stroke-linejoin: round;
  stroke-linecap: round;
  pointer-events: none;
}

section.state-chart .state-marker-disc {
  fill: var(--state-marker);
  stroke: none;
}

section.state-chart .state-marker-ring {
  fill: none;
  stroke: var(--state-marker);
  stroke-width: 0.1171875cqi;
}

section.state-chart .state-marker-line {
  fill: none;
  stroke: var(--state-edge);
  stroke-width: 0.109375cqi;
  stroke-linecap: round;
}

/* ── Inline variant (HTML chips, no SVG) ─────────────────────────────── */

section.state-chart.inline .state-chart-figure,
section.state-chart.horizontal .state-chart-figure {
  width: auto;
  max-width: 59.375cqi;
}

section.state-chart.inline .state-rows,
section.state-chart.horizontal .state-rows {
  list-style: none;
  margin: 0;
  /* Row spacing lives on the container as flex gap + edge padding (was a
   * per-row margin: 0.3125cqi 0; margins collapse outside the flex box and
   * break virtual-list scrollHeight measurement). Adjacent rows' collapsed
   * margin was 0.3125cqi → gap; the first/last outer margin → padding. */
  display: flex;
  flex-direction: column;
  gap: 0.3125cqi;
  padding: 0.3125cqi 0;
}

section.state-chart.inline .state-node-row,
section.state-chart.horizontal .state-node-row {
  position: relative;
  display: flex;
  align-items: center;
  /* Right-anchor the transitions cluster via space-between (was margin-left:auto
   * on .state-transitions — auto margins sit outside the flex content box). The
   * label is the left child, the transitions the right; the index is absolute. */
  justify-content: space-between;
  gap: var(--sp-sm);
  padding: var(--sp-sm) var(--sp-md);
  /* Row spacing is the container's flex gap now (was margin: 0.3125cqi 0). */
  /* Same canonical tile as the SVG-variant nodes above. */
  --fill-hue: var(--text-muted);
  --fill-ink: var(--diagram-stroke);
  background: linear-gradient(180deg,
    light-dark(color-mix(in oklab, var(--fill-hue) var(--chart-fill-top-l),    var(--bg)),
               color-mix(in oklab, var(--fill-hue) var(--chart-fill-top-d),    black)) 0%,
    light-dark(color-mix(in oklab, var(--fill-hue) var(--chart-fill-bottom-l), var(--bg)),
               color-mix(in oklab, var(--fill-hue) var(--chart-fill-bottom-d), black)) 100%);
  border: var(--chart-hairline) solid color-mix(in oklab, var(--fill-hue) var(--chart-fill-edge), var(--border));
  border-left: var(--chart-fill-accent) solid var(--fill-ink);
  color: var(--state-node-ink);
  border-radius: 0.46875cqi;
}
/* Neutral rows too — the pill carries the status colour (see the SVG-node note). */

section.state-chart.inline .state-node-row[data-kind="start"],
section.state-chart.horizontal .state-node-row[data-kind="start"] {
  border-left-width: clamp(7px, 0.546875cqi, 9px);
}

section.state-chart.inline .state-node-row[data-kind="terminal"],
section.state-chart.horizontal .state-node-row[data-kind="terminal"] {
  outline: 0.1171875cqi solid var(--state-node-stroke);
  outline-offset: 0.15625cqi;
}

section.state-chart.inline .state-node-row .state-label,
section.state-chart.horizontal .state-node-row .state-label {
  flex: 0 0 auto;
  font-weight: 500;
}

section.state-chart.inline .state-node-row .state-index,
section.state-chart.horizontal .state-node-row .state-index {
  position: absolute;
  top: 0.15625cqi;
  right: 0.46875cqi;
  font-size: 0.703125cqi; /* cqi-ok: index numeral inside a cqi-sized state node */
  color: var(--state-index-ink);
}

/* Inline LR (lr inline, or the horizontal alias) flows the chip rows
 * left-to-right; keyed on the figure's resolved direction. */
section.state-chart .state-chart-figure[data-variant="inline"][data-sc-dir="lr"] .state-rows {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  overflow-x: auto;
  gap: var(--sp-sm);
  padding: var(--sp-sm) 0;
}

section.state-chart .state-chart-figure[data-variant="inline"][data-sc-dir="lr"] .state-node-row {
  flex: 0 0 auto;
  min-width: 10.9375cqi;
}

section.state-chart.inline .state-transitions,
section.state-chart.horizontal .state-transitions {
  display: inline-flex;
  flex-wrap: wrap;
  gap: var(--sp-xs);
  /* Right-anchored by the row's justify-content:space-between (was margin-left:auto). */
  align-items: center;
}

section.state-chart.inline .state-chip,
section.state-chart.horizontal .state-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  line-height: 1;
  gap: 0.3125cqi;
  font-family: var(--pill-font);
  font-size: var(--pill-fs);
  font-weight: var(--pill-weight);
  letter-spacing: var(--pill-tracking);
  padding: var(--pill-pad-y) var(--pill-pad-x);
  border: var(--chart-hairline) solid var(--state-node-stroke);
  border-radius: var(--pill-radius);
  background: color-mix(in oklab, var(--state-node-fill) 60%, transparent);
}

section.state-chart.inline .state-chip[data-dir="back"],
section.state-chart.horizontal .state-chip[data-dir="back"] {
  border-style: dashed;
}

section.state-chart.inline .state-chip-event,
section.state-chart.horizontal .state-chip-event {
  font-family: var(--font-mono);
}

section.state-chart.inline .state-chip-arrow,
section.state-chart.horizontal .state-chip-arrow {
  color: var(--state-index-ink);
  font-variant-numeric: tabular-nums;
}

/* ── Dark canvas ─────────────────────────────────────────────────────────
 * section.dark sets color-scheme:dark, flipping every light-dark() token
 * this component consumes (--bg-alt, --text-heading, --diagram-line, --bg,
 * --text-muted, and chart-family's --pass/--warn/--fail) automatically. */

/* ── SVG-native nodes (2026-07-26) ───────────────────────────────────────────
 * The state-chart lays its nodes out as HTML on purpose: a string transform
 * cannot measure text, so the browser sizes each node to its real content. That
 * is the whole reason installStateChartLayout exists — and it is also why the
 * chart used to be un-animatable: chart motion addresses marks inside the first
 * <svg>, and the states were <li>s outside it.
 *
 * The measuring pass now PAINTS those measured boxes into the same overlay it
 * already drew the edges into. So the geometry is still real metrics (never the
 * guessed glyph widths this architecture replaced), but the whole chart is one
 * SVG and every state, connector and label is an addressable node.
 *
 * The HTML column stays in the layout as the measuring harness and is hidden
 * once the SVG exists — `visibility:hidden`, NOT `display:none`, because the
 * boxes must keep occupying space for the next re-measure (resize, font load).
 * Until the pass runs (or if it never does) the HTML nodes are what you see, so
 * this degrades to the previous rendering rather than to nothing. */
section.state-chart .state-chart-figure[data-sc-svg="1"] .state-nodes {
  visibility: hidden;
}

/* The node tile — the SVG twin of the .state-node card. Same canonical chart
 * fill, and because SVG `fill` cannot take a CSS gradient, the layout pass
 * emits it as an inline `<linearGradient>` per node and points the rect at
 * `fill="url(#…)"`. So the gradient DEFS are generated in JS
 * (state-chart.transform.js `nodeFillDefs`) and only the edge is styled here.
 * The fill stays a single neutral tone whatever the state's status — status
 * color lives in the index badge, never the node fill, so a green "on-track"
 * node can't blend into a green wash. */
/* The painted node is the HIT TARGET for the mark-detail popover. The overlay
 * is `pointer-events: none` (it must not swallow clicks meant for the slide),
 * and the measuring column is `visibility: hidden`, which also makes it
 * un-hit-testable — so without re-enabling pointer events HERE,
 * `elementFromPoint` finds nothing carrying `data-mark` and the popover never
 * opens on a state. It is the rect that carries the mark, so it is the rect
 * that must be hittable. */
section.state-chart .state-node-shape {
  pointer-events: auto;
  /* The FILL is the canonical chart gradient, emitted inline by the layout pass
   * (SVG fill cannot take a CSS gradient). What stays here is the edge. */
  --fill-hue: var(--text-muted);
  stroke: color-mix(in oklab, var(--fill-hue) var(--chart-fill-edge), var(--border));
  stroke-width: 1;
}

/* The node's leading accent edge — the HTML card's
 * `border-left: var(--chart-fill-accent) solid var(--fill-ink)`. */
section.state-chart .state-node-accent {
  fill: var(--diagram-stroke);
}

section.state-chart .state-label-t {
  fill: var(--state-node-ink);
  font-family: var(--font-body);
  font-weight: 500;
}

/* The index numeral doubles as the status badge — a status-LESS node keeps a
 * quiet numeral; a status node gets the colored disc behind it. Same tone
 * vocabulary and the same --pill-* recipe as the HTML badge and the legend
 * swatch, so a node's badge still reads identically to its legend key. */
section.state-chart .state-index-t {
  fill: var(--state-index-ink);
  font-family: var(--font-body);
  font-variant-numeric: tabular-nums;
}
section.state-chart .state-index-t[data-s] {
  fill: var(--text-heading);
}
section.state-chart .state-index-disc {
  --pill-hue: var(--state-info-hue);
  --pill-ink: var(--state-info-ink);
  fill: light-dark(
    color-mix(in oklab, var(--pill-hue) 54%, var(--bg)),
    color-mix(in oklab, var(--pill-hue) 64%, black));
  stroke: var(--pill-ink);
  stroke-width: 0.75;
}
section.state-chart .state-index-disc[data-s="on-track"],
section.state-chart .state-index-disc[data-s="done"],
section.state-chart .state-index-disc[data-s="live"]     { --pill-hue: var(--state-pass-hue); --pill-ink: var(--state-pass-ink); }
section.state-chart .state-index-disc[data-s="at-risk"],
section.state-chart .state-index-disc[data-s="warn"]     { --pill-hue: var(--state-warn-hue); --pill-ink: var(--state-warn-ink); }
section.state-chart .state-index-disc[data-s="blocked"],
section.state-chart .state-index-disc[data-s="fail"]     { --pill-hue: var(--state-fail-hue); --pill-ink: var(--state-fail-ink); }
section.state-chart .state-index-disc[data-s="pilot"],
section.state-chart .state-index-disc[data-s="decision"] { --pill-hue: var(--state-info-hue); --pill-ink: var(--state-info-ink); }
section.state-chart .state-index-disc[data-s="deferred"] { --pill-hue: var(--state-mute-hue); --pill-ink: var(--state-mute-ink); }

/* Start and terminal keep DISTINCT redundancy cues, as the HTML card did — the
 * start node reads heavier at its leading edge, the terminal wears an outline
 * ring. Collapsing both into one identical rule (an earlier cut) made the two
 * ends of a machine visually indistinguishable, which is the one distinction a
 * state diagram must never lose. */
section.state-chart .state-node-shape[data-kind="start"] {
  stroke: var(--state-node-stroke);
  stroke-width: 1.5;
}
/* The start node's heavier leading stripe — the HTML card's wider border-left. */
section.state-chart .state-node-accent[data-kind="start"] {
  fill: var(--state-node-stroke);
}
/* The terminal ring: SVG has no `outline`, so the layout pass emits a second,
 * offset rect behind the node — the same doubled edge the HTML outline drew. */
section.state-chart .state-node-shape[data-kind="terminal"] {
  stroke: var(--state-node-stroke);
  stroke-width: 1.5;
}
section.state-chart .state-node-ring {
  fill: none;
  stroke: var(--state-node-stroke);
  stroke-width: 1;
}

/* Reveal focus cue — the shared reveal layer toggles .chart-mark-active on the
 * focused mark and dims the rest. A hue edge, not a filter: a filter would
 * rasterize the node in the PDF path. */
section.state-chart .state-node-shape.chart-mark-active {
  stroke: var(--accent);
  stroke-width: 2;
}

/* === lib/components/evidence/stats/stats.styles.css === */
/* stats — evidence.stack.stats
 *
 * Row of 3–5 stat tiles. Each tile = big number + uppercase label.
 * Authored as a plain nested list — the number is the parent list item
 * (lifted to <strong> by the shared slot-label lift; typing `**…**` is an
 * idempotent no-op), the label is its nested sublist:
 *
 *   1. 73%
 *      - faster close
 *
 * No structural transform: the <ol>/<li> is styled directly. (Until
 * 2026-06-07 the emulator rebuilt this into .stats-row > .stat-item while
 * marp/runtime styled the raw list — see
 * engineering/decisions/2026-06-07-slot-header-auto-lift.md.)
 *
 * See lib/components/evidence/stats/stats.manifest.json for the contract.
 */

section.stats > .cell-stage { display:flex; flex-direction:column; justify-content:center; align-items:center; }
/* The heading + subtitle are framing text — they follow the headline-alignment seam
 * (`headline:`) via their OWN align-self, so the centered stat strip below is untouched (its
 * `align-items:center` on the stage stays). `auto`/no register → the fallback `center`, so a
 * default stats slide is byte-identical. */
section.stats h2 { padding-bottom:var(--sp-xs); text-align:var(--headline-align, center); align-self:var(--headline-justify, center); }
/* CONSISTENT-DEFAULTS: stats centers its heading + tiles, so its WHOLE masthead framing centers to
 * match. The lede is a flex column (masthead-lede.css); override its fallbacks to `center` here so
 * the eyebrow, heading, and heading-rule <hr> all center as one cluster by default. Per-selector
 * fallback → `headline: left` still overrides (the register SETS the seam; a set value beats a
 * fallback). The rule <hr> follows the cluster automatically (it's a flex child) — no per-component
 * rule handling, no bay-drift. */
section.form.stats .cell-masthead .masthead-lede { text-align:var(--headline-align, center); align-items:var(--headline-justify, center); }
section.stats h3 { padding-bottom:0.3125cqi; }
section.stats > .cell-stage > p, section.stats > .cell-stage > em { font-size:var(--fs-body); line-height:var(--lh-relaxed); padding-bottom:var(--sp-lg); color:var(--text-label); font-style:italic; display:block; text-align:var(--headline-align, center); align-self:var(--headline-justify, center); }

/* The stat strip: the top-level list laid out as a centered flex row. */
section.stats > .cell-stage > ol {
  display:flex; justify-content:center; gap:var(--sp-md);
  list-style:none; margin:0;
  /* Berth ONLY on the vertical axis: the tile shadow extends downward (all layers
   * 0 x-offset, negative spread), so horizontal berth would just steal row width
   * and shear the outer tiles of a dense 5-stat row against the stage clip. */
  padding:var(--elevation-berth) 0;
}
/* Each stat is now a card TILE (the manifest always called them tiles): a
 * bg-alt surface with a hairline + Struck elevation, so the numbers sit up off
 * the stage in both canvases. Fill unchanged across themes (light-dark() token).
 * Horizontal padding stays tight (--sp-sm) so five tiles + gaps fit the stage
 * within the pre-tile width budget; vertical padding carries the tile height. */
section.stats > .cell-stage > ol > li {
  display:flex; flex-direction:column; align-items:center; gap:0.46875cqi; text-align:center;
  background:var(--bg-alt); border:1px solid var(--border);
  border-radius:var(--radius-md); padding:var(--sp-lg) var(--sp-sm);
  box-shadow:var(--elevation-card);
}
/* The number — the lifted parent-li lead. */
section.stats > .cell-stage > ol > li > strong {
  font-family:var(--font-display); font-size:var(--fs-h1); font-weight:700;
  color:var(--accent); line-height:1; display:block;
  letter-spacing:0; text-transform:none; font-variant-numeric:tabular-nums;
}
/* The label — the nested sublist. */
section.stats > .cell-stage > ol > li > ul {
  list-style:none; padding:0; margin:0;
}
section.stats > .cell-stage > ol > li > ul > li {
  font-family:var(--font-label); font-size:var(--fs-meta); font-weight:600;
  letter-spacing:0.18em; text-transform:uppercase; color:var(--text-label);
}

/* Portrait / square (social) — stack the stat tiles vertically and let the hero
   numbers command the tall frame. A centred horizontal row crams 3–5 numbers
   small with the whole lower frame empty; stacked + enlarged (the engine's
   --stat-emphasis param, on top of --canvas-scale) reads from across a room and
   fills the canvas. `space-evenly` does the FILLING (it spreads the surplus), so
   `gap` is only a tight FLOOR: a small floor leaves the sparse 3-stat case
   luxuriously spread (surplus redistributed) yet lets the dense 4-stat case pack
   to fit instead of clipping — a big floor (was --sp-2xl) overflowed 4 numbers +
   a 2-line title at the shortest portrait (4:5). Keyed on data-orientation, so
   landscape is untouched. */
section.stats[data-orientation='portrait'] > .cell-stage > ol,
section.stats[data-orientation='square'] > .cell-stage > ol { display:flex; flex-direction:column;
  flex-direction: column; gap: var(--sp-sm); width: 100%; justify-content: space-evenly; flex: 1;
}
section.stats[data-orientation='portrait'] > .cell-stage > ol > li > strong,
section.stats[data-orientation='square'] > .cell-stage > ol > li > strong {
  font-size: calc(var(--fs-h1) * var(--stat-emphasis, 1));
}
section.stats[data-orientation='portrait'] > .cell-stage > ol > li > ul > li,
section.stats[data-orientation='square'] > .cell-stage > ol > li > ul > li {
  font-size: var(--fs-body); /* label legible under the big number (was --fs-meta) */
}
/* Box-local family reflow (2026-06-18-component-adaptive-sizing.md): square+tall+
 * strip (≤1.05) stack the numbers into a tall column and enlarge them, keyed on the
 * nearest `lattice` container so it fires on a portrait/square deck AND inside a
 * narrow nested cell. Doubled class matches the [data-orientation] reflow's
 * specificity. */
@container lattice (aspect-ratio <= 1.05) {
  section.stats.stats > .cell-stage > ol { display:flex; flex-direction:column;
    flex-direction: column; gap: var(--sp-sm); width: 100%; justify-content: space-evenly; flex: 1;
  }
  section.stats.stats > .cell-stage > ol > li > strong {
    font-size: calc(var(--fs-h1) * var(--stat-emphasis, 1));
  }
  section.stats.stats > .cell-stage > ol > li > ul > li {
    font-size: var(--fs-body);
  }
}

/* === lib/components/legal/statute-stack/statute-stack.styles.css === */
/* statute-stack — inventory.ledger.structure
 *
 * Extracted from lib/_legacy.css in Phase 4 of the destination map.
 * See lib/components/statute-stack/statute-stack.manifest.json for the component contract.
 */

/* ── STATUTE-STACK ────────────────────────────────────────────────────
 * <!-- _class: statute-stack -->
 *
 * - Federal `15 U.S.C. §6501`
 *   - Verifiable parental consent for under-13 personal data.
 *   - `In effect since 2000`
 * - State `Cal. Civ. §1798.120`
 *   - …
 *
 * Authoring contract: the top-level li carries the jurisdiction label PLUS trailing inline
 * `code` pills on the SAME line (auto-bolded together by slotLabelLift in all three
 * renderers — author writes `- Federal \`cite\``, not `- **Federal** \`cite\``). The nested
 * ul holds the body — prose obligations, and (for column cards) the status pill as the last
 * only-child <code>.
 *
 * TWO-PILL ANATOMY, placement KEYED TO CARD SHAPE (so the two pills never collide + wrap):
 *   · ROW cards (.hierarchy/.bands/.preemption — full-width): BOTH pills on the header line
 *     — citation LEFT after the label, status RIGHT. Author both codes in the header:
 *     `- Federal \`cite\` \`status\``.
 *   · COLUMN cards (the narrow 3-rail default): citation pill anchors RIGHT in the header;
 *     status drops to the card foot, BOTTOM-LEFT. Author `- Federal \`cite\`` + the status
 *     as the last body code.
 * Citation = neutral outline (an identifier, identical across cards); status = jurisdiction-
 * hued (the signal colour). A bare first-body-line `code` still renders as a hanging
 * citation chip, for decks on the legacy body-citation authoring.
 *
 * Default = three equal vertical rails. Modifiers re-ARRANGE the same cards: .hierarchy
 * (weighted-height stack — authority cascade), .bands (equal-height stack — scorecard),
 * .preemption (chevron-linked stack), .lane (markdown table — a different shape, below).
 * ──────────────────────────────────────────────────────────────────── */
section.statute-stack > .cell-stage { display:flex; flex-direction:column; }
section.statute-stack > .cell-stage > ul,
section.statute-stack > .cell-stage > ol {
  list-style:none; padding:0; margin:0;
  /* flex, not grid (flex shop §10): the default is three equal rails — a flex row
   * with `flex:1` cells reproduces `repeat(3,1fr)`. The vertical variants below flip
   * to flex-column (they shared this rule's `display:grid`, so each must now set its
   * own flex-direction). */
  display:flex; flex-direction:row;
  gap:var(--sp-md); flex:1;
}
section.statute-stack > .cell-stage > ul > li,
section.statute-stack > .cell-stage > ol > li {
  flex:1; min-width:0;
  background:var(--bg-alt);
  border:1px solid var(--border);
  border-top:3px solid var(--jur-accent, var(--accent));
  border-radius:var(--radius-md);
  padding:var(--sp-md);
  display:flex; flex-direction:column;
  gap:var(--sp-xs);
  color:var(--text-body);
  font-size:var(--fs-body);
  line-height:var(--lh-base);
  font-weight:400;
}
section.statute-stack > .cell-stage > ul > li::marker,
section.statute-stack > .cell-stage > ol > li::marker { content:''; }
/* Three-jurisdiction hue rotation. Federal = warm cobalt, State = warm
 * sienna, Local = warm slate. Cycles after three. */
section.statute-stack > .cell-stage > :is(ul, ol) > li:nth-child(3n+1) { --jur-accent:var(--cat-4-mark); }
section.statute-stack > .cell-stage > :is(ul, ol) > li:nth-child(3n+2) { --jur-accent:var(--cat-6-mark); }
section.statute-stack > .cell-stage > :is(ul, ol) > li:nth-child(3n)   { --jur-accent:var(--cat-1-mark); }
/* Jurisdiction label — eyebrow chrome (auto-bolded by slotLabelLift). The lifted
 * <strong> is the card's HEADER ROW: the label sits left, and trailing inline `code` pills
 * ride the same row. Placement is keyed to the card SHAPE (see below), because a wide row
 * has space for two header pills but a narrow column does not:
 *   · ROW cards (hierarchy/bands/preemption — full-width): citation pill LEFT (right after
 *     the label), status pill RIGHT (margin-left:auto) — both on the header line.
 *   · COLUMN cards (the 3-rail default — narrow): the lone citation pill anchors RIGHT
 *     (top-right corner); the status pill drops to the card foot (bottom-left, below) so the
 *     two never collide and wrap in the tight rail. */
section.statute-stack > .cell-stage > ul > li > strong:first-child,
section.statute-stack > .cell-stage > ol > li > strong:first-child {
  display:flex; align-items:baseline; gap:var(--sp-sm);
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.16em;
  text-transform:uppercase;
  color:var(--jur-accent, var(--accent));
}
/* Header pill chrome (shared). Neutral outline by default — the citation reads identical
 * across cards (an identifier, not a signal). */
section.statute-stack > .cell-stage > :is(ul, ol) > li > strong:first-child > code {
  display:inline-flex; align-items:center; line-height:1;
  font-family:var(--pill-font); font-size:var(--pill-fs); font-weight:var(--pill-weight);
  letter-spacing:var(--pill-tracking); text-transform:none;
  border:1px solid var(--pill-border, var(--text-muted));
  background:var(--pill-bg, var(--bg)); color:var(--pill-fg, var(--text-body));
  border-radius:var(--pill-radius); padding:var(--pill-pad-y) var(--pill-pad-x);
  white-space:nowrap;
}
/* COLUMN cards (default) — the lone citation pill anchors to the header's right corner.
 * Two-child header row (label + lone pill) → space-between pushes the pill to the right
 * edge WITHOUT a left-auto margin (auto margins sit outside the flex content box and break
 * the virtual-list height measurement). */
section.statute-stack:not(.hierarchy):not(.bands):not(.preemption):not(.lane) > .cell-stage > :is(ul, ol) > li > strong:first-child {
  justify-content:space-between;
}
/* ROW cards — the citation stays left after the label; the trailing status pill (the second
 * header code) anchors to the right edge on the same line and takes the jurisdiction hue (the
 * signal colour). A lone citation in a row card simply stays left.
 *
 * Right-anchoring is margin-free (an auto margin sits outside the flex content box and breaks
 * the virtual-list height measurement): the status pill is taken out of flow and pinned to the
 * header's right edge with absolute positioning, so the label + citation stay packed left at
 * their natural widths. (A flex:1 spacer can't be used here — the citation is a chrome-bearing
 * pill, so growing it would stretch its visible box rather than open up clean space.) */
section.statute-stack:is(.hierarchy, .bands, .preemption) > .cell-stage > :is(ul, ol) > li > strong:first-child {
  position:relative;
}
section.statute-stack:is(.hierarchy, .bands, .preemption) > .cell-stage > :is(ul, ol) > li > strong:first-child > code:last-child:not(:first-child) {
  position:absolute; right:0; top:50%; transform:translateY(-50%);
  --pill-border:var(--jur-accent, var(--accent));
  --pill-fg:var(--jur-accent, var(--accent));
}
/* Body list. */
section.statute-stack > .cell-stage > ul > li > ul,
section.statute-stack > .cell-stage > ol > li > ul,
section.statute-stack > .cell-stage > ul > li > ol,
section.statute-stack > .cell-stage > ol > li > ol {
  list-style:none; padding:0; margin:0;
  display:flex; flex-direction:column; gap:var(--sp-xs);
  flex:1;
}
section.statute-stack > .cell-stage > ul > li > :is(ul, ol) > li,
section.statute-stack > .cell-stage > ol > li > :is(ul, ol) > li {
  font-size:var(--fs-body);
  line-height:var(--lh-snug);
  color:var(--text-body);
}
section.statute-stack > .cell-stage > ul > li > :is(ul, ol) > li::marker,
section.statute-stack > .cell-stage > ol > li > :is(ul, ol) > li::marker { content:''; }
/* Citation chip — first body item, only-child <code>. Non-pill hanging
 * cite: mono, body-heading colour, no chrome. */
section.statute-stack > .cell-stage > ul > li > :is(ul, ol) > li:first-child:has(> code:only-child) > code,
section.statute-stack > .cell-stage > ol > li > :is(ul, ol) > li:first-child:has(> code:only-child) > code {
  display:block;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:600;
  color:var(--text-heading);
  background:none; border:none; padding:0;
  letter-spacing:0.02em;
}
/* COLUMN-card status pill — last body item, only-child <code> (the default's authoring puts
 * status in the body so the narrow rail keeps it OFF the header line). Same chrome as the
 * header citation but JURISDICTION-HUED (the card's signal colour); foot-anchored to the
 * BOTTOM-LEFT corner + align-self.
 * Row cards carry status in the header instead, so this body code never appears there.
 * (Swap --jur-accent for a --pass/--warn/--fail map for pass/warn/fail status semantics.)
 *
 * Bottom-anchoring is margin-free (an auto margin sits outside the flex content box and
 * breaks the virtual-list height measurement): instead of margin-top:auto on the status li,
 * the body item immediately ABOVE the status (a chrome-free prose/citation line) grows to
 * fill the rail's free space, pushing the status to the foot — the flex:1-spacer idiom. */
section.statute-stack:not(.hierarchy):not(.bands):not(.preemption):not(.lane) > .cell-stage > ul > li > :is(ul, ol) > li:has(+ li:last-child > code:only-child),
section.statute-stack:not(.hierarchy):not(.bands):not(.preemption):not(.lane) > .cell-stage > ol > li > :is(ul, ol) > li:has(+ li:last-child > code:only-child) {
  flex:1 1 auto;
}
section.statute-stack > .cell-stage > ul > li > :is(ul, ol) > li:last-child:has(> code:only-child) > code,
section.statute-stack > .cell-stage > ol > li > :is(ul, ol) > li:last-child:has(> code:only-child) > code {
  display:inline-flex; align-items:center; line-height:1;
  font-family:var(--pill-font); font-size:var(--pill-fs); font-weight:var(--pill-weight);
  letter-spacing:var(--pill-tracking); text-transform:none;
  padding:var(--pill-pad-y) var(--pill-pad-x);
  border-radius:var(--pill-radius);
  border:1px solid var(--jur-accent, var(--accent));
  background:var(--pill-bg, var(--bg));
  color:var(--jur-accent, var(--accent));
  align-self:flex-start;
  white-space:nowrap;
}

/* .hierarchy — the shared jurisdiction card, stacked full-width with WEIGHTED heights
 * (Federal tall, State mid, Local short) so the cascade of authority reads top-to-bottom.
 * Cards inherit the base anatomy (label+citation header, gloss, foot status) — only the
 * arrangement differs. flex mirror of `grid-auto-rows:1.5fr 1fr 0.7fr`. */
section.statute-stack.hierarchy > .cell-stage > ul,
section.statute-stack.hierarchy > .cell-stage > ol {
  flex-direction:column;
}
section.statute-stack.hierarchy > .cell-stage > :is(ul, ol) > li:nth-child(1) { flex:1.5; }
section.statute-stack.hierarchy > .cell-stage > :is(ul, ol) > li:nth-child(2) { flex:1; }
section.statute-stack.hierarchy > .cell-stage > :is(ul, ol) > li:nth-child(3) { flex:0.7; }
section.statute-stack.hierarchy > .cell-stage > ul > li,
section.statute-stack.hierarchy > .cell-stage > ol > li {
  border-top:1px solid var(--border);
  border-left:4px solid var(--jur-accent, var(--accent));
}

/* .bands — the shared jurisdiction card, stacked full-width with EQUAL heights: an
 * at-a-glance scorecard. Cards inherit the base anatomy; the container just stacks them
 * (base `flex:1` → equal rows in a column). flex mirror of `grid-auto-rows:1fr`. */
section.statute-stack.bands > .cell-stage > ul,
section.statute-stack.bands > .cell-stage > ol {
  flex-direction:column;
}
section.statute-stack.bands > .cell-stage > ul > li,
section.statute-stack.bands > .cell-stage > ol > li {
  border-top:1px solid var(--border);
  border-left:4px solid var(--jur-accent, var(--accent));
}

/* .preemption — vertical stack with arrows between cards. */
section.statute-stack.preemption > .cell-stage > ul,
section.statute-stack.preemption > .cell-stage > ol {
  /* content-height cards stacked + centred — flex mirror of `grid-auto-rows:auto;
   * align-content:center`. */
  flex-direction:column;
  /* inter-card spacing as a flex gap (was margin-bottom on each card) — measurable,
   * inside the flex content box; the chevron ::after still centres in this gap band. */
  gap:var(--sp-md);
  justify-content:center;
}
section.statute-stack.preemption > .cell-stage > ul > li,
section.statute-stack.preemption > .cell-stage > ol > li {
  flex:0 0 auto;
  border:1px solid var(--border);
  border-left:4px solid var(--jur-accent, var(--accent));
  border-top:1px solid var(--border);
  position:relative;
}
section.statute-stack.preemption > .cell-stage > :is(ul, ol) > li:not(:last-child)::after {
  /* `❯` rotated down — the same chevron the compare-prose connector uses, for one
   * connector vocabulary across the deck. It sits CENTRED in its own clean band (the
   * inter-card gap), not floated over the next card's edge behind a `var(--bg)` mask
   * chip. */
  content:'❯';
  position:absolute;
  left:50%; top:100%;
  transform:translate(-50%, calc(var(--sp-md) / 2 - 50%)) rotate(90deg);
  font-size:var(--fs-h3);
  font-weight:300;
  color:var(--accent);
  line-height:1;
}

/* Stacked ROW variants (hierarchy / bands / preemption) — both pills ride the header line
 * (citation left, status right) and the gloss sits below, so each card is just two compact
 * lines. Tighter padding + a centred content block keep the card balanced in its band
 * (especially hierarchy's tall Federal card) instead of stranding the two lines at the top. */
section.statute-stack:is(.hierarchy, .bands, .preemption) > .cell-stage > :is(ul, ol) > li {
  padding:var(--sp-sm) var(--sp-md);
  gap:var(--sp-2xs);
  justify-content:center;
}
section.statute-stack:is(.hierarchy, .bands, .preemption) > .cell-stage > :is(ul, ol) > li > :is(ul, ol) {
  flex:0 1 auto;
}
section.statute-stack:is(.hierarchy, .bands) > .cell-stage > :is(ul, ol) {
  gap:var(--sp-sm);
}

/* .lane — markdown table; columns are aspects (cite, obligation, status).
 * Authoring example:
 *   | Jurisdiction | Citation              | Headline obligation       | Status      |
 *   | ------------ | --------------------- | ------------------------- | ----------- |
 *   | Federal      | 15 U.S.C. §6501       | Parental consent <13 data | In effect   |
 *   | State        | Cal. Civ. Code §1798  | Notice + opt-out + DSAR   | Enforced    |
 *   | Local        | NYC §22-1201          | Annual AEDT bias audit    | Effective   |
 */
section.statute-stack.lane > .cell-stage > ul,
section.statute-stack.lane > .cell-stage > ol { display:none; }
section.statute-stack.lane table {
  width:100%; border-collapse:collapse;
  flex:1; font-size:var(--fs-body);
  table-layout:auto;
}
section.statute-stack.lane thead tr { background:var(--spectrum-structure) bottom / 100% 2px no-repeat; }
section.statute-stack.lane thead th {
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.10em;
  text-transform:uppercase;
  color:var(--text-label);
  padding:0.625cqi var(--sp-sm);
  text-align:left;
}
section.statute-stack.lane td {
  padding:var(--sp-sm) var(--sp-sm);
  border-bottom:1px solid var(--border);
  vertical-align:top;
  color:var(--text-body);
  line-height:var(--lh-snug);
}
section.statute-stack.lane td:first-child {
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  font-weight:700;
  letter-spacing:0.10em;
  text-transform:uppercase;
  color:var(--lane-jur, var(--accent));
  white-space:nowrap;
}
section.statute-stack.lane td:nth-child(2) {
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  color:var(--text-heading);
  white-space:nowrap;
}
section.statute-stack.lane tbody tr:nth-child(3n+1) { --lane-jur:var(--cat-4-mark); }
section.statute-stack.lane tbody tr:nth-child(3n+2) { --lane-jur:var(--cat-6-mark); }
section.statute-stack.lane tbody tr:nth-child(3n)   { --lane-jur:var(--cat-1-mark); }
section.statute-stack.lane tbody tr > td:first-child {
  border-left:3px solid var(--lane-jur, var(--accent));
  padding-left:var(--sp-md);
}
section.statute-stack.lane td:last-child {
  text-align:right;
  font-family:var(--font-mono);
  font-size:var(--fs-meta);
  letter-spacing:0.04em;
  color:var(--text-secondary);
  white-space:nowrap;
}

/* ── Box-local family reflow (2026-06-20-native-to-reflow-feasibility.md, Batch
   A1). Wide keeps the three-rail grid; square/tall/strip collapse the DEFAULT
   layout to a single full-width column of jurisdiction cards, content-height rows
   distributed to fill. Scoped off the named variants (hierarchy/bands/preemption/
   lane), which already author their own single-column / table portrait shape.
   Doubled class reaches (0,2,N) to beat the base grid on specificity — the role
   the old [data-orientation] stamp played; keyed on the nearest `lattice`
   container's aspect so it fires on a portrait deck AND a narrow nested cell. */
@container lattice (aspect-ratio <= 1.05) {
  section.statute-stack.statute-stack:not(.hierarchy):not(.bands):not(.preemption):not(.lane) > .cell-stage > ul,
  section.statute-stack.statute-stack:not(.hierarchy):not(.bands):not(.preemption):not(.lane) > .cell-stage > ol {
    /* portrait → single column of content-height cards, evenly distributed (flex mirror
       of `grid-auto-rows:auto; align-content:space-evenly`). */
    flex-direction: column;
    justify-content: space-evenly;
  }
  section.statute-stack.statute-stack:not(.hierarchy):not(.bands):not(.preemption):not(.lane) > .cell-stage > ul > li,
  section.statute-stack.statute-stack:not(.hierarchy):not(.bands):not(.preemption):not(.lane) > .cell-stage > ol > li {
    flex: 0 0 auto;
  }
  /* Header-pill authoring already carries the citation + status on the label row, so the
     portrait card needs no pill-lift — just breathing room between that row and the gloss. */
  section.statute-stack:not(.hierarchy):not(.bands):not(.preemption):not(.lane) > .cell-stage > :is(ul, ol) > li > :is(ul, ol) {
    padding-top:var(--sp-md);
  }
}


/* ── Struck elevation (base.tokens.css --elevation-card) ── lift the cards; vertical
 * berth (padding-block, never margin — #20) so the stage's overflow:clip doesn't
 * shear the shadow. Shadow has no horizontal extent, so no horizontal berth. */
section.statute-stack > .cell-stage > ol > li {
  box-shadow: var(--elevation-card);
}
section.statute-stack > .cell-stage {
  padding-block: var(--elevation-berth);
}

/* === lib/components/chart/timeline-list/timeline-list.styles.css === */
/* timeline-list — extracted from lib/_legacy.css (batch 9).
 * See lib/components/timeline-list/timeline-list.manifest.json for the component contract.
 */

/* ── TIMELINE-LIST · horizontal ──
 * Ordered list rendered as a left-to-right spine with dots at each item.
 * Date pill sits above the dot; title + status pill + body sit below.
 * Items distribute evenly along the spine. */
:is(section.timeline-list, figure.timeline-list).chart-frame .chart-body {
  /* Inherit the shared .chart-body width so the surface panel matches every
   * other chart's size — don't re-assert width:100% (it spanned edge-to-edge,
   * wider than the rest). The timeline-spine already caps at max-width. */
  padding: var(--sp-xl) var(--sp-2xl) var(--sp-lg);
  align-items: center;
  justify-content: center;
}
:is(section.timeline-list, figure.timeline-list) .timeline-spine {
  position: relative;
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
  align-items: start;
  width: 100%;
  max-width: 85.9375cqi;
  padding: 0.9375cqi 0 0;  /* room for the dot to "sit on" the spine line */
}
/* The horizontal spine line runs through the centre of each dot. The dot
 * is 1.09375cqi tall with 3px border on each side — its centre is 0.546875cqi
 * from the top of timeline-item content. Spine padding-top is 0.9375cqi so
 * the dot appears at y=0.9375cqi, centre at y≈1.484375cqi; line is at same. */
:is(section.timeline-list, figure.timeline-list) .timeline-spine::before {
  content: '';
  position: absolute;
  top: 1.484375cqi;
  left: 6%;
  right: 6%;
  height: 2px;  /* sanctioned: timeline spine rule — a hairline, resolution-stable by design */
  background: linear-gradient(
    to right,
    color-mix(in oklab, var(--accent) 12%, transparent) 0%,
    color-mix(in oklab, var(--accent) 55%, transparent) 12%,
    color-mix(in oklab, var(--accent) 55%, transparent) 88%,
    color-mix(in oklab, var(--accent) 12%, transparent) 100%
  );
  transform: translateY(-1px);
  z-index: 0;
}
:is(section.timeline-list, figure.timeline-list) .timeline-item {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 0 var(--sp-sm);
  z-index: 1;
}
/* The dot is a fixed circle drawn on a ::before so the element box itself can
 * carry the dot→pill spacing as padding-bottom (a margin would collapse outside
 * the flex content box and break virtual-list scrollHeight). The visible ring
 * keeps its exact 1.09375cqi size + position, so the spine-line math (centre at
 * 0.546875cqi from the item content top) is unchanged. */
:is(section.timeline-list, figure.timeline-list) .timeline-dot {
  position: relative;
  /* Footprint = the original ring's border-box (content 1.09375cqi + 3px border
   * each side). The ring is now drawn on ::before so this box can carry the
   * dot→pill spacing as padding-bottom (margins collapse outside the flex box). */
  width: calc(1.09375cqi + 6px);  /* sanctioned: 1.09375cqi ring content + 3px stroke ×2 — exact ring footprint so the box can carry the dot→pill padding without distorting the ring */
  aspect-ratio: 1;
  box-sizing: content-box;
  padding-bottom: var(--sp-sm);   /* was margin-bottom: var(--sp-sm) — dot→pill gap */
  --timeline-dot-ink: var(--chart-cat-1-ink); /* per-stage colour, cycled below */
  flex: 0 0 auto;
}
:is(section.timeline-list, figure.timeline-list) .timeline-dot::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;   /* fills the dot's ring footprint (left+right:0); square via aspect-ratio — no px */
  aspect-ratio: 1;
  box-sizing: border-box;
  border-radius: 50%;
  background: var(--bg);             /* hollow — centre matches the slide */
  border: 3px solid var(--timeline-dot-ink);
  box-shadow: 0 0 0 4px var(--bg);
}
/* Each stage's dot rides the vivid catN spectrum (hollow ring, stroke only),
 * matching pie / kanban / word-cloud — categorical colour for sequential
 * stages. Six-rotation, like the other categorical members. The spine and
 * date pills stay accent so the row still reads as one timeline. */
:is(section.timeline-list, figure.timeline-list) .timeline-item:nth-child(6n+1) .timeline-dot { --timeline-dot-ink: var(--chart-cat-1-ink); }
:is(section.timeline-list, figure.timeline-list) .timeline-item:nth-child(6n+2) .timeline-dot { --timeline-dot-ink: var(--chart-cat-2-ink); }
:is(section.timeline-list, figure.timeline-list) .timeline-item:nth-child(6n+3) .timeline-dot { --timeline-dot-ink: var(--chart-cat-3-ink); }
:is(section.timeline-list, figure.timeline-list) .timeline-item:nth-child(6n+4) .timeline-dot { --timeline-dot-ink: var(--chart-cat-4-ink); }
:is(section.timeline-list, figure.timeline-list) .timeline-item:nth-child(6n+5) .timeline-dot { --timeline-dot-ink: var(--chart-cat-5-ink); }
:is(section.timeline-list, figure.timeline-list) .timeline-item:nth-child(6n)   .timeline-dot { --timeline-dot-ink: var(--chart-cat-6-ink); }
:is(section.timeline-list, figure.timeline-list) .timeline-pill {
  display: inline-flex;
  align-items: center;
  height: 1.875cqi;
  padding: 0 0.78125cqi;
  /* pill→title spacing moved to .timeline-title's padding-top (the pill is a
   * filled chip — self-padding would grow its outline; a margin would collapse
   * outside the flex content box). */
  border-radius: 0.9375cqi;
  background: var(--bg);
  border: var(--chart-hairline) solid color-mix(in oklab, var(--accent) 40%, var(--border));
  color: var(--accent);
  font-family: var(--font-mono);
  font-size: var(--fs-meta);
  font-weight: 600;
  letter-spacing: 0.04em;
  white-space: nowrap;
  flex: 0 0 auto;
}
:is(section.timeline-list, figure.timeline-list) .timeline-pill--empty {
  visibility: hidden;
}
:is(section.timeline-list, figure.timeline-list) .timeline-title {
  font-size: var(--fs-body);
  font-weight: 600;
  color: var(--text-heading);
  text-align: center;
  /* padding-top = the pill→title gap (was the pill's margin-bottom: var(--sp-sm));
   * padding-bottom = the title→status/body gap (was margin-bottom: 0.3125cqi).
   * The title has no fill, so padding is fully measurable and margin-free. */
  padding-top: var(--sp-sm);
  padding-bottom: 0.3125cqi;
  line-height: var(--lh-tight);
  max-width: 17.1875cqi;
}
:is(section.timeline-list, figure.timeline-list) .timeline-body {
  font-size: var(--fs-meta);
  color: var(--text-secondary);
  text-align: center;
  line-height: var(--lh-relaxed);
  max-width: 17.1875cqi;
}
/* status→body gap (was the .chart-status margin-bottom: var(--sp-xs)). Scoped to
 * an immediately-preceding status so a body without a status doesn't inherit the
 * gap — the status pill is filled, so the spacing rides the body's padding-top. */
:is(section.timeline-list, figure.timeline-list) .chart-status + .timeline-body {
  padding-top: var(--sp-xs);
}

/* ── Box-local RESTRUCTURE (tall + strip, ≤0.9): the left-to-right spine becomes
 * a real vertical timeline — items stack down the page, each dot rides a left
 * rail, the date/title/body fill the width beside it. Keyed on the nearest
 * `lattice` container (the section), so it fires on a portrait deck AND inside a
 * narrow nested cell. See engineering/decisions/2026-06-19-chart-adaptive-sizing.md. */
@container lattice (aspect-ratio <= 0.9) {
  :is(section.timeline-list, figure.timeline-list).chart-frame .chart-body {
    align-items: stretch;
    justify-content: center;
    padding: var(--sp-lg) var(--sp-xl);
  }
  :is(section.timeline-list, figure.timeline-list) .timeline-spine {
    grid-auto-flow: row;
    grid-template-columns: 1fr;
    grid-auto-columns: auto;
    max-width: none;
    width: 100%;
    height: 100%;
    row-gap: var(--sp-md);
    padding: var(--sp-xs) 0;
    align-content: space-evenly;
  }
  /* The spine line runs vertically through the dots on the left rail. */
  :is(section.timeline-list, figure.timeline-list) .timeline-spine::before {
    top: 1.5cqi;
    bottom: 1.5cqi;
    left: 0.546875cqi;
    right: auto;
    width: 2px;  /* sanctioned: timeline spine rule — a hairline, resolution-stable by design */
    height: auto;
    background: linear-gradient(
      to bottom,
      color-mix(in oklab, var(--accent) 12%, transparent) 0%,
      color-mix(in oklab, var(--accent) 55%, transparent) 8%,
      color-mix(in oklab, var(--accent) 55%, transparent) 92%,
      color-mix(in oklab, var(--accent) 12%, transparent) 100%
    );
    transform: translateX(-1px);
  }
  :is(section.timeline-list, figure.timeline-list) .timeline-item {
    display: grid;
    grid-template-columns: auto 1fr;
    column-gap: var(--sp-md);
    align-items: start;
    padding: 0;
  }
  /* Dot anchors the left rail; everything else fills the right column. */
  :is(section.timeline-list, figure.timeline-list) .timeline-item > * {
    grid-column: 2;
    text-align: left;
    align-self: start;
  }
  :is(section.timeline-list, figure.timeline-list) .timeline-dot {
    grid-column: 1;
    grid-row: 1;
    /* Portrait: the dot rides its own left-rail grid cell, so it needs no
     * dot→pill padding-bottom (override the base) — just a top nudge to align
     * with the row (was margin: 0.234375cqi 0 0 0; padding shifts the ::before
     * ring down by the same amount). */
    padding: 0.234375cqi 0 0 0;
  }
  /* Chips hug their content; the title/body keep the default stretch so prose
   * fills the column and wraps. */
  :is(section.timeline-list, figure.timeline-list) .timeline-dot,
  :is(section.timeline-list, figure.timeline-list) .timeline-pill,
  :is(section.timeline-list, figure.timeline-list) .timeline-item .chart-status { justify-self: start; }
  /* Portrait pill→title gap tightens to var(--sp-2xs) (was the pill's
   * margin-bottom: var(--sp-2xs)); it rides the title's padding-top, overriding
   * the landscape var(--sp-sm). The pill is filled, so the spacing can't sit on
   * the pill itself. */
  :is(section.timeline-list, figure.timeline-list) .timeline-title { padding-top: var(--sp-2xs); }
  :is(section.timeline-list, figure.timeline-list) .timeline-title,
  :is(section.timeline-list, figure.timeline-list) .timeline-body { max-width: none; }
}

/* === lib/components/anchor/title/title.styles.css === */
/* title — anchor.bookend.title
 *
 * Dark canvas, centered. Inline-code paragraph after h1 becomes the
 * eyebrow (overrides the general subtitle rule).
 *
 * See lib/components/title/title.manifest.json for the component contract.
 */

/* align-items (the flex cross-axis = horizontal, this is a column) + the h1/p text-align read
 * the headline-alignment seam (`headline:` register). `auto`/no register → the fallback `center`
 * applies, byte-identical to the centered title bookend. head-left/right re-anchor the whole
 * cluster (heading, eyebrow, hr, dek) as one. */
section.title { justify-content:center; align-items:var(--headline-justify, center); background:var(--surface-inverse); }
section.title { border-top: none; }
section.title h1 { font-size:var(--fs-h1); color:var(--text-display); padding-bottom:var(--sp-xs); text-align:var(--headline-align, center); }
section.title hr { background:var(--accent); height:1px; width:64px; margin:0; }
section.title p  { color:var(--on-dark-secondary); font-size:var(--fs-message); font-weight:300; margin:0; padding-top:0; text-align:var(--headline-align, center); }
/* Title layout: inline-code after h1 = eyebrow, rendered visually above h1 via flex order.
 * Overrides the general subtitle rule (italic, body font) for section.title only. */
section.title h1 + p:has(> code:only-child) { order:-1; margin:0; padding-top:0; padding-bottom:0.3125cqi; }
section.title h1 + p:has(> code:only-child) > code {
  font-family: var(--font-mono);
  font-size: var(--fs-meta);
  font-style: normal;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--on-dark-secondary);
  background: none;
  border: none;
  padding: 0;
  border-radius: 0;
}

/* === lib/components/comparison/verdict-grid/verdict-grid.styles.css === */
/* verdict-grid — extracted from lib/_legacy.css (batch 5).
 * See lib/components/verdict-grid/verdict-grid.manifest.json for the component contract.
 */

/* ── VERDICT-GRID ──
 * ## heading  then 4× pairs: ### tool-name  p badges+body
 *
 * The badge is the layout's chrome (mono pill). Its leading ::before
 * paints the universal state-token disc and ::after masks the per-shape
 * mark on top — check / dash / x / slash, picked by state-full /
 * state-half / state-empty / state-slashed. Replaces the prior Unicode
 * ✓/–/✗ glyphs (font-dependent) with a font-independent disc+mask recipe;
 * the SHAPE carries the meaning independently of colour. */
.badge { position:relative; display:inline-flex; align-items:center; justify-content:center; text-align:center; line-height:1; gap:6px; font-family:var(--pill-font); font-size:var(--pill-fs); font-weight:var(--pill-weight); letter-spacing:var(--pill-tracking); border-radius:var(--pill-radius); padding:var(--pill-pad-y) var(--pill-pad-x); white-space:nowrap; background:var(--bg); border:1px solid var(--text-muted); color:var(--text-body); }
.badge.pass { --state-color:var(--pass); }
.badge.warn { --state-color:var(--warn); }
.badge.fail { --state-color:var(--fail); }
.badge.skip { --state-color:var(--text-muted); color:var(--text-muted); text-decoration:line-through; text-decoration-color:color-mix(in srgb, var(--text-muted) 60%, transparent); }
/* Disc (leading ::before, in flex flow) + mark (::after, overlaid on the
 * disc). Colours mixed here from --state-color + the scalar knobs; disc
 * style follows the default (Ringed Solid) or a .checks-* variant. Mirror
 * recipe: checklist.styles.css, obligation-matrix.styles.css. */
.badge::before {
  content:'';
  display:inline-block;
  flex:none;
  width:calc(0.95em * var(--state-disc-scale)); height:calc(0.95em * var(--state-disc-scale));
  border-radius:50%;
  box-sizing:border-box;
  background:color-mix(in srgb, var(--state-color, var(--text-muted)) var(--state-fill-pct), transparent);
  box-shadow:
    0 0 0 var(--state-ring-outer-w) color-mix(in srgb, var(--state-color, var(--text-muted)) var(--state-ring-mix), black),
    inset 0 0 0 var(--state-ring-inner-w) var(--state-color, var(--text-muted));
}
/* Mark overlay — anchored to the disc, which sits at the badge's left pad. */
.badge::after {
  content:'';
  position:absolute;
  left:var(--pill-pad-x); top:50%; transform:translateY(-50%);
  width:calc(0.95em * var(--state-disc-scale)); height:calc(0.95em * var(--state-disc-scale));
  background-color:color-mix(in srgb, var(--state-color, var(--text-muted)) var(--state-mark-pct), var(--bg));
  -webkit-mask:var(--state-mark) center / 100% 100% no-repeat;
          mask:var(--state-mark) center / 100% 100% no-repeat;
}


/* ── VERDICT-GRID ────────────────────────────────────────────────────────────
 * Nested-list format: ul > li(title + ul(badge items + last = body))
 * All selectors use > from section root to prevent outer card styles from
 * cascading into the nested badge/body items. */
/* The stage is a flex column so the grid `ul` (flex:1) fills the bounded stage
 * (flex cell-tree §6); the section itself carried no display, so the codemod left
 * the cell without one. */
section.verdict-grid > .cell-stage { display:flex; flex-direction:column; }
section.verdict-grid > .cell-stage > ul {
  /* flex mirror of `grid-template-columns:1fr 1fr; grid-auto-rows:minmax(0,1fr)`: a 2-col
   * tiling (matrix-2x2 idiom — `width` on the cells, not a flex-shorthand calc basis) whose
   * wrapped rows stretch to share the bounded stage (align-content:stretch), so a dense grid
   * shrinks to fit instead of clipping the last row. */
  display:flex; flex-wrap:wrap; align-content:stretch;
  gap:var(--sp-sm); flex:1; list-style:none; padding:0; margin:0;
}
section.verdict-grid > .cell-stage > ul > li {
  box-sizing:border-box;
  width:calc(50% - var(--sp-sm) / 2);
  min-height:0;
  background:var(--bg-alt); border:1px solid var(--border);
  border-radius:var(--radius-md); padding:1.40625cqi 1.71875cqi;
  display:flex; flex-direction:column; gap:var(--sp-xs);
  font-size:var(--fs-body); font-weight:700; color:var(--text-heading);
}
section.verdict-grid > .cell-stage > ul > li:last-child { background:var(--accent-soft); border-color:var(--on-accent-soft); color:var(--on-accent-soft); position:relative; overflow:hidden; padding-right:3.125cqi; }
section.verdict-grid > .cell-stage > ul > li:last-child::after {
  content:'✧'; position:absolute; top:0.625cqi; right:0.625cqi;
  font-size:2.75cqi; line-height:1; color:var(--on-accent-soft); opacity:0.35; /* cqi-ok: decorative ✧ glyph, 0.35 opacity — not read */
  font-family:var(--font-body); font-weight:400; letter-spacing:0;
  pointer-events:none;
}
section.verdict-grid > .cell-stage > ul > li:last-child:nth-child(odd) { width:100%; }
section.verdict-grid > .cell-stage > ul > li > strong { font-weight:inherit; color:inherit; }
/* Inner ul = badge row */
section.verdict-grid > .cell-stage > ul > li > ul { display:flex; flex-wrap:wrap; gap:0.390625cqi; list-style:none; padding:0; margin:0; align-content:flex-start; }
/* Badge items (all but last nested li) — neutral pill */
section.verdict-grid > .cell-stage > ul > li > ul > li:not(:last-child) { display:inline-flex; align-items:center; justify-content:center; text-align:center; line-height:1; font-family:var(--pill-font); font-size:var(--pill-fs); font-weight:var(--pill-weight); letter-spacing:var(--pill-tracking); border-radius:var(--pill-radius); padding:var(--pill-pad-y) var(--pill-pad-x); white-space:nowrap; background:var(--bg); border:1px solid var(--text-muted); color:var(--text-body); }
/* When emitter/runtime ran: strip neutral pill so .badge span styles through cleanly */
section.verdict-grid > .cell-stage > ul > li > ul > li:not(:last-child):has(.badge) { background:none; border:none; padding:0; }
/* Body text (last nested li) — reset inherited card-title styles */
section.verdict-grid > .cell-stage > ul > li > ul > li:last-child { width:100%; font-size:var(--fs-body-compact); font-weight:400; color:var(--text-body); line-height:var(--lh-snug); background:none; border:none; border-radius:0; padding:0; display:block; }
section.verdict-grid > .cell-stage > ul > li:last-child > ul > li:last-child { padding-right:3.125cqi; }
section.verdict-grid > .cell-stage > ul > li > ul > li::before { display:none; content:none; }

/* Hardening: element siblings of <strong> in a card li don't inherit
 * the parent's font-weight:700. Covers cases like `<strong>Title.</strong>
 * <em>italic body</em>`. Text-node siblings still inherit (CSS can't
 * target text nodes); the manifest validator catches that case at
 * lint time. See CARD_STYLE_LAYOUTS in lib/components/index.js. */
section.verdict-grid :is(ul,ol) > li > strong ~ * { font-weight: 400; }

/* ── Portrait / square reflow (social/mobile @sizes). Keyed on the deck-wide
 * data-orientation stamp (lib/engine/slides.js); landscape untouched. See
 * 2026-06-16-social-mobile-portrait-sizes.md (phase 3). */
section.verdict-grid[data-orientation="portrait"] > .cell-stage > ul {
  flex-direction: column;
}
section.verdict-grid[data-orientation="portrait"] > .cell-stage > ul > li {
  width: auto; flex: 1; min-height: 0;
}
/* fill:center — with few cards the 1fr rows stretch tall; top-anchored content
 * then leaves dead space at the card bottom ("a grid of boxes", forms.md §6). Centre
 * the content block so the full-height cards read as a board deck. Portrait only;
 * the wide 2×2 is untouched. */
section.verdict-grid[data-orientation="portrait"] > .cell-stage > ul > li { justify-content: center; }
/* Box-local family reflow (2026-06-18-component-adaptive-sizing.md): tall+strip
 * (≤0.9) collapse the verdict grid to one column, keyed on the nearest `lattice`
 * container so it fires on a portrait deck AND inside a narrow nested cell. Doubled
 * class reaches (0,2,2) to match the [data-orientation] reflow it mirrors. */
@container lattice (aspect-ratio <= 0.9) {
  section.verdict-grid.verdict-grid > .cell-stage > ul {
    flex-direction: column;
  }
  section.verdict-grid.verdict-grid > .cell-stage > ul > li { width: auto; flex: 1; min-height: 0; justify-content: center; }
}

/* ── Struck elevation (base.tokens.css --elevation-card) ── lift the cards; vertical
 * berth (padding-block, never margin — #20) so the stage's overflow:clip doesn't
 * shear the shadow. Shadow has no horizontal extent, so no horizontal berth. */
section.verdict-grid > .cell-stage > ul > li {
  box-shadow: var(--elevation-card);
}
section.verdict-grid > .cell-stage {
  padding-block: var(--elevation-berth);
}

/* === lib/components/imagery/video/video.styles.css === */
/* video.styles.css — the `video` component: a poster that links to the clip, a
 * play badge, the provider label, and a scannable QR beside it. Injected by the
 * video transform as
 *   <figure class="video-embed"><a class="video-poster">…</a>
 *     <div class="video-aside"><div class="video-qr">…</div><figcaption/></div></figure>
 *
 * Palette-blind: layout color goes through tokens. The two FIXED-contrast
 * surfaces — the play badge and the QR chip — use the same --qr-paper/--qr-ink
 * token-with-fallback the QR variants use, so the code scans and the badge reads
 * on any poster (#3-exempt). Spacing is gap/padding only (HARD RULE #20). */

section.video .video-embed {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--sp-lg, 2rem);
  width: 100%;
  /* No fixed height: the poster is capped by WIDTH (cqi) and its height follows
   * via aspect-ratio, so the figure is a natural-flow block the frame's content
   * cell measures correctly (a cqh height sized against the whole section
   * over-reports to the cell's clip probe). */
}

/* Poster — a 16:9 tile carrying the author/oEmbed still as a cover background
 * (set inline, like lib/core/bg-image.js). It is an <a>, so it's a live link in
 * HTML and a clickable link annotation in the PDF. */
section.video .video-poster {
  position: relative;
  display: block;
  width: 100%;
  max-width: 46cqi;
  height: auto;
  aspect-ratio: 16 / 9;
  flex: 0 1 auto;
  min-width: 0;
  border-radius: var(--radius-lg, 0.75rem);
  background: var(--qr-ink, #14140f) center / cover no-repeat;
  box-shadow: 0 12px 40px rgba(10, 22, 40, 0.28);
  overflow: hidden;
  text-decoration: none;
}
/* No still available → a dark, video-like placeholder (fixed --qr-ink blend, so
 * it reads as a poster on ANY theme, light or dark) rather than a blank box. */
section.video .video-poster.is-placeholder {
  background:
    linear-gradient(135deg,
      color-mix(in srgb, var(--qr-ink, #14140f) 78%, var(--accent)),
      color-mix(in srgb, var(--qr-ink, #14140f) 94%, var(--accent)));
}

/* Play badge — a fixed-contrast disc + a CSS triangle, centered on the poster. */
section.video .video-play {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 4.5rem;
  height: 4.5rem;
  border-radius: 50%;
  background: var(--qr-paper, #ffffff);
  box-shadow: 0 6px 20px rgba(10, 22, 40, 0.35);
}
section.video .video-play::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  /* right-pointing triangle, optically nudged off-center */
  border-style: solid;
  border-width: 0.85rem 0 0.85rem 1.4rem;
  border-color: transparent transparent transparent var(--qr-ink, #14140f);
  transform: translate(-42%, -50%);
}

/* Provider label — a chip on the poster's lower-left. */
section.video .video-provider {
  position: absolute;
  left: var(--sp-sm, 0.75rem);
  bottom: var(--sp-sm, 0.75rem);
  padding: 0.25em 0.7em;
  border-radius: 999px;
  font-size: var(--fs-meta, 0.8rem);
  font-weight: 600;
  color: var(--qr-ink, #14140f);
  background: color-mix(in srgb, var(--qr-paper, #ffffff) 90%, transparent);
}

/* Aside — the QR + caption column beside the poster. */
section.video .video-aside {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--sp-sm, 0.75rem);
  max-width: 13rem;
}
section.video .video-qr {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--sp-xs, 0.5rem);
}
section.video .video-qr .qr-tile {
  width: 8rem;
  padding: 0.6em;
  background: var(--qr-paper, #ffffff);
  color: var(--qr-ink, #14140f);
  border-radius: 0.6em;
  box-shadow: 0 2px 14px rgba(10, 22, 40, 0.22);
}
section.video .video-qr .qr-tile svg { display: block; width: 100%; height: auto; }
section.video .video-qr-hint {
  font-size: var(--fs-meta, 0.8rem);
  font-weight: 500;
  color: var(--text-muted);
}
section.video .video-embed figcaption {
  font-size: var(--fs-body-compact);
  color: var(--text-heading);
  text-align: center;
  line-height: 1.3;
}

/* ═══════════════════════════════════════════════════════════════════════════
 * COMPOSITIONS — each a candidate "killer" layout; `qr` is an opt-in modifier
 * (the transform emits the QR only under `.qr`, so these mostly reveal/place it).
 * ═══════════════════════════════════════════════════════════════════════════ */

/* ── companion — claim/lead LEFT, poster RIGHT (this kernel splits them). ───── */
section.video.companion {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: var(--sp-xl, 3rem);
}
section.video.companion .video-lead {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--sp-sm, 1rem);
}
section.video.companion .video-lead::before {
  content: "";
  width: 2.5rem;
  height: 3px;
  border-radius: 999px;
  background: var(--accent);
}
section.video.companion .video-lead h2 {
  font-size: var(--fs-h2);
  font-weight: 800;
  line-height: var(--lh-tight, 1.1);
  color: var(--text-heading);
  padding: 0;
  margin: 0;
}
section.video.companion .video-lead p {
  font-size: var(--fs-message);
  line-height: 1.4;
  color: var(--text-body);
  max-width: 32ch;
  padding: 0;
  margin: 0;
}
section.video.companion .video-embed {
  flex: 1.15 1 0;
  min-width: 0;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--sp-lg, 2rem);
}
section.video.companion .video-poster { max-width: 46cqi; }
section.video.companion .video-aside { align-items: center; text-align: center; }
section.video.companion.qr .video-poster { max-width: 40cqi; }
/* With the QR on, a hairline rule (poster-width, centered) + a symmetric gap
 * separates the poster from the scannable code, and both stay centered on the
 * column's axis — a pleasing, deliberate channel, not a cramped stack. */
section.video.companion.qr .video-embed { gap: var(--sp-xl, 3rem); }
section.video.companion.qr .video-aside {
  width: 40cqi;
  max-width: 100%;
  padding-top: var(--sp-xl, 3rem);
  border-top: 1px solid var(--border);
}
section.video.companion .video-embed figcaption {
  font-size: var(--fs-meta);
  color: var(--text-muted);
  line-height: 1.25;
}

/* ── gallery — contained-on-matte museum exhibit (CSS override to contain). ─── */
section.video.gallery {
  display: flex;
  flex-direction: column;
  align-items: center;
