/* mark-chevron — 3 right-pointing chevrons, bottom-left corner.
 * Default at-bl. */
section.mark-chevron::before {
  content: '';
  position: absolute;
  bottom: 6.3cqi; left: 2.4cqi;
  width: 3.9cqi; height: 1.4cqi;
  pointer-events: none;
  background: color-mix(in srgb, var(--accent) 28%, transparent);
  --m: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='31 622 50 18'><polyline points='34,625 42,631 34,637' fill='none' stroke='white' stroke-width='1.5' stroke-opacity='1'/><polyline points='52,625 60,631 52,637' fill='none' stroke='white' stroke-width='1.5' stroke-opacity='0.8'/><polyline points='70,625 78,631 70,637' fill='none' stroke='white' stroke-width='1.5' stroke-opacity='0.65'/></svg>");
  -webkit-mask: var(--m) center / contain no-repeat;
          mask: var(--m) center / contain no-repeat;
