:is(section, figure) .pieCircle:nth-of-type(12n+4) { fill: var(--cat-4-texture, var(--cat-4-fill)) !important; }
:is(section, figure) .pieCircle:nth-of-type(12n+5) { fill: var(--cat-5-texture, var(--cat-5-fill)) !important; }
:is(section, figure) .pieCircle:nth-of-type(12n+6) { fill: var(--cat-6-texture, var(--cat-6-fill)) !important; }
:is(section, figure) .pieCircle:nth-of-type(12n+7) { fill: var(--cat-7-texture, var(--cat-7-fill)) !important; }
:is(section, figure) .pieCircle:nth-of-type(12n+8) { fill: var(--cat-8-texture, var(--cat-8-fill)) !important; }
:is(section, figure) .pieCircle:nth-of-type(12n+9) { fill: var(--cat-9-texture, var(--cat-9-fill)) !important; }
