:is(section, figure) g.leaf5x rect.treemapLeaf { fill: var(--cat-6-texture, var(--cat-6-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.leaf6x rect.treemapLeaf { fill: var(--cat-1-texture, var(--cat-1-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.leaf7x rect.treemapLeaf { fill: var(--cat-2-texture, var(--cat-2-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) rect.treemapLeaf { fill-opacity: 1 !important; }
:is(section, figure) .treemapLabel, :is(section, figure) .treemapNode text, :is(section, figure) .treemapLeaf text { fill: var(--cat-on-fill) !important; }

/* ── C4 ──
 * C4 has a hardcoded official palette (#08427B, #1168BD, etc.) that
 * ignores themeVariables. Override the box fills to band tokens.
 */
:is(section, figure) .person, :is(section, figure) .person_ext { fill: var(--cat-1-texture, var(--cat-1-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) .system, :is(section, figure) .system_ext { fill: var(--cat-2-texture, var(--cat-2-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) .container, :is(section, figure) .container_ext { fill: var(--cat-3-texture, var(--cat-3-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) .component, :is(section, figure) .component_ext { fill: var(--cat-4-texture, var(--cat-4-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) .person text, :is(section, figure) .system text, :is(section, figure) .container text, :is(section, figure) .component text,
:is(section, figure) .person_ext text, :is(section, figure) .system_ext text, :is(section, figure) .container_ext text, :is(section, figure) .component_ext text,
:is(section, figure) text.legendW, :is(section, figure) text.legendT { fill: var(--cat-on-fill) !important; }

/* C4 emits group classes like .person-man, .person-woman, .system-other,
 * .container-db, .component-queue, .boundary, etc. — wider than the bare
 * .person/.system/... selectors above. Catch the entire C4 cycle via
 * prefix match for inner unclassed <rect> elements.
 */
:is(section, figure) g[class*="person"] > rect, :is(section, figure) g[class*="system"] > rect,
:is(section, figure) g[class*="container"] > rect, :is(section, figure) g[class*="component"] > rect,
:is(section, figure) g[class*="boundary"] > rect, :is(section, figure) g[class*="node-bkg"] > rect {
  fill: var(--cat-1-texture, var(--cat-1-fill)) !important;
  stroke: var(--diagram-stroke) !important;
}
/* All text/lines/paths inside any C4 SVG (scoped via :has() so non-C4
 * trees aren't affected). */
:is(section, figure) svg:has(g[class*="person"]) text,
:is(section, figure) svg:has(g[class*="person"]) tspan,
:is(section, figure) svg:has(g[class*="system"]) text,
:is(section, figure) svg:has(g[class*="system"]) tspan {
  fill: var(--cat-on-fill) !important;
}
:is(section, figure) svg:has(g[class*="person"]) line,
:is(section, figure) svg:has(g[class*="person"]) path:not([class]),
:is(section, figure) svg:has(g[class*="system"]) line,
:is(section, figure) svg:has(g[class*="system"]) path:not([class]) {
  stroke: var(--diagram-line) !important;
}
:is(section, figure) text.legendW, :is(section, figure) text.legendT, :is(section, figure) .legend text, :is(section, figure) .legend tspan {
  fill: var(--cat-on-fill) !important;
}


/* ── VENN ──
 * Full-opacity band fills with strong stroke. Mermaid's default puts inline
 * style="fill-opacity: 0.1" on each circle path; that opacity inherits down
 * to text. Force fill-opacity:1 on path AND text so labels render at full
 * contrast.
 */
:is(section, figure) .venn-set-0, :is(section, figure) g.venn-set-0 path, :is(section, figure) .venn-set-0 path {
  fill: var(--cat-1-texture, var(--cat-1-fill)) !important;
  fill-opacity: 1 !important;
  stroke: var(--diagram-stroke) !important;
  stroke-width: 2 !important;
  stroke-opacity: 1 !important;
}
:is(section, figure) .venn-set-1, :is(section, figure) g.venn-set-1 path, :is(section, figure) .venn-set-1 path {
  fill: var(--cat-2-texture, var(--cat-2-fill)) !important;
  fill-opacity: 1 !important;
  stroke: var(--diagram-stroke) !important;
  stroke-width: 2 !important;
  stroke-opacity: 1 !important;
}
:is(section, figure) .venn-set-2, :is(section, figure) g.venn-set-2 path, :is(section, figure) .venn-set-2 path {
  fill: var(--cat-3-texture, var(--cat-3-fill)) !important;
  fill-opacity: 1 !important;
  stroke: var(--diagram-stroke) !important;
  stroke-width: 2 !important;
  stroke-opacity: 1 !important;
}
:is(section, figure) .venn-area text, :is(section, figure) text.label, :is(section, figure) text.label tspan, :is(section, figure) .label tspan {
  fill: var(--text-heading) !important;
  fill-opacity: 1 !important;
  paint-order: normal !important;
  stroke: none !important;
  stroke-width: 0 !important;
  font-weight: 500 !important;
}
/* Intersection regions read as "this is the shared region" without
 * competing with the circle colors. */
:is(section, figure) .venn-intersection path, :is(section, figure) g.venn-intersection path {
  fill: var(--diagram-stroke) !important;
  fill-opacity: 0.08 !important;
  stroke: var(--diagram-stroke) !important;
  stroke-width: 1.5 !important;
  stroke-dasharray: 4 3 !important;
  stroke-opacity: 0.7 !important;
}

/* ── ISHIKAWA ──
 * Branch heads use an internal palette baked into the renderer. Force
 * dark text via cascade; recolor connectors onto the brand line.
 */
:is(section, figure) .ishikawa-head-label { fill: var(--text-heading) !important; font-weight: 600 !important; }
:is(section, figure) .ishikawa-label.cause, :is(section, figure) .ishikawa-label.align { fill: var(--text-heading) !important; }
:is(section, figure) .ishikawa-spine, :is(section, figure) .ishikawa-arrow, :is(section, figure) .ishikawa-branch, :is(section, figure) .ishikawa-sub-branch {
  stroke: var(--diagram-line) !important;
}


/* ── JOURNEY · ACTOR FACES + STROKES ──
 * Journey draws actor avatars: a body circle (no class), a head circle.face
 * (cornsilk #FFF8DC by default), eyes, a path.mouth + line.mouth at #666666,
 * plus per-actor circle.actor-N marker pills filled with X11 named colors.
 * Force the entire avatar cluster onto the brand palette.
 *
 * Section/task strokes are also #666666 by default — section/task rules
 * above set fill but not stroke. Patch strokes by targeting the rect
 * directly with the actual emitted compound selectors.
 */
:is(section, figure) svg:has(path.mouth) circle:not(.face):not([class*="actor-"]) {
  fill: var(--diagram-line) !important;
  stroke: var(--diagram-line) !important;
}
:is(section, figure) circle.face {
  fill: var(--bg-alt) !important;
  stroke: var(--diagram-line) !important;
}
:is(section, figure) path.mouth { fill: var(--diagram-line) !important; }
:is(section, figure) path.mouth, :is(section, figure) line.mouth {
  stroke: var(--diagram-line) !important;
}
:is(section, figure) circle.actor-0 { fill: var(--cat-1-texture, var(--cat-1-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) circle.actor-1 { fill: var(--cat-2-texture, var(--cat-2-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) circle.actor-2 { fill: var(--cat-3-texture, var(--cat-3-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) circle.actor-3 { fill: var(--cat-4-texture, var(--cat-4-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) circle.actor-4 { fill: var(--cat-5-texture, var(--cat-5-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) circle.actor-5 { fill: var(--cat-6-texture, var(--cat-6-fill)) !important; stroke: var(--diagram-stroke) !important; }
/* Legend titles inherit actor color via <title> SVG element; force their
 * text-bearing tspans to read on the brand palette. */
:is(section, figure) .legend > title, :is(section, figure) title { fill: var(--text-heading) !important; }
:is(section, figure) rect.section0, :is(section, figure) rect.section1, :is(section, figure) rect.section2,
:is(section, figure) rect.task0, :is(section, figure) rect.task1, :is(section, figure) rect.task2,
:is(section, figure) rect[class*="section-type-"], :is(section, figure) rect[class*="task-type-"],
:is(section, figure) rect.journey-section, :is(section, figure) rect.task {
  stroke: var(--diagram-stroke) !important;
}

/* ── MINDMAP + TIMELINE CONNECTOR LINES ──
 * Both diagrams emit `line.node-line-N` (with index 0, 1, -1, …) using
 * Mermaid's internal lightened cScale, producing inconsistent off-band
 * strokes. Force all connector strokes to the deck's single line color
 * so connectors recede behind the colored nodes.
 */
:is(section, figure) line.node-line-, :is(section, figure) line[class*="node-line-"] {
  stroke: var(--diagram-line) !important;
  stroke-width: 1.5 !important;
}

/* ── SANKEY ──
 * Mermaid sankey hardcodes the Tableau-10 categorical palette for both
 * node fills and link gradients. The .node group has no per-cycle class
 * on the rect — Mermaid's only signal is element order inside
 * `<g class="nodes">`. Earlier this rule pinned every node to band-1
 * (reasoning: sankey distinguishes flows by width, not colour). That
 * left sankey reading as flat compared to treemap's six-colour
 * distribution.
 *
 * Cycle node fills through bands 1–8 via :nth-of-type() so each node
 * picks up a different palette slot — same principle as treemap. The
 * NODES carry the distinct colours; the link ribbons ("tentacles") are
 * connective tissue tied to c1 — the brand/lead colour every other
 * diagram opens on — at reduced opacity so overlapping flows stay
 * legible and the node bars remain the primary read. --cat-1-fill is a
 * light-dark() pair, so the ribbons flip with the canvas.
 */
:is(section, figure) g.nodes > g.node:nth-of-type(1)  > rect { fill: var(--cat-1-texture, var(--cat-1-fill))  !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.nodes > g.node:nth-of-type(2)  > rect { fill: var(--cat-2-texture, var(--cat-2-fill))  !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.nodes > g.node:nth-of-type(3)  > rect { fill: var(--cat-3-texture, var(--cat-3-fill))  !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.nodes > g.node:nth-of-type(4)  > rect { fill: var(--cat-4-texture, var(--cat-4-fill))  !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.nodes > g.node:nth-of-type(5)  > rect { fill: var(--cat-5-texture, var(--cat-5-fill))  !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.nodes > g.node:nth-of-type(6)  > rect { fill: var(--cat-6-texture, var(--cat-6-fill))  !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.nodes > g.node:nth-of-type(7)  > rect { fill: var(--cat-7-texture, var(--cat-7-fill))  !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.nodes > g.node:nth-of-type(8)  > rect { fill: var(--cat-8-texture, var(--cat-8-fill))  !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.nodes > g.node:nth-of-type(9)  > rect { fill: var(--cat-1-texture, var(--cat-1-fill))  !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.nodes > g.node:nth-of-type(10) > rect { fill: var(--cat-2-texture, var(--cat-2-fill))  !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) g.node-labels text, :is(section, figure) g.nodes text {
  fill: var(--cat-on-fill) !important;
}
:is(section, figure) g.link path, :is(section, figure) g.links path {
  /* Ribbons are connective tissue tied to c1 at reduced opacity — a flat COLOR,
   * NOT the texture channel: a pattern paint-server sampled through a thin,
   * variable-width stroke reads as speckle, not a tint. So stay on --cat-1-fill. */
  stroke: var(--cat-1-fill) !important;
  stroke-opacity: 0.4 !important;
  fill: none !important;
}

/* ── PACKET ──
 * Packet hardcodes #EFEFEF rect fills and #000000 text. Pull onto the
 * brand band-1 + paired dark text.
 */
:is(section, figure) rect.packetBlock {
  fill: var(--cat-1-texture, var(--cat-1-fill)) !important;
  stroke: var(--diagram-stroke) !important;
}
:is(section, figure) text.packetLabel, :is(section, figure) text.packetByte, :is(section, figure) text.packetTitle {
  fill: var(--cat-on-fill) !important;
}

/* ── ARCHITECTURE ──
 * The architecture-beta renderer draws each service as an outer rect
 * with inline style="fill:#087ebf" (a hardcoded Mermaid blue), inside
 * which white icon glyphs are drawn with inline stroke:#fff. Replace
 * service fills with band-1; re-skin glyphs to read on the now-pale
 * background. !important wins over inline styles per CSS spec, so the
 * unclassed inline-styled rects are reachable.
 */
:is(section, figure) g.architecture-groups rect:not(.background):not(.node-bkg),
:is(section, figure) g.architecture-services rect:not(.background):not(.node-bkg),
:is(section, figure) g.architecture-service rect:not(.background):not(.node-bkg) {
  fill: var(--cat-1-texture, var(--cat-1-fill)) !important;
  stroke: var(--diagram-stroke) !important;
}
:is(section, figure) g.architecture-groups path.edge,
:is(section, figure) g.architecture-edges path.edge {
  stroke: var(--diagram-line) !important;
  stroke-width: 1.5 !important;
}
/* Glyphs inside services: re-skin from white to brand stroke so they
 * read on the pale fill. */
:is(section, figure) g.architecture-groups svg path,
:is(section, figure) g.architecture-groups svg circle,
:is(section, figure) g.architecture-groups svg ellipse,
:is(section, figure) g.architecture-groups svg line,
:is(section, figure) g.architecture-service svg path,
:is(section, figure) g.architecture-service svg circle,
:is(section, figure) g.architecture-service svg ellipse,
:is(section, figure) g.architecture-service svg line {
  fill: var(--diagram-stroke) !important;
  stroke: var(--diagram-stroke) !important;
}
:is(section, figure) g.architecture-groups svg path[style*="fill: none"],
:is(section, figure) g.architecture-groups svg circle[style*="fill: none"],
:is(section, figure) g.architecture-groups svg ellipse[style*="fill: none"],
:is(section, figure) g.architecture-groups svg line[style*="fill: none"],
:is(section, figure) g.architecture-service svg path[style*="fill: none"],
:is(section, figure) g.architecture-service svg circle[style*="fill: none"],
:is(section, figure) g.architecture-service svg ellipse[style*="fill: none"],
:is(section, figure) g.architecture-service svg line[style*="fill: none"] {
  fill: none !important;
}
:is(section, figure) g.architecture-groups text, :is(section, figure) g.architecture-groups tspan,
:is(section, figure) g.architecture-service text, :is(section, figure) g.architecture-service tspan {
  fill: var(--cat-on-fill) !important;
}

/* ── ER ROW-RECT EVEN/ODD ──
 * The ER renderer alternates row backgrounds via .row-rect-even and
 * .row-rect-odd <path> elements. Mermaid 11 derives one of them by
 * lightening the primary, producing an off-palette stray. Pin both
 * bands to palette tokens for deterministic output.
 */
:is(section, figure) g.row-rect-even > path { fill: var(--bg-alt) !important; }
:is(section, figure) g.row-rect-odd > path  { fill: var(--bg) !important; }

/* ── EDGE MARKERS = EDGE COLOUR (style, both modes) ──
 * Arrowheads and crow's-foot relationship markers render UNFILLED by default
 * in some diagram types — notably ER relationship terminals, which come out as
 * thin open outlines. Fill every marker with the flipping edge colour so each
 * connector terminal reads as solidly as its line (matching flowchart/state
 * arrowheads). Not a dark-flip hack: --diagram-line flips with the canvas, so this
 * is identical in both schemes — it's a deliberate "solid terminals" style.
 * (Edge LINE strokes and arrowheads are otherwise baked correctly by the
 * lineColor themeVar via dual-render; only the ER marker FILL needs this.) */
:is(section, figure) .marker,
:is(section, figure) .marker path,
:is(section, figure) .arrowMarkerPath,
:is(section, figure) .arrowheadPath {
  fill: var(--diagram-line) !important;
  stroke: var(--diagram-line) !important;
}

/* ── JOURNEY AXIS + TASK CONNECTORS (canvas-borne structural lines) ──
 * The journey axis line and the dashed task→face connectors emit as inline
 * stroke="black" — NOT a themeVar, so dual-render can't bake them to the dark
 * scheme. Re-point at the flipping --diagram-line. Scoped by aria-roledescription
 * and excludes `.mouth` (the smiley strokes on the mood faces). The mood-face
 * fill/eyes/mouth are handled by the journey block above. */
:is(section, figure) svg[aria-roledescription="journey"] line:not(.mouth) {
  stroke: var(--diagram-line) !important;
}

/* ── TIMELINE AXIS + PERIOD DIVIDERS ──
 * The timeline's section/period divider lines (`.node-line-*`) and the
 * unclassed axis line (inline stroke="black") bake dark, so the spine vanishes
 * on a dark slide. Re-point every timeline line at --diagram-line. */
:is(section, figure) svg[aria-roledescription="timeline"] line {
  stroke: var(--diagram-line) !important;
}

/* ── TREEVIEW LABELS + LINES (beta type — hardcoded black) ──
 * treeView-beta bakes `.treeView-node-label { fill: black }` and
 * `.treeView-node-line { stroke: black }` as LITERAL black in its own injected
 * <style> block — it ignores the labelColor/lineColor themeVariables we inject
 * (a beta-type gap, despite its docs claiming those vars). So on a dark slide
 * both the file labels and the tree connectors vanish. Re-point at the flipping
 * tokens: dark on a light canvas (unchanged from baked black), light on a dark
 * canvas (now visible). The !important beats Mermaid's un-important inline rule. */
:is(section, figure) .treeView-node-label { fill: var(--cat-on-fill) !important; }
:is(section, figure) .treeView-node-line  { stroke: var(--diagram-line) !important; }

/* ── MINDMAP BRANCH EDGES (per-section colour, brightened) ──
 * Mindmap draws each branch in its section's cScale colour (themeVar
 * cScale0-11 → --cN-dark). Those bake at the light branch and, more to the
 * point, the saturated --cN-dark tone reads dark on a dark canvas. Re-point
 * each `.section-edge-N` at the matching category, brightened via color-mix
 * toward the flipping ink (lighter on a dark slide, slightly deeper on a light
 * slide) so the branches stay COLOURED and read brightly in both modes.
 * Scoped to svg.mindmapDiagram so no other diagram's edges are touched.
 * (Restores the per-branch colour an earlier over-broad edge rule flattened.)
 * Section indices mirror the mindmap-node fill mapping below: 0→c1 … 5→c6. */
:is(section, figure) svg.mindmapDiagram .section-edge--1,
:is(section, figure) svg.mindmapDiagram .section-edge-0 { stroke: color-mix(in srgb, var(--cat-1-mark) 78%, var(--cat-on-fill)) !important; }
:is(section, figure) svg.mindmapDiagram .section-edge-1 { stroke: color-mix(in srgb, var(--cat-2-mark) 78%, var(--cat-on-fill)) !important; }
:is(section, figure) svg.mindmapDiagram .section-edge-2 { stroke: color-mix(in srgb, var(--cat-3-mark) 78%, var(--cat-on-fill)) !important; }
:is(section, figure) svg.mindmapDiagram .section-edge-3 { stroke: color-mix(in srgb, var(--cat-4-mark) 78%, var(--cat-on-fill)) !important; }
:is(section, figure) svg.mindmapDiagram .section-edge-4 { stroke: color-mix(in srgb, var(--cat-5-mark) 78%, var(--cat-on-fill)) !important; }
:is(section, figure) svg.mindmapDiagram .section-edge-5 { stroke: color-mix(in srgb, var(--cat-6-mark) 78%, var(--cat-on-fill)) !important; }
:is(section, figure) svg.mindmapDiagram .section-edge-6 { stroke: color-mix(in srgb, var(--cat-1-mark) 78%, var(--cat-on-fill)) !important; }
:is(section, figure) svg.mindmapDiagram .section-edge-7 { stroke: color-mix(in srgb, var(--cat-2-mark) 78%, var(--cat-on-fill)) !important; }


/* ── TIMELINE diagram overrides (Mermaid) — relocated from the retired
 * timeline component on 2026-06-07 when timeline merged into list-steps.
 * These target Mermaid-emitted SVG (.timeline-node, .eventWrapper), not the
 * list-steps.timeline layout variant. */
/* ── TIMELINE BAND CYCLE (shifted) ──
 * Mermaid's timeline renderer uses `f = r % h - 1` for its section index,
 * so the FIRST timeline section gets `section--1`, the second gets
 * `section-0`, and so on. The general band-cycle rules above pin BOTH
 * `section--1` AND `section-0` to band-1 (because that's the correct map
 * for mindmap and other diagrams where `section-0` is the first), which
 * means every timeline renders its first two sections in the same band.
 * Visible on the gallery's Phase 01 / Phase 02 (both blue) and on
 * diagram-tokens' Discover / Frame (both blue) where the deck's footer
 * literally claims "8 sections cycling --c1..8-light".
 *
 * Timeline groups wrap each section in <g class="timeline-node section-N">.
 * Re-pin the cycle one band up for `.timeline-node` only so timeline
 * sections cycle c1-light (section--1), c2-light (section-0), c3-light
 * (section-1), …, c12-light (section-10). Higher specificity than the
 * generic `.section-N` rules above wins automatically. Other diagram
 * types that use bare `.section-N` (mindmap, kanban via .cluster) keep
 * their existing mappings.
 */
:is(section, figure) .timeline-node.section--1 rect, :is(section, figure) .timeline-node.section--1 path, :is(section, figure) .timeline-node.section--1 circle { fill: var(--cat-1-texture, var(--cat-1-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) .timeline-node.section--1 text, :is(section, figure) .timeline-node.section--1 tspan, :is(section, figure) .timeline-node.section--1 span { fill: var(--cat-on-fill) !important; color: var(--cat-on-fill) !important; }
:is(section, figure) .timeline-node.section-0 rect, :is(section, figure) .timeline-node.section-0 path, :is(section, figure) .timeline-node.section-0 circle { fill: var(--cat-2-texture, var(--cat-2-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) .timeline-node.section-0 text, :is(section, figure) .timeline-node.section-0 tspan, :is(section, figure) .timeline-node.section-0 span { fill: var(--cat-on-fill) !important; color: var(--cat-on-fill) !important; }
:is(section, figure) .timeline-node.section-1 rect, :is(section, figure) .timeline-node.section-1 path, :is(section, figure) .timeline-node.section-1 circle { fill: var(--cat-3-texture, var(--cat-3-fill)) !important; stroke: var(--diagram-stroke) !important; }
:is(section, figure) .timeline-node.section-1 text, :is(section, figure) .timeline-node.section-1 tspan, :is(section, figure) .timeline-node.section-1 span { fill: var(--cat-on-fill) !important; color: var(--cat-on-fill) !important; }
